const ORIG_QUESTIONS = [{"topic": "Kidney Disease", "q": "Which type of acute kidney injury is caused by decreased blood flow to the kidneys?", "opts": ["Prerenal AKI", "Intrarenal AKI", "Postrenal AKI", "Chronic AKI"], "ans": 0, "expl": "Prerenal AKI results from hypoperfusion of the kidneys due to conditions like hypotension, heart failure, or volume depletion.", "obj": 1}, {"topic": "Kidney Disease", "q": "What is the hallmark finding in acute tubular necrosis (ATN)?", "opts": ["Proteinuria", "Muddy brown casts in urine", "Hematuria", "Glucosuria"], "ans": 1, "expl": "Muddy brown granular casts are characteristic of ATN, indicating tubular epithelial cell damage and sloughing.", "obj": 1}, {"topic": "Kidney Disease", "q": "Which stage of CKD corresponds to a GFR of 15-29 mL/min/1.73m\u00b2?", "opts": ["Stage 2", "Stage 3", "Stage 4", "Stage 5"], "ans": 2, "expl": "CKD Stage 4 is defined by GFR 15-29 mL/min/1.73m\u00b2, indicating severe kidney damage and preparation for renal replacement therapy.", "obj": 1}, {"topic": "Kidney Disease", "q": "What electrolyte abnormality is most commonly associated with advanced CKD?", "opts": ["Hyperkalemia", "Hypokalemia", "Hypercalcemia", "Hypophosphatemia"], "ans": 0, "expl": "Hyperkalemia occurs in advanced CKD due to decreased potassium excretion by damaged nephrons.", "obj": 1}, {"topic": "Kidney Disease", "q": "Which condition is characterized by heavy proteinuria (>3.5g/day), hypoalbuminemia, and edema?", "opts": ["Nephritic syndrome", "Nephrotic syndrome", "Acute glomerulonephritis", "Pyelonephritis"], "ans": 1, "expl": "Nephrotic syndrome presents with massive proteinuria, hypoalbuminemia, edema, and hyperlipidemia due to glomerular permeability changes.", "obj": 1}, {"topic": "Kidney Disease", "q": "What is the primary cause of postrenal AKI?", "opts": ["Glomerulonephritis", "Urinary tract obstruction", "Acute tubular necrosis", "Renal artery stenosis"], "ans": 1, "expl": "Postrenal AKI results from obstruction of urine flow, such as from kidney stones, tumors, or prostate enlargement.", "obj": 1}, {"topic": "Kidney Disease", "q": "Which medication class should be used cautiously in patients with CKD due to nephrotoxicity risk?", "opts": ["ACE inhibitors", "NSAIDs", "Beta-blockers", "Calcium channel blockers"], "ans": 1, "expl": "NSAIDs can cause vasoconstriction of afferent arterioles and worsen kidney function, especially in CKD patients.", "obj": 5}, {"topic": "Kidney Disease", "q": "What is the most common cause of glomerulonephritis worldwide?", "opts": ["Diabetic nephropathy", "IgA nephropathy", "Lupus nephritis", "Post-streptococcal GN"], "ans": 1, "expl": "IgA nephropathy (Berger disease) is the most common primary glomerulonephritis globally.", "obj": 1}, {"topic": "Kidney Disease", "q": "Which finding distinguishes nephritic from nephrotic syndrome?", "opts": ["Proteinuria", "Hematuria with RBC casts", "Edema", "Hypoalbuminemia"], "ans": 1, "expl": "Nephritic syndrome is characterized by hematuria with RBC casts, hypertension, and mild-to-moderate proteinuria.", "obj": 1}, {"topic": "Kidney Disease", "q": "What is the target blood pressure for most patients with CKD and proteinuria?", "opts": ["<140/90 mmHg", "<130/80 mmHg", "<120/70 mmHg", "<150/90 mmHg"], "ans": 1, "expl": "Current guidelines recommend BP <130/80 mmHg for CKD patients, especially those with proteinuria.", "obj": 2}, {"topic": "Kidney Disease", "q": "Which hormone deficiency contributes to anemia in CKD?", "opts": ["Insulin", "Erythropoietin", "Aldosterone", "Parathyroid hormone"], "ans": 1, "expl": "Damaged kidneys produce less erythropoietin, leading to decreased red blood cell production and anemia.", "obj": 1}, {"topic": "Kidney Disease", "q": "What is the primary treatment for hyperkalemia in a patient with peaked T waves on ECG?", "opts": ["Oral potassium binders", "IV calcium gluconate", "Dietary restriction", "Loop diuretics"], "ans": 1, "expl": "IV calcium gluconate stabilizes cardiac membranes immediately in severe hyperkalemia with ECG changes.", "obj": 2}, {"topic": "Kidney Disease", "q": "Which type of dialysis uses the peritoneal membrane as a filter?", "opts": ["Hemodialysis", "Peritoneal dialysis", "Continuous venovenous hemofiltration", "Plasmapheresis"], "ans": 1, "expl": "Peritoneal dialysis uses the peritoneal membrane for solute and fluid exchange via instilled dialysate.", "obj": 3}, {"topic": "Kidney Disease", "q": "What is the most accurate indicator of kidney function?", "opts": ["Serum creatinine", "Blood urea nitrogen", "Glomerular filtration rate (GFR)", "Urine output"], "ans": 2, "expl": "GFR is the best overall measure of kidney function, estimating filtration capacity per minute.", "obj": 1}, {"topic": "Kidney Disease", "q": "Which condition is a common cause of prerenal AKI in hospitalized patients?", "opts": ["Sepsis", "Glomerulonephritis", "Kidney stones", "Polycystic kidney disease"], "ans": 0, "expl": "Sepsis causes vasodilation and hypotension, leading to renal hypoperfusion and prerenal AKI.", "obj": 1}, {"topic": "Kidney Disease", "q": "What dietary modification is typically recommended for CKD patients with hyperphosphatemia?", "opts": ["High protein diet", "Phosphate restriction", "High potassium diet", "Low calcium intake"], "ans": 1, "expl": "Phosphate restriction and phosphate binders help control hyperphosphatemia in CKD.", "obj": 4}, {"topic": "Kidney Disease", "q": "Which finding suggests acute glomerulonephritis?", "opts": ["Muddy brown casts", "RBC casts and dysmorphic RBCs", "WBC casts", "Hyaline casts"], "ans": 1, "expl": "RBC casts and dysmorphic red blood cells indicate glomerular bleeding, characteristic of glomerulonephritis.", "obj": 1}, {"topic": "Kidney Disease", "q": "What is the definition of oliguria in adults?", "opts": ["<500 mL/day", "<400 mL/day", "<300 mL/day", "<100 mL/day"], "ans": 1, "expl": "Oliguria is defined as urine output less than 400 mL per day in adults.", "obj": 1}, {"topic": "Kidney Disease", "q": "Which complication is associated with rapid correction of hyponatremia in CKD patients?", "opts": ["Cerebral edema", "Osmotic demyelination syndrome", "Cardiac arrest", "Seizures"], "ans": 1, "expl": "Rapid sodium correction can cause osmotic demyelination syndrome (central pontine myelinolysis).", "obj": 1}, {"topic": "Kidney Disease", "q": "What is the primary mechanism of metabolic acidosis in CKD?", "opts": ["Increased acid production", "Decreased acid excretion", "Bicarbonate overproduction", "Respiratory compensation"], "ans": 1, "expl": "CKD impairs the kidney's ability to excrete hydrogen ions and regenerate bicarbonate, causing metabolic acidosis.", "obj": 1}, {"topic": "Hemodialysis", "q": "What is the primary mechanism by which solutes move across a dialyzer membrane during hemodialysis?", "opts": ["Ultrafiltration", "Diffusion", "Convection", "Osmosis"], "ans": 1, "expl": "Diffusion is the primary mechanism of solute clearance in hemodialysis, where solutes move from an area of higher concentration (blood) to lower concentration (dialysate) across a semipermeable membrane.", "obj": 3}, {"topic": "Hemodialysis", "q": "Which vascular access type has the lowest risk of infection and longest patency for chronic hemodialysis?", "opts": ["Tunneled dialysis catheter", "Arteriovenous graft", "Arteriovenous fistula", "Peripheral IV line"], "ans": 2, "expl": "Arteriovenous fistulas (AVF) have the lowest infection rate, best long-term patency, and are considered the gold standard for chronic hemodialysis access.", "obj": 6}, {"topic": "Hemodialysis", "q": "What does Kt/V measure in hemodialysis?", "opts": ["Blood flow rate", "Dialysis adequacy", "Membrane permeability", "Ultrafiltration volume"], "ans": 1, "expl": "Kt/V is a dimensionless number used to quantify hemodialysis adequacy, where K is dialyzer clearance, t is treatment time, and V is volume of distribution of urea.", "obj": 3}, {"topic": "Hemodialysis", "q": "During hemodialysis, ultrafiltration primarily removes which of the following?", "opts": ["Large proteins", "Excess fluid", "Red blood cells", "Glucose"], "ans": 1, "expl": "Ultrafiltration is the process of removing excess fluid from the blood by applying hydrostatic pressure across the dialyzer membrane, forcing water and small solutes through.", "obj": 3}, {"topic": "Hemodialysis", "q": "Which anticoagulant is most commonly used during routine hemodialysis treatments?", "opts": ["Warfarin", "Heparin", "Aspirin", "Clopidogrel"], "ans": 1, "expl": "Unfractionated heparin is the most commonly used anticoagulant during hemodialysis to prevent clotting in the extracorporeal circuit.", "obj": 5}, {"topic": "Hemodialysis", "q": "What is the most common intradialytic complication during hemodialysis?", "opts": ["Air embolism", "Hypotension", "Seizures", "Hemolysis"], "ans": 1, "expl": "Intradialytic hypotension is the most frequent complication, occurring in 20-30% of treatments, often due to rapid fluid removal or autonomic dysfunction.", "obj": 3}, {"topic": "Hemodialysis", "q": "Which dialysate component is typically set at 135-145 mEq/L?", "opts": ["Potassium", "Calcium", "Sodium", "Bicarbonate"], "ans": 2, "expl": "Dialysate sodium concentration is typically maintained between 135-145 mEq/L to match physiologic serum sodium levels and prevent osmotic shifts.", "obj": 3}, {"topic": "Hemodialysis", "q": "What is convection in the context of hemodialysis?", "opts": ["Solute movement due to concentration gradient", "Solute movement with water flow across membrane", "Movement of water only", "Movement of proteins"], "ans": 1, "expl": "Convection is the movement of solutes across the membrane along with water flow (solvent drag), particularly important for middle molecule clearance.", "obj": 3}, {"topic": "Hemodialysis", "q": "Which vascular access requires the longest maturation time before use?", "opts": ["Tunneled catheter", "Arteriovenous graft", "Arteriovenous fistula", "Non-tunneled catheter"], "ans": 2, "expl": "Arteriovenous fistulas typically require 3-6 months to mature before they can be safely used for dialysis, longer than grafts or catheters.", "obj": 3}, {"topic": "Hemodialysis", "q": "What is the recommended minimum Kt/V value for adequate hemodialysis?", "opts": ["0.8", "1.2", "2.0", "3.5"], "ans": 1, "expl": "KDOQI guidelines recommend a minimum single-pool Kt/V of 1.2 per dialysis session to ensure adequate dialysis delivery.", "obj": 7}, {"topic": "Hemodialysis", "q": "Which symptom is most characteristic of dialysis disequilibrium syndrome?", "opts": ["Hypertension", "Neurological symptoms including headache and confusion", "Muscle cramps", "Fever"], "ans": 1, "expl": "Dialysis disequilibrium syndrome presents with neurological symptoms (headache, nausea, confusion, seizures) due to rapid solute removal causing cerebral edema.", "obj": 3}, {"topic": "Hemodialysis", "q": "What is the primary cause of muscle cramps during hemodialysis?", "opts": ["Hyperkalemia", "Rapid ultrafiltration and volume depletion", "High dialysate calcium", "Excessive anticoagulation"], "ans": 1, "expl": "Muscle cramps during dialysis are commonly caused by rapid fluid removal leading to volume depletion and changes in muscle perfusion.", "obj": 3}, {"topic": "Hemodialysis", "q": "Which air embolism symptom would appear FIRST if air enters the venous line?", "opts": ["Chest pain and dyspnea", "Bradycardia", "Hypertension", "Fever"], "ans": 0, "expl": "Air embolism typically presents first with sudden chest pain, dyspnea, and cough as air reaches the pulmonary circulation.", "obj": 3}, {"topic": "Hemodialysis", "q": "What is the function of the dialyzer membrane's pore size?", "opts": ["Determines blood flow rate", "Controls which molecules can pass through", "Sets dialysate temperature", "Regulates anticoagulation"], "ans": 1, "expl": "Membrane pore size determines the molecular weight cutoff, controlling which solutes can be cleared while retaining larger proteins like albumin.", "obj": 3}, {"topic": "Hemodialysis", "q": "Which dialysate temperature is typically used to reduce intradialytic hypotension?", "opts": ["39\u00b0C", "35-36\u00b0C (cool dialysate)", "42\u00b0C", "Room temperature"], "ans": 1, "expl": "Cool dialysate (35-36\u00b0C) promotes peripheral vasoconstriction and improves hemodynamic stability, reducing hypotension episodes.", "obj": 3}, {"topic": "Hemodialysis", "q": "What is the primary advantage of high-flux dialyzers?", "opts": ["Lower cost", "Better clearance of middle molecules", "Reduced anticoagulation needs", "Shorter treatment time"], "ans": 1, "expl": "High-flux dialyzers have larger pores that allow better clearance of middle molecular weight toxins like beta-2 microglobulin.", "obj": 3}, {"topic": "Hemodialysis", "q": "Which access complication is characterized by a thrill that is weak or absent?", "opts": ["Infection", "Thrombosis", "Aneurysm formation", "Steal syndrome"], "ans": 1, "expl": "A weak or absent thrill suggests thrombosis or stenosis of the vascular access, requiring immediate evaluation.", "obj": 1}, {"topic": "Hemodialysis", "q": "What is the purpose of bicarbonate in the dialysate?", "opts": ["To lower blood pressure", "To correct metabolic acidosis", "To prevent clotting", "To reduce potassium"], "ans": 1, "expl": "Bicarbonate in dialysate helps correct the metabolic acidosis common in ESRD patients by diffusing into the blood and buffering acids.", "obj": 3}, {"topic": "Hemodialysis", "q": "Which patient position is recommended if an air embolism is suspected?", "opts": ["Supine flat", "Left lateral decubitus with head down", "Sitting upright", "Prone"], "ans": 1, "expl": "Left lateral decubitus (Durant's maneuver) with head down traps air in the right ventricle, preventing it from entering pulmonary circulation.", "obj": 2}, {"topic": "Hemodialysis", "q": "What is the typical blood flow rate range for maintenance hemodialysis?", "opts": ["50-100 mL/min", "200-500 mL/min", "600-800 mL/min", "1000-1200 mL/min"], "ans": 1, "expl": "Standard blood flow rates for hemodialysis range from 200-500 mL/min, with 300-400 mL/min being most common for adequate clearance.", "obj": 3}, {"topic": "Peritoneal Dialysis", "q": "Which peritoneal dialysis catheter type is placed using a laparoscopic approach and has a pre-sternal exit site?", "opts": ["Tenckhoff catheter", "Presternal catheter", "Moncrief-Popovich catheter", "Fluoroscopically placed catheter"], "ans": 1, "expl": "Presternal catheters are surgically placed with the exit site on the chest wall, beneficial for patients with abdominal ostomies or obesity.", "obj": 3}, {"topic": "Peritoneal Dialysis", "q": "What is the recommended frequency for exit-site care in stable peritoneal dialysis patients?", "opts": ["Daily", "Weekly", "After each exchange", "Only when drainage is noted"], "ans": 1, "expl": "Exit-site care is typically performed weekly in stable patients, though frequency may increase if drainage or infection is present.", "obj": 3}, {"topic": "Peritoneal Dialysis", "q": "Which organism is the most common cause of peritoneal dialysis-associated peritonitis?", "opts": ["Escherichia coli", "Staphylococcus epidermidis", "Pseudomonas aeruginosa", "Candida albicans"], "ans": 1, "expl": "Coagulase-negative staphylococci, particularly S. epidermidis, are the most frequent pathogens in PD peritonitis due to skin flora contamination.", "obj": 6}, {"topic": "Peritoneal Dialysis", "q": "What does a high transporter status on the Peritoneal Equilibration Test (PET) indicate?", "opts": ["Slow solute clearance requiring longer dwells", "Rapid solute equilibration with poor ultrafiltration on long dwells", "Normal membrane function", "Membrane failure requiring transplant"], "ans": 1, "expl": "High transporters rapidly equilibrate solutes but lose osmotic gradient quickly, leading to poor UF on long dwells; they benefit from shorter cycles.", "obj": 3}, {"topic": "Peritoneal Dialysis", "q": "Which dialysate solution is preferred for patients with hyperkalemia?", "opts": ["Standard lactate-buffered solution", "Potassium-free solution", "Bicarbonate-buffered solution", "Icodextrin solution"], "ans": 1, "expl": "Potassium-free dialysate helps correct hyperkalemia by promoting potassium removal across the peritoneal membrane.", "obj": 3}, {"topic": "Peritoneal Dialysis", "q": "What is the primary mechanism of ultrafiltration in peritoneal dialysis?", "opts": ["Diffusion", "Osmosis", "Convection", "Active transport"], "ans": 1, "expl": "Ultrafiltration occurs primarily through osmosis, driven by the osmotic gradient created by glucose or icodextrin in the dialysate.", "obj": 3}, {"topic": "Peritoneal Dialysis", "q": "CAPD stands for:", "opts": ["Continuous Ambulatory Peritoneal Dialysis", "Cyclic Automated Peritoneal Dialysis", "Chronic Ambulatory Peritoneal Dialysis", "Continuous Automated Peritoneal Dialysis"], "ans": 0, "expl": "CAPD is Continuous Ambulatory Peritoneal Dialysis, performed manually throughout the day without a machine.", "obj": 3}, {"topic": "Peritoneal Dialysis", "q": "Which symptom is most indicative of peritonitis in a PD patient?", "opts": ["Mild abdominal discomfort", "Cloudy effluent with abdominal pain", "Increased ultrafiltration volume", "Decreased appetite alone"], "ans": 1, "expl": "Cloudy effluent combined with abdominal pain is the hallmark presentation of peritonitis and requires immediate evaluation.", "obj": 6}, {"topic": "Peritoneal Dialysis", "q": "What is the first-line empiric antibiotic coverage for PD peritonitis?", "opts": ["Gram-positive only", "Gram-negative only", "Both Gram-positive and Gram-negative", "Antifungal only"], "ans": 2, "expl": "Empiric therapy must cover both Gram-positive (e.g., vancomycin or cephalosporin) and Gram-negative organisms (e.g., ceftazidime or aminoglycoside).", "obj": 5}, {"topic": "Peritoneal Dialysis", "q": "Ultrafiltration failure is defined as:", "opts": ["Inability to achieve target solute clearance", "Persistent inability to remove adequate fluid volume", "Complete loss of peritoneal membrane function", "Catheter mechanical failure"], "ans": 1, "expl": "UF failure is the inability to remove sufficient fluid despite appropriate osmotic agents, often due to membrane changes or high transporter status.", "obj": 3}, {"topic": "Peritoneal Dialysis", "q": "Which nutrient requires careful monitoring in PD patients due to glucose absorption from dialysate?", "opts": ["Protein", "Potassium", "Calories/carbohydrates", "Vitamin D"], "ans": 2, "expl": "Significant glucose absorption from dialysate can contribute 100-300+ calories daily, affecting glycemic control and weight.", "obj": 3}, {"topic": "Peritoneal Dialysis", "q": "What is the recommended protein intake for stable PD patients?", "opts": ["0.6-0.8 g/kg/day", "1.0-1.2 g/kg/day", "1.5-2.0 g/kg/day", "No restriction needed"], "ans": 1, "expl": "PD patients need 1.0-1.2 g/kg/day due to protein losses in dialysate (5-15g/day) and catabolic state of uremia.", "obj": 4}, {"topic": "Peritoneal Dialysis", "q": "Which PD modality uses a cycler machine primarily during nighttime sleep?", "opts": ["CAPD", "CCPD", "Tidal PD", "Intermittent PD"], "ans": 1, "expl": "CCPD (Continuous Cyclic Peritoneal Dialysis) uses a cycler at night with a daytime dwell, offering more freedom during waking hours.", "obj": 3}, {"topic": "Peritoneal Dialysis", "q": "What is the purpose of the Peritoneal Equilibration Test (PET)?", "opts": ["To measure residual kidney function", "To classify peritoneal membrane transport characteristics", "To diagnose peritonitis", "To assess catheter patency"], "ans": 1, "expl": "PET classifies patients as high, high-average, low-average, or low transporters to guide prescription optimization.", "obj": 6}, {"topic": "Peritoneal Dialysis", "q": "Which catheter complication presents as leakage of dialysate around the exit site?", "opts": ["Catheter migration", "Exit-site infection", "Pericatheter leak", "Omental wrapping"], "ans": 2, "expl": "Pericatheter leaks occur early post-placement or from increased intra-abdominal pressure, causing fluid to track around the catheter.", "obj": 6}, {"topic": "Peritoneal Dialysis", "q": "Icodextrin solution is particularly useful for:", "opts": ["Patients with peritonitis", "Long daytime dwells in high transporters", "Emergency hyperkalemia treatment", "Patients with fungal infections"], "ans": 1, "expl": "Icodextrin provides sustained osmotic gradient for long dwells, ideal for high transporters who lose glucose-based UF quickly.", "obj": 6}, {"topic": "Peritoneal Dialysis", "q": "What is the minimum dwell time typically recommended for adequate exchange in CAPD?", "opts": ["15 minutes", "30 minutes", "2-4 hours", "8 hours"], "ans": 2, "expl": "Standard CAPD exchanges use 2-4 hour dwells to balance solute clearance and ultrafiltration efficiency.", "obj": 3}, {"topic": "Peritoneal Dialysis", "q": "Which finding suggests catheter tip migration on imaging?", "opts": ["Catheter tip in the pelvis", "Catheter tip in the upper abdomen or subphrenic space", "Cuff visible at exit site", "Normal catheter trajectory"], "ans": 1, "expl": "Migration to the upper abdomen can cause inflow pain and drainage problems; the tip should rest in the pelvis.", "obj": 3}, {"topic": "Peritoneal Dialysis", "q": "Encapsulating Peritoneal Sclerosis (EPS) is characterized by:", "opts": ["Reversible membrane inflammation", "Fibrotic encapsulation of bowel with obstruction", "Temporary UF failure", "Mild exit-site infection"], "ans": 1, "expl": "EPS is a rare but serious complication with thick fibrous membrane formation around intestines, causing obstruction and requiring surgical intervention.", "obj": 6}, {"topic": "Peritoneal Dialysis", "q": "What is the role of heparin in PD dialysate?", "opts": ["Anticoagulation for systemic effect", "Prevention of fibrin clot formation in catheter", "Treatment of peritonitis", "Enhancement of ultrafiltration"], "ans": 1, "expl": "Heparin (500-1000 units/L) prevents fibrin formation in the catheter or effluent without causing systemic anticoagulation.", "obj": 6}, {"topic": "Transplant", "q": "Which type of kidney donor typically provides the best long-term graft survival?", "opts": ["Living related donor", "Deceased donor after brain death", "Deceased donor after circulatory death", "Living unrelated donor"], "ans": 0, "expl": "Living related donors generally provide the best outcomes due to better HLA matching, shorter cold ischemia time, and the ability to schedule transplantation electively before the recipient requires dialysis.", "obj": 3}, {"topic": "Transplant", "q": "What is the primary mechanism of hyperacute rejection?", "opts": ["T-cell mediated cytotoxicity", "Pre-formed antibodies against donor HLA antigens", "Chronic antibody-mediated injury", "Drug toxicity from calcineurin inhibitors"], "ans": 1, "expl": "Hyperacute rejection occurs within minutes to hours due to pre-existing antibodies in the recipient that react against donor antigens, causing immediate thrombosis and graft necrosis. This is why crossmatch testing is critical before transplantation.", "obj": 5}, {"topic": "Transplant", "q": "Which immunosuppressive medication is most commonly associated with nephrotoxicity?", "opts": ["Mycophenolate mofetil", "Prednisone", "Tacrolimus", "Sirolimus"], "ans": 2, "expl": "Tacrolimus and other calcineurin inhibitors cause dose-dependent nephrotoxicity through vasoconstriction of afferent arterioles. Therapeutic drug monitoring is essential to balance rejection prevention with kidney protection.", "obj": 5}, {"topic": "Transplant", "q": "What is the typical time frame for acute cellular rejection to occur post-transplant?", "opts": ["Within 24 hours", "Days to weeks, most common in first 3-6 months", "After 5 years", "Only during pregnancy"], "ans": 1, "expl": "Acute cellular rejection most commonly occurs within the first 3-6 months post-transplant when immunosuppression levels may be subtherapeutic or during medication adjustments. It can occur at any time with inadequate immunosuppression.", "obj": 1}, {"topic": "Transplant", "q": "Which virus is most concerning for post-transplant infection in seronegative recipients receiving organs from seropositive donors?", "opts": ["Hepatitis A virus", "Cytomegalovirus (CMV)", "Rhinovirus", "Parvovirus B19"], "ans": 1, "expl": "CMV D+/R- (donor positive, recipient negative) represents the highest risk scenario. CMV can cause direct tissue invasion and indirect effects including increased rejection risk and opportunistic infections. Prophylaxis is standard for high-risk patients.", "obj": 6}, {"topic": "Transplant", "q": "What is the primary purpose of induction therapy in kidney transplantation?", "opts": ["To treat established rejection", "To provide intense immunosuppression during the highest risk period immediately post-transplant", "To replace maintenance immunosuppression", "To prevent viral infections"], "ans": 1, "expl": "Induction therapy uses potent immunosuppressive agents (such as basiliximab or antithymocyte globulin) during the immediate post-transplant period when rejection risk is highest, allowing delayed introduction or lower doses of nephrotoxic maintenance agents.", "obj": 5}, {"topic": "Transplant", "q": "BK virus nephropathy primarily affects which part of the transplanted kidney?", "opts": ["Glomeruli only", "Renal tubular epithelial cells", "Blood vessels only", "Collecting system only"], "ans": 1, "expl": "BK virus infects and replicates in renal tubular epithelial cells, causing interstitial nephritis and potential graft loss. Screening with urine decoy cells or plasma BK viral load is standard in the first year post-transplant.", "obj": 2}, {"topic": "Transplant", "q": "Which prophylactic medication is typically given to prevent Pneumocystis jirovecii pneumonia (PJP) in transplant recipients?", "opts": ["Acyclovir", "Trimethoprim-sulfamethoxazole", "Fluconazole", "Isoniazid"], "ans": 1, "expl": "Trimethoprim-sulfamethoxazole (TMP-SMX) is the first-line prophylaxis for PJP, typically given for 6-12 months post-transplant. It also provides protection against other opportunistic infections including Toxoplasma and some bacterial infections.", "obj": 6}, {"topic": "Transplant", "q": "What is the hallmark histological finding of chronic antibody-mediated rejection?", "opts": ["Tubular necrosis", "Transplant glomerulopathy with double contours", "Acute tubular injury", "Glomerular hyperfiltration"], "ans": 1, "expl": "Chronic antibody-mediated rejection is characterized by transplant glomerulopathy (duplication of glomerular basement membranes), interstitial fibrosis, tubular atrophy, and often C4d deposition in peritubular capillaries.", "obj": 1}, {"topic": "Transplant", "q": "Which factor is an absolute contraindication to kidney transplantation?", "opts": ["Age over 70 years", "Active malignancy", "Controlled hypertension", "Type 2 diabetes"], "ans": 1, "expl": "Active malignancy is generally an absolute contraindication due to the risk of cancer progression with immunosuppression. Most centers require a cancer-free period (typically 2-5 years depending on cancer type) before listing.", "obj": 7}, {"topic": "Transplant", "q": "What is the standard preservation solution used for deceased donor kidneys during cold storage?", "opts": ["Normal saline", "University of Wisconsin (UW) solution", "Lactated Ringer's", "5% Dextrose"], "ans": 1, "expl": "University of Wisconsin solution is the most commonly used preservation fluid, containing impermeants and substrates that minimize cellular swelling and injury during cold ischemia. It allows safe preservation for 24-48 hours.", "obj": 3}, {"topic": "Transplant", "q": "Which maintenance immunosuppression regimen is most commonly used in kidney transplantation?", "opts": ["Monotherapy with prednisone", "Triple therapy: calcineurin inhibitor + antimetabolite + corticosteroid", "Dual therapy with two calcineurin inhibitors", "Steroid-only regimen"], "ans": 1, "expl": "Triple therapy combining a calcineurin inhibitor (tacrolimus), antimetabolite (mycophenolate), and corticosteroid provides synergistic immunosuppression with different mechanisms, allowing lower doses of each agent and reduced toxicity.", "obj": 5}, {"topic": "Transplant", "q": "What is the most common cause of graft loss in the first year post-transplant?", "opts": ["Hyperacute rejection", "Death with functioning graft", "Acute rejection", "Surgical complications"], "ans": 1, "expl": "Death with a functioning graft has become the leading cause of graft loss, particularly from cardiovascular disease and infection. This reflects improved rejection prevention but ongoing challenges with long-term complications of immunosuppression.", "obj": 1}, {"topic": "Transplant", "q": "Which HLA locus is most important for kidney transplant matching?", "opts": ["HLA-DP", "HLA-DR", "HLA-A", "HLA-C"], "ans": 1, "expl": "HLA-DR matching has the strongest impact on graft survival, followed by HLA-B and HLA-A. Zero-antigen mismatch kidneys from deceased donors receive priority allocation due to superior outcomes.", "obj": 2}, {"topic": "Transplant", "q": "What is delayed graft function (DGF) defined as?", "opts": ["Need for dialysis within the first week post-transplant", "Creatinine elevation after 6 months", "Immediate urine output post-transplant", "Biopsy-proven rejection"], "ans": 0, "expl": "DGF is typically defined as the need for dialysis within the first week after transplantation. It is more common with deceased donor kidneys, prolonged cold ischemia time, and donor hemodynamic instability.", "obj": 3}, {"topic": "Transplant", "q": "Which medication requires therapeutic drug monitoring due to narrow therapeutic index and variable metabolism?", "opts": ["Prednisone", "Mycophenolate mofetil", "Tacrolimus", "Dapsone"], "ans": 2, "expl": "Tacrolimus has significant interpatient variability in metabolism via CYP3A4/5, requiring regular trough level monitoring. Target levels vary by time post-transplant and rejection risk.", "obj": 5}, {"topic": "Transplant", "q": "What is the primary mechanism of action of mycophenolate mofetil?", "opts": ["Calcineurin inhibition", "Inhibition of inosine monophosphate dehydrogenase", "mTOR inhibition", "IL-2 receptor blockade"], "ans": 1, "expl": "Mycophenolate inhibits IMPDH, blocking de novo purine synthesis. Lymphocytes depend on this pathway (unlike other cells that can use salvage pathways), providing selective immunosuppression.", "obj": 5}, {"topic": "Transplant", "q": "Which condition is a common metabolic complication of long-term corticosteroid use?", "opts": ["Hypoglycemia", "Hyperglycemia and new-onset diabetes", "Hypotension", "Weight loss"], "ans": 1, "expl": "Corticosteroids cause insulin resistance, increased hepatic gluconeogenesis, and can lead to post-transplant diabetes mellitus (PTDM). They also contribute to weight gain, dyslipidemia, and bone disease.", "obj": 1}, {"topic": "Transplant", "q": "What is the recommended screening interval for BK virus in the first year post-transplant?", "opts": ["Weekly", "Monthly for first 3-6 months, then every 3 months", "Annually", "Only if symptoms develop"], "ans": 1, "expl": "Standard screening involves monthly plasma BK viral load or urine decoy cell testing for the first 3-6 months, then every 3 months through year one. Early detection allows immunosuppression reduction before nephropathy develops.", "obj": 2}, {"topic": "Transplant", "q": "Which type of rejection is primarily mediated by donor-specific antibodies?", "opts": ["Acute cellular rejection", "Antibody-mediated rejection", "Interstitial fibrosis", "Drug toxicity"], "ans": 1, "expl": "Antibody-mediated rejection (AMR) is caused by donor-specific antibodies binding to graft endothelium, activating complement and causing injury. It can be acute or chronic and is diagnosed by histology, C4d staining, and DSA detection.", "obj": 1}, {"topic": "Acute Therapies", "q": "Which solute removal mechanism in CRRT relies primarily on hydrostatic pressure to move fluid and dissolved solutes across a semipermeable membrane?", "opts": ["Diffusion", "Convection", "Adsorption", "Ultrafiltration alone"], "ans": 1, "expl": "Convection uses hydrostatic pressure to create solvent drag, pulling solutes along with fluid across the membrane. This is the primary mechanism in hemofiltration-based modalities like CVVH.", "obj": 3}, {"topic": "Acute Therapies", "q": "In CVVHD (Continuous Veno-Venous Hemodialysis), what is the primary mechanism of solute clearance?", "opts": ["Convection with replacement fluid", "Diffusion with dialysate flow", "Adsorption to membrane", "Plasma separation"], "ans": 1, "expl": "CVVHD uses dialysate flowing counter-current to blood, creating concentration gradients that drive diffusive solute clearance, similar to conventional hemodialysis but at lower flow rates.", "obj": 3}, {"topic": "Acute Therapies", "q": "What distinguishes CVVHDF from CVVH and CVVHD?", "opts": ["It uses only convection", "It uses only diffusion", "It combines both convection and diffusion", "It uses no replacement fluid"], "ans": 2, "expl": "CVVHDF (Continuous Veno-Venous Hemodiafiltration) combines both convective clearance (via replacement fluid) and diffusive clearance (via dialysate), maximizing solute removal across molecular weight ranges.", "obj": 3}, {"topic": "Acute Therapies", "q": "SLED (Sustained Low-Efficiency Dialysis) is best described as:", "opts": ["A continuous 24-hour therapy", "An extended intermittent therapy typically run 6-12 hours", "A high-flow rapid dialysis session", "A peritoneal dialysis variant"], "ans": 1, "expl": "SLED is an extended intermittent renal replacement therapy, typically performed for 6-12 hours with lower blood and dialysate flows than conventional HD, offering hemodynamic stability between continuous and intermittent approaches.", "obj": 3}, {"topic": "Acute Therapies", "q": "According to KDIGO guidelines, what is the recommended delivered CRRT dose for critically ill patients with AKI?", "opts": ["15-20 mL/kg/hr", "20-25 mL/kg/hr", "25-30 mL/kg/hr", "35-40 mL/kg/hr"], "ans": 1, "expl": "KDIGO recommends a delivered dose of 20-25 mL/kg/hr for CRRT in critically ill patients. Higher doses have not shown improved outcomes in major trials.", "obj": 7}, {"topic": "Acute Therapies", "q": "Which vascular access site is preferred for CRRT catheter placement when feasible?", "opts": ["Femoral vein", "Internal jugular vein", "Subclavian vein", "External jugular vein"], "ans": 1, "expl": "The right internal jugular vein is preferred as it provides straight access to the SVC/RA junction, has lower infection risk than femoral, and avoids subclavian stenosis risk that could compromise future AV fistula creation.", "obj": 3}, {"topic": "Acute Therapies", "q": "What is a key advantage of regional citrate anticoagulation over systemic heparin in CRRT?", "opts": ["Lower cost", "Reduced bleeding risk", "Simpler monitoring", "Faster circuit clotting"], "ans": 1, "expl": "Citrate anticoagulation works regionally within the circuit by chelating calcium, minimizing systemic anticoagulation effects and reducing bleeding risk, particularly beneficial in patients with coagulopathy or active bleeding.", "obj": 5}, {"topic": "Acute Therapies", "q": "When using citrate anticoagulation in CRRT, which electrolyte requires close monitoring for potential accumulation?", "opts": ["Potassium", "Sodium", "Calcium", "Phosphate"], "ans": 2, "expl": "Citrate binds ionized calcium in the circuit. The citrate-calcium complex is metabolized by the liver, but in liver failure or severe shock, citrate can accumulate, leading to systemic hypocalcemia and metabolic alkalosis.", "obj": 5}, {"topic": "Acute Therapies", "q": "In sepsis-induced AKI requiring CRRT, what is the primary indication for initiating renal replacement therapy?", "opts": ["Elevated creatinine alone", "Life-threatening complications of AKI", "Oliguria for 6 hours", "BUN above 50 mg/dL"], "ans": 1, "expl": "CRRT initiation in sepsis-induced AKI is based on life-threatening complications: severe acidosis, hyperkalemia, volume overload refractory to diuretics, or uremic complications\u2014not solely on BUN/creatinine values.", "obj": 6}, {"topic": "Acute Therapies", "q": "Which buffer solution is most commonly used in modern CRRT and provides better hemodynamic stability than lactate?", "opts": ["Acetate", "Bicarbonate", "Lactate", "Citrate alone"], "ans": 1, "expl": "Bicarbonate-buffered solutions are now standard in CRRT, providing more physiologic pH correction and better hemodynamic stability compared to lactate, which requires hepatic metabolism and can cause vasodilation.", "obj": 3}, {"topic": "Acute Therapies", "q": "What is the primary cause of circuit clotting in CRRT?", "opts": ["Low blood flow rate", "Inadequate anticoagulation", "High ultrafiltration rate", "All of the above"], "ans": 3, "expl": "Circuit clotting can result from multiple factors: low blood flow causing stasis, inadequate anticoagulation allowing thrombus formation, and high ultrafiltration rates increasing hemoconcentration within the filter.", "obj": 3}, {"topic": "Acute Therapies", "q": "During CRRT, transmembrane pressure (TMP) elevation most commonly indicates:", "opts": ["Filter clotting", "Access recirculation", "Hypotension", "Electrolyte imbalance"], "ans": 0, "expl": "Rising TMP suggests increased resistance to ultrafiltration, typically from filter membrane fouling or clotting. Progressive TMP elevation often precedes complete circuit thrombosis and signals need for circuit change.", "obj": 3}, {"topic": "Acute Therapies", "q": "What is the typical blood flow rate range for CRRT?", "opts": ["50-100 mL/min", "100-200 mL/min", "200-300 mL/min", "300-400 mL/min"], "ans": 1, "expl": "CRRT typically uses blood flow rates of 100-200 mL/min, lower than conventional hemodialysis. This allows for gentler, continuous solute and fluid removal with better hemodynamic tolerance.", "obj": 3}, {"topic": "Acute Therapies", "q": "Which complication is specifically associated with rapid correction of chronic hypernatremia during CRRT?", "opts": ["Cardiac arrhythmias", "Cerebral edema", "Hemolysis", "Hypotension"], "ans": 1, "expl": "Rapid correction of chronic hypernatremia can cause cerebral edema as brain cells, which have accumulated idiogenic osmoles, swell when extracellular tonicity decreases too quickly. Sodium correction should not exceed 10-12 mEq/L per 24 hours.", "obj": 3}, {"topic": "Acute Therapies", "q": "In CRRT, what does the term 'effluent' refer to?", "opts": ["The blood returning to patient", "The dialysate inflow", "The waste fluid removed from circuit", "The replacement fluid"], "ans": 2, "expl": "Effluent is the total waste fluid removed from the CRRT circuit, including ultrafiltrate, spent dialysate, and any net fluid removal. Effluent flow rate determines the prescribed CRRT dose.", "obj": 3}, {"topic": "Acute Therapies", "q": "Which electrolyte abnormality is most commonly encountered during initiation of CRRT in severe AKI?", "opts": ["Hypernatremia", "Hypokalemia", "Hyperkalemia", "Hypophosphatemia"], "ans": 2, "expl": "Hyperkalemia is a common indication for urgent RRT initiation in AKI. CRRT effectively removes potassium, but initial rates should be monitored to avoid overly rapid shifts that could precipitate arrhythmias.", "obj": 3}, {"topic": "Acute Therapies", "q": "What is the primary mechanism of phosphate removal in CRRT?", "opts": ["Diffusion only", "Convection only", "Both diffusion and convection", "Adsorption to membrane"], "ans": 2, "expl": "Phosphate is removed by both diffusion and convection in CRRT. However, phosphate clearance is often inadequate, leading to hypophosphatemia during prolonged CRRT, requiring supplementation.", "obj": 3}, {"topic": "Acute Therapies", "q": "Which factor most significantly reduces delivered CRRT dose compared to prescribed dose?", "opts": ["Blood flow rate", "Replacement fluid rate", "Treatment downtime", "Dialysate temperature"], "ans": 2, "expl": "Treatment downtime from circuit clotting, patient transport, procedures, or machine alarms significantly reduces delivered dose. Studies show delivered dose is often 15-30% lower than prescribed due to interruptions.", "obj": 5}, {"topic": "Acute Therapies", "q": "For a patient with severe metabolic acidosis (pH 7.15) and AKI, which CRRT prescription adjustment would best address the acidosis?", "opts": ["Decrease effluent rate", "Increase bicarbonate concentration in dialysate/replacement fluid", "Reduce blood flow rate", "Switch to heparin anticoagulation"], "ans": 1, "expl": "Increasing bicarbonate concentration in the dialysate or replacement fluid enhances bicarbonate delivery, helping correct metabolic acidosis. Standard solutions contain 25-32 mEq/L bicarbonate, which can be adjusted based on acid-base status.", "obj": 3}, {"topic": "Acute Therapies", "q": "What is the primary advantage of continuous renal replacement therapies over intermittent hemodialysis in hemodynamically unstable patients?", "opts": ["Lower cost", "Faster solute clearance", "Better hemodynamic tolerance", "Shorter treatment time"], "ans": 2, "expl": "CRRT provides slow, continuous fluid and solute removal over 24 hours, avoiding the rapid osmotic and volume shifts of intermittent HD that can precipitate hypotension in unstable patients.", "obj": 3}, {"topic": "CKD Complications", "q": "A patient with stage 4 CKD has a hemoglobin level of 9.2 g/dL. What is the primary mechanism causing anemia in this patient?", "opts": ["Decreased erythropoietin production by the kidneys", "Increased red blood cell destruction", "Acute blood loss from the GI tract", "Vitamin B12 deficiency"], "ans": 0, "expl": "In CKD, damaged kidneys produce less erythropoietin (EPO), the hormone that stimulates red blood cell production in bone marrow. This is the primary cause of anemia in CKD patients.", "obj": 2}, {"topic": "CKD Complications", "q": "Which laboratory finding is most characteristic of secondary hyperparathyroidism in CKD?", "opts": ["Elevated PTH with low or normal calcium", "Low PTH with high calcium", "Normal PTH with low phosphate", "Elevated PTH with high calcium"], "ans": 0, "expl": "Secondary hyperparathyroidism in CKD presents with elevated PTH as the parathyroid glands overwork to compensate for low calcium (caused by low vitamin D activation) and high phosphate levels.", "obj": 1}, {"topic": "CKD Complications", "q": "A CKD patient presents with metabolic acidosis. Which mechanism best explains this complication?", "opts": ["Decreased ability to excrete hydrogen ions and regenerate bicarbonate", "Increased production of lactic acid", "Excessive loss of bicarbonate through diarrhea", "Respiratory compensation failure"], "ans": 0, "expl": "Damaged kidneys lose the ability to excrete acid (hydrogen ions) and regenerate bicarbonate, leading to metabolic acidosis with a normal anion gap.", "obj": 1}, {"topic": "CKD Complications", "q": "What is the primary nursing concern when a CKD patient has a serum potassium level of 6.2 mEq/L?", "opts": ["Risk of life-threatening cardiac arrhythmias", "Increased risk of bleeding", "Development of metabolic alkalosis", "Progression of bone disease"], "ans": 0, "expl": "Hyperkalemia above 6.0 mEq/L can cause dangerous cardiac arrhythmias including ventricular fibrillation. This is a medical emergency requiring immediate intervention.", "obj": 1}, {"topic": "CKD Complications", "q": "Which intervention is most appropriate for managing hyperphosphatemia in a CKD patient?", "opts": ["Administering phosphate binders with meals", "Increasing dietary phosphate intake", "Giving vitamin D supplements alone", "Restricting fluid intake"], "ans": 0, "expl": "Phosphate binders should be taken with meals to bind dietary phosphate in the gut, preventing its absorption. This is a cornerstone of CKD-MBD management.", "obj": 2}, {"topic": "CKD Complications", "q": "A patient with diabetic nephropathy is at highest risk for which cardiovascular complication?", "opts": ["Accelerated atherosclerosis and coronary artery disease", "Pulmonary hypertension", "Aortic stenosis", "Peripheral varicose veins"], "ans": 0, "expl": "Diabetic nephropathy significantly increases cardiovascular risk due to accelerated atherosclerosis, endothelial dysfunction, and chronic inflammation associated with both diabetes and CKD.", "obj": 1}, {"topic": "CKD Complications", "q": "What is the target hemoglobin range for most CKD patients being treated with erythropoiesis-stimulating agents (ESAs)?", "opts": ["10-11 g/dL", "12-14 g/dL", "8-9 g/dL", "14-16 g/dL"], "ans": 0, "expl": "Current guidelines recommend targeting hemoglobin of 10-11 g/dL in CKD patients on ESAs. Higher targets increase cardiovascular risk without improving quality of life.", "obj": 2}, {"topic": "CKD Complications", "q": "Which type of bone disease is characterized by low bone turnover and suppressed PTH in CKD patients?", "opts": ["Adynamic bone disease", "Osteitis fibrosa cystica", "Osteoporosis", "Paget's disease"], "ans": 0, "expl": "Adynamic bone disease features low bone turnover with suppressed PTH, often from over-suppression with vitamin D analogs or calcium-based binders. It increases fracture and calcification risk.", "obj": 1}, {"topic": "CKD Complications", "q": "What is the primary reason CKD patients develop dyslipidemia?", "opts": ["Decreased clearance of triglyceride-rich lipoproteins", "Increased dietary fat absorption", "Enhanced HDL production", "Reduced cholesterol synthesis"], "ans": 0, "expl": "CKD causes dyslipidemia primarily through decreased clearance of triglyceride-rich lipoproteins (VLDL, chylomicrons) due to reduced lipoprotein lipase activity.", "obj": 1}, {"topic": "CKD Complications", "q": "A CKD patient complains of persistent nausea, loss of appetite, and muscle wasting. Which complication should the nurse suspect?", "opts": ["Protein-energy wasting (malnutrition)", "Hypercalcemia", "Metabolic alkalosis", "Iron overload"], "ans": 0, "expl": "These symptoms indicate protein-energy wasting, a common complication in advanced CKD caused by uremic toxins, inflammation, metabolic acidosis, and inadequate nutrient intake.", "obj": 1}, {"topic": "CKD Complications", "q": "Which form of vitamin D requires activation by the kidneys and is typically deficient in CKD patients?", "opts": ["Calcitriol (1,25-dihydroxyvitamin D)", "Cholecalciferol (vitamin D3)", "Ergocalciferol (vitamin D2)", "25-hydroxyvitamin D"], "ans": 0, "expl": "Calcitriol is the active form of vitamin D produced by kidney 1-alpha-hydroxylase. In CKD, this enzyme activity decreases, leading to calcitriol deficiency and impaired calcium absorption.", "obj": 5}, {"topic": "CKD Complications", "q": "What is the most common cause of death in patients with chronic kidney disease?", "opts": ["Cardiovascular disease", "Infection", "Progression to ESRD", "Malignancy"], "ans": 0, "expl": "Cardiovascular disease accounts for approximately 50% of deaths in CKD patients, with risk increasing as kidney function declines. This includes coronary artery disease, heart failure, and sudden cardiac death.", "obj": 1}, {"topic": "CKD Complications", "q": "A patient with CKD has elevated intact PTH, elevated phosphate, and low calcium. What stage of CKD-MBD does this represent?", "opts": ["Secondary hyperparathyroidism", "Primary hyperparathyroidism", "Tertiary hyperparathyroidism", "Hypoparathyroidism"], "ans": 0, "expl": "This pattern indicates secondary hyperparathyroidism: the parathyroid glands increase PTH production in response to low calcium and high phosphate from impaired kidney function.", "obj": 1}, {"topic": "CKD Complications", "q": "Which dietary modification is most important for a CKD patient with hyperkalemia?", "opts": ["Limiting high-potassium foods like bananas, oranges, and potatoes", "Increasing protein intake", "Restricting all dairy products", "Eliminating all carbohydrates"], "ans": 0, "expl": "Patients with hyperkalemia should limit high-potassium foods. Common sources include bananas, oranges, tomatoes, potatoes, spinach, and salt substitutes containing potassium chloride.", "obj": 4}, {"topic": "CKD Complications", "q": "What is the role of sevelamer in CKD management?", "opts": ["Non-calcium phosphate binder that reduces phosphate absorption", "Potassium-lowering medication", "Erythropoietin stimulator", "Vitamin D analog"], "ans": 0, "expl": "Sevelamer is a non-calcium, non-aluminum phosphate binder that binds dietary phosphate in the intestine. It's preferred when calcium levels are elevated or vascular calcification is present.", "obj": 5}, {"topic": "CKD Complications", "q": "Which finding suggests uremic pruritus in a dialysis patient?", "opts": ["Generalized itching without visible rash, worse at night", "Localized rash with vesicles", "Hives appearing after medication administration", "Dry, scaly patches only on extremities"], "ans": 0, "expl": "Uremic pruritus presents as generalized itching without primary skin lesions, often worse at night. It's related to uremic toxins, dry skin, and immune dysregulation in CKD.", "obj": 1}, {"topic": "CKD Complications", "q": "A CKD patient is prescribed sodium bicarbonate. What complication is being treated?", "opts": ["Metabolic acidosis", "Hyperkalemia", "Hyperphosphatemia", "Anemia"], "ans": 0, "expl": "Sodium bicarbonate treats metabolic acidosis by providing bicarbonate to buffer excess acid. Target serum bicarbonate is typically 22-26 mEq/L in CKD patients.", "obj": 5}, {"topic": "CKD Complications", "q": "What is the primary mechanism by which CKD increases fracture risk?", "opts": ["CKD-mineral and bone disorder (CKD-MBD) affecting bone quality", "Increased physical activity", "Excessive vitamin D intake", "Low phosphate levels"], "ans": 0, "expl": "CKD-MBD causes abnormal bone turnover, mineralization, and strength through disturbances in calcium, phosphate, PTH, and vitamin D metabolism, significantly increasing fracture risk.", "obj": 1}, {"topic": "CKD Complications", "q": "Which iron study pattern is typical in CKD-related anemia?", "opts": ["Normal or high ferritin with low transferrin saturation", "Low ferritin with high transferrin saturation", "Low ferritin with low transferrin saturation", "High ferritin with high transferrin saturation"], "ans": 0, "expl": "CKD anemia often shows functional iron deficiency: normal/high ferritin (acute phase reactant) but low transferrin saturation due to inflammation blocking iron release from stores.", "obj": 1}, {"topic": "CKD Complications", "q": "What is the significance of elevated FGF23 in early CKD?", "opts": ["Early marker of phosphate retention and predictor of cardiovascular events", "Indicator of improved kidney function", "Sign of iron deficiency", "Marker of resolved metabolic acidosis"], "ans": 0, "expl": "FGF23 rises early in CKD to promote phosphate excretion. However, elevated FGF23 is independently associated with left ventricular hypertrophy and increased cardiovascular mortality.", "obj": 1}, {"topic": "Pediatric Nephrology", "q": "A 4-year-old presents with periorbital edema and proteinuria of 4+ on dipstick. Which finding would confirm nephrotic syndrome?", "opts": ["Urine protein-to-creatinine ratio greater than 2.0 mg/mg", "Serum albumin less than 2.5 g/dL with edema", "Blood pressure above the 95th percentile", "Serum creatinine of 1.5 mg/dL"], "ans": 1, "expl": "Nephrotic syndrome in children requires heavy proteinuria (UPCR >2.0 or 40 mg/m2/hr), hypoalbuminemia (<2.5 g/dL), and edema. Option B captures the key diagnostic criteria.", "obj": 1}, {"topic": "Pediatric Nephrology", "q": "Which organism is most commonly associated with typical hemolytic uremic syndrome (HUS) in children?", "opts": ["Streptococcus pneumoniae", "Escherichia coli O157:H7", "Staphylococcus aureus", "Salmonella typhi"], "ans": 1, "expl": "Typical HUS is most commonly caused by Shiga toxin-producing E. coli, particularly serotype O157:H7, often acquired from undercooked ground beef or contaminated produce.", "obj": 1}, {"topic": "Pediatric Nephrology", "q": "What is the preferred initial dialysis modality for infants and young children with end-stage kidney disease?", "opts": ["Hemodialysis via central venous catheter", "Peritoneal dialysis", "Continuous venovenous hemofiltration", "Kidney transplantation immediately"], "ans": 1, "expl": "Peritoneal dialysis is preferred in infants and young children because it provides gentle continuous ultrafiltration, preserves residual kidney function, and allows better growth and nutrition compared to hemodialysis.", "obj": 3}, {"topic": "Pediatric Nephrology", "q": "A newborn male has bilateral hydronephrosis on prenatal ultrasound. Which condition should be highest on the differential?", "opts": ["Vesicoureteral reflux", "Posterior urethral valves", "Ureteropelvic junction obstruction", "Multicystic dysplastic kidney"], "ans": 1, "expl": "Posterior urethral valves (PUV) occur only in males and cause bilateral hydronephrosis due to bladder outlet obstruction. It is the most common cause of lower urinary tract obstruction in male infants.", "obj": 1}, {"topic": "Pediatric Nephrology", "q": "Which medication is first-line treatment for minimal change disease in children?", "opts": ["Cyclosporine", "Mycophenolate mofetil", "Prednisone", "Rituximab"], "ans": 2, "expl": "Corticosteroids (prednisone) are first-line therapy for minimal change disease, the most common cause of nephrotic syndrome in children. Most children achieve remission within 4-8 weeks of steroid therapy.", "obj": 5}, {"topic": "Pediatric Nephrology", "q": "What is the classic triad of hemolytic uremic syndrome?", "opts": ["Fever, rash, and joint pain", "Microangiopathic hemolytic anemia, thrombocytopenia, and acute kidney injury", "Hematuria, proteinuria, and hypertension", "Vomiting, diarrhea, and dehydration"], "ans": 1, "expl": "HUS is characterized by the triad of microangiopathic hemolytic anemia (schistocytes on smear), thrombocytopenia (low platelets), and acute kidney injury. This results from endothelial damage caused by Shiga toxin.", "obj": 1}, {"topic": "Pediatric Nephrology", "q": "Which nutritional intervention is most important for children with chronic kidney disease?", "opts": ["High-protein diet to prevent malnutrition", "Adequate caloric intake to support growth", "Unrestricted potassium intake", "High-phosphorus diet for bone health"], "ans": 1, "expl": "Children with CKD require adequate caloric intake (often 100-140% of recommended daily allowance) to support growth. Protein should be adequate but not excessive, and potassium/phosphorus may need restriction depending on kidney function.", "obj": 2}, {"topic": "Pediatric Nephrology", "q": "What is the most common congenital anomaly of the kidney and urinary tract (CAKUT)?", "opts": ["Renal agenesis", "Horseshoe kidney", "Hydronephrosis", "Posterior urethral valves"], "ans": 2, "expl": "Hydronephrosis is the most common CAKUT, detected in approximately 1-5% of prenatal ultrasounds. It can result from various causes including UPJ obstruction, VUR, or PUV.", "obj": 1}, {"topic": "Pediatric Nephrology", "q": "A child with posterior urethral valves is at highest risk for which long-term complication?", "opts": ["Recurrent urinary tract infections only", "Chronic kidney disease and bladder dysfunction", "Nephrotic syndrome", "Kidney stones"], "ans": 1, "expl": "Children with PUV are at significant risk for chronic kidney disease due to obstructive uropathy and associated bladder dysfunction (valve bladder). Long-term monitoring of kidney function and bladder health is essential.", "obj": 1}, {"topic": "Pediatric Nephrology", "q": "Which laboratory finding is characteristic of renal tubular acidosis in children?", "opts": ["Metabolic alkalosis with hypokalemia", "Normal anion gap metabolic acidosis", "High anion gap metabolic acidosis", "Respiratory acidosis"], "ans": 1, "expl": "Renal tubular acidosis causes a normal anion gap (hyperchloremic) metabolic acidosis due to impaired acid excretion or bicarbonate reabsorption. Potassium levels vary by RTA type.", "obj": 1}, {"topic": "Pediatric Nephrology", "q": "What is the most appropriate initial imaging study for a child with suspected vesicoureteral reflux?", "opts": ["Renal ultrasound", "Voiding cystourethrogram (VCUG)", "CT urogram", "MRI of the abdomen"], "ans": 1, "expl": "VCUG is the gold standard for diagnosing vesicoureteral reflux as it visualizes urine flow during voiding and can grade the severity of reflux. Ultrasound may suggest VUR but cannot confirm it.", "obj": 2}, {"topic": "Pediatric Nephrology", "q": "Which finding on urinalysis suggests glomerular disease in a child?", "opts": ["Isolated leukocyte esterase positivity", "Dysmorphic red blood cells and red cell casts", "Crystalluria with normal pH", "Specific gravity of 1.005"], "ans": 1, "expl": "Dysmorphic RBCs and red cell casts indicate glomerular bleeding and are hallmarks of glomerulonephritis. These findings suggest the kidney itself is the source of hematuria.", "obj": 1}, {"topic": "Pediatric Nephrology", "q": "What is the primary goal of growth hormone therapy in children with CKD?", "opts": ["To improve kidney function", "To achieve normal height velocity and final adult height", "To reduce proteinuria", "To prevent bone fractures"], "ans": 1, "expl": "Growth hormone therapy in children with CKD aims to overcome growth failure and achieve normal height velocity and final adult height. It does not improve kidney function but addresses CKD-related growth impairment.", "obj": 2}, {"topic": "Pediatric Nephrology", "q": "Which electrolyte abnormality is most concerning in a child with acute kidney injury and oliguria?", "opts": ["Hyponatremia", "Hyperkalemia", "Hypocalcemia", "Hyperphosphatemia"], "ans": 1, "expl": "Hyperkalemia is the most immediately life-threatening electrolyte abnormality in AKI with oliguria, as it can cause fatal arrhythmias. It requires urgent treatment with calcium, insulin/glucose, and possibly dialysis.", "obj": 1}, {"topic": "Pediatric Nephrology", "q": "What is the most common cause of acute kidney injury in hospitalized children?", "opts": ["Glomerulonephritis", "Ischemic or nephrotoxic injury", "Congenital anomalies", "Urinary tract obstruction"], "ans": 1, "expl": "In hospitalized children, AKI is most commonly caused by ischemic injury (sepsis, hypotension, dehydration) or nephrotoxic medications (aminoglycosides, vancomycin, contrast). This is called intrinsic or acute tubular necrosis.", "obj": 1}, {"topic": "Pediatric Nephrology", "q": "Which statement about steroid-resistant nephrotic syndrome in children is correct?", "opts": ["It rarely progresses to kidney failure", "Kidney biopsy is typically recommended", "Steroids should be continued indefinitely", "It is always caused by minimal change disease"], "ans": 1, "expl": "Steroid-resistant nephrotic syndrome (no remission after 8 weeks of steroids) typically requires kidney biopsy to determine underlying pathology, as focal segmental glomerulosclerosis and other lesions are common causes.", "obj": 1}, {"topic": "Pediatric Nephrology", "q": "What is the recommended daily fluid intake calculation for a healthy child weighing 25 kg?", "opts": ["1000 mL plus 20 mL per kg over 20 kg", "1500 mL plus 20 mL per kg over 20 kg", "100 mL per kg for all weight", "50 mL per kg for all weight"], "ans": 1, "expl": "The Holliday-Segar method calculates maintenance fluids as: 100 mL/kg for first 10 kg, 50 mL/kg for next 10 kg, and 20 mL/kg for each kg over 20 kg. For 25 kg: 1000 + 500 + 100 = 1600 mL/day.", "obj": 4}, {"topic": "Pediatric Nephrology", "q": "Which condition is associated with an increased risk of Wilms tumor in children?", "opts": ["Nephrotic syndrome", "Beckwith-Wiedemann syndrome", "Posterior urethral valves", "Vesicoureteral reflux"], "ans": 1, "expl": "Beckwith-Wiedemann syndrome (characterized by macrosomia, macroglossia, and abdominal wall defects) is associated with increased risk of Wilms tumor. These children require regular renal ultrasound screening.", "obj": 1}, {"topic": "Pediatric Nephrology", "q": "What is the primary mechanism of anemia in children with chronic kidney disease?", "opts": ["Iron deficiency from dietary restrictions", "Decreased erythropoietin production", "Hemolysis from uremic toxins", "Bone marrow suppression from medications"], "ans": 1, "expl": "Anemia in CKD is primarily due to decreased erythropoietin production by damaged kidneys. Treatment typically involves erythropoiesis-stimulating agents and iron supplementation.", "obj": 1}, {"topic": "Pediatric Nephrology", "q": "Which intervention is most effective in preventing progression of chronic kidney disease in children?", "opts": ["High-protein diet", "Blood pressure control with ACE inhibitors or ARBs", "Aggressive diuretic therapy", "Calcium supplementation alone"], "ans": 1, "expl": "Blood pressure control, particularly with ACE inhibitors or ARBs, is the most effective intervention to slow CKD progression in children. These medications also reduce proteinuria, which is independently nephrotoxic.", "obj": 2}, {"topic": "Pregnancy and Kidney Disease", "q": "Which physiologic change occurs in the kidneys during normal pregnancy?", "opts": ["GFR decreases by 20-30% due to increased plasma volume", "GFR increases by 40-50% starting in the first trimester", "Serum creatinine rises to 1.2 mg/dL as a normal adaptation", "Renal plasma flow decreases significantly after week 20"], "ans": 1, "expl": "During normal pregnancy, GFR increases by 40-50% beginning in the first trimester due to increased renal plasma flow and vasodilation. Serum creatinine normally decreases to 0.4-0.8 mg/dL, not increases.", "obj": 1}, {"topic": "Pregnancy and Kidney Disease", "q": "A pregnant patient at 28 weeks has BP 150/95 mmHg and proteinuria. She had normal BP before pregnancy. What is the most likely diagnosis?", "opts": ["Chronic hypertension", "Gestational hypertension progressing to preeclampsia", "White coat hypertension", "Renal artery stenosis"], "ans": 1, "expl": "New-onset hypertension after 20 weeks gestation with proteinuria indicates preeclampsia. Chronic hypertension would have been present before pregnancy or before 20 weeks gestation.", "obj": 1}, {"topic": "Pregnancy and Kidney Disease", "q": "Which laboratory finding helps differentiate chronic hypertension from preeclampsia in a pregnant patient?", "opts": ["Elevated uric acid levels", "Hypertension present before 20 weeks gestation", "Proteinuria greater than 300 mg/24 hours", "Platelet count below 100,000/mcL"], "ans": 1, "expl": "Chronic hypertension is defined as hypertension present before pregnancy or diagnosed before 20 weeks gestation. Preeclampsia develops after 20 weeks. Both can have proteinuria, but timing distinguishes them.", "obj": 1}, {"topic": "Pregnancy and Kidney Disease", "q": "What is the hallmark triad of HELLP syndrome?", "opts": ["Hypertension, edema, liver failure", "Hemolysis, elevated liver enzymes, low platelets", "Hyperuricemia, edema, lethargy, proteinuria, seizures", "Hypotension, elevated lactate, low potassium"], "ans": 1, "expl": "HELLP syndrome stands for Hemolysis (microangiopathic), Elevated Liver enzymes, and Low Platelets. It is a severe variant of preeclampsia requiring immediate delivery.", "obj": 1}, {"topic": "Pregnancy and Kidney Disease", "q": "Which medication is considered first-line for blood pressure control in pregnant patients with chronic kidney disease?", "opts": ["Lisinopril", "Losartan", "Labetalol", "Atenolol"], "ans": 2, "expl": "Labetalol is first-line for BP control in pregnancy. ACE inhibitors (lisinopril) and ARBs (losartan) are contraindicated due to fetal renal toxicity. Atenolol is associated with fetal growth restriction.", "obj": 5}, {"topic": "Pregnancy and Kidney Disease", "q": "A patient with stage 3 CKD (baseline creatinine 1.8 mg/dL) becomes pregnant. What is the most significant risk?", "opts": ["Progression to end-stage kidney disease during pregnancy", "Preeclampsia superimposed on CKD", "Development of nephrotic syndrome", "Acute tubular necrosis from hyperemesis"], "ans": 1, "expl": "Women with CKD have a 25-50% risk of developing superimposed preeclampsia. While CKD may progress, the most common and significant complication is preeclampsia, which increases maternal and fetal morbidity.", "obj": 1}, {"topic": "Pregnancy and Kidney Disease", "q": "What is the recommended target blood pressure for pregnant patients with chronic kidney disease?", "opts": ["Below 120/80 mmHg", "Below 135/85 mmHg", "Below 140/90 mmHg", "Below 150/100 mmHg"], "ans": 2, "expl": "Current guidelines recommend maintaining BP below 140/90 mmHg in pregnant patients with CKD. Aggressive lowering below 120/80 may compromise placental perfusion.", "obj": 2}, {"topic": "Pregnancy and Kidney Disease", "q": "Which finding is most concerning for acute kidney injury in a pregnant patient?", "opts": ["Serum creatinine of 0.6 mg/dL", "Serum creatinine of 1.0 mg/dL", "Urine output of 600 mL/day", "BUN of 12 mg/dL"], "ans": 1, "expl": "In pregnancy, normal creatinine is 0.4-0.8 mg/dL due to increased GFR. A creatinine of 1.0 mg/dL or higher in pregnancy represents significant renal impairment and may indicate AKI.", "obj": 1}, {"topic": "Pregnancy and Kidney Disease", "q": "What is the most common cause of acute kidney injury in pregnancy?", "opts": ["Acute tubular necrosis from sepsis", "Preeclampsia/HELLP syndrome", "Posterior urethral valves", "Renal vein thrombosis"], "ans": 1, "expl": "Preeclampsia and HELLP syndrome are the most common causes of AKI in pregnancy, accounting for approximately 50-60% of cases. Other causes include septic abortion, hemorrhage, and acute fatty liver of pregnancy.", "obj": 1}, {"topic": "Pregnancy and Kidney Disease", "q": "A pregnant patient at 32 weeks presents with fever, flank pain, and costovertebral angle tenderness. What is the most appropriate initial management?", "opts": ["Oral nitrofurantoin and outpatient follow-up", "IV ceftriaxone and hospital admission", "Wait for urine culture before starting antibiotics", "Renal ultrasound only, no antibiotics"], "ans": 1, "expl": "This presentation indicates pyelonephritis, which requires hospitalization and IV antibiotics in pregnancy due to high risk of complications including preterm labor, sepsis, and respiratory distress.", "obj": 2}, {"topic": "Pregnancy and Kidney Disease", "q": "Which antibiotic is safest for treating urinary tract infection in the first trimester of pregnancy?", "opts": ["Ciprofloxacin", "Trimethoprim-sulfamethoxazole", "Cephalexin", "Doxycycline"], "ans": 2, "expl": "Cephalexin (a cephalosporin) is safe throughout pregnancy. Fluoroquinolones affect fetal cartilage, TMP-SMX is contraindicated in first trimester (folate antagonist) and near term, and tetracyclines cause tooth discoloration.", "obj": 5}, {"topic": "Pregnancy and Kidney Disease", "q": "What is the minimum dialysis prescription for pregnant patients with end-stage kidney disease?", "opts": ["Standard 3 times weekly, 3-4 hours per session", "Daily or near-daily dialysis totaling 20+ hours weekly", "Peritoneal dialysis only, no hemodialysis", "Twice weekly, 2 hours per session"], "ans": 1, "expl": "Pregnant patients on dialysis require intensive regimens (daily or near-daily, 20+ hours/week) to maintain BUN below 50 mg/dL and minimize fluid shifts, which improves fetal outcomes.", "obj": 3}, {"topic": "Pregnancy and Kidney Disease", "q": "Why is intensive dialysis required during pregnancy in patients with ESKD?", "opts": ["To prevent maternal hypertension only", "To maintain low BUN levels for fetal growth and prevent polyhydramnios", "To increase maternal weight gain", "To reduce the need for erythropoietin"], "ans": 1, "expl": "High BUN levels are associated with poor fetal outcomes including intrauterine growth restriction and polyhydramnios. Intensive dialysis maintains BUN <50 mg/dL, mimicking the low BUN of normal pregnancy.", "obj": 3}, {"topic": "Pregnancy and Kidney Disease", "q": "What is the most common obstetric complication in pregnant patients receiving dialysis?", "opts": ["Placenta accreta", "Preterm delivery", "Uterine rupture", "Postpartum hemorrhage"], "ans": 1, "expl": "Preterm delivery occurs in 50-80% of pregnancies in dialysis patients. Other complications include intrauterine growth restriction, polyhydramnios, and spontaneous abortion, especially in first trimester.", "obj": 1}, {"topic": "Pregnancy and Kidney Disease", "q": "Which parameter should be monitored weekly in pregnant patients with CKD?", "opts": ["24-hour urine protein and blood pressure", "Serum albumin only", "Kidney ultrasound", "Bone mineral density"], "ans": 0, "expl": "Weekly monitoring of BP and proteinuria is essential to detect superimposed preeclampsia early. Additional monitoring includes fetal growth scans and assessment of kidney function.", "obj": 2}, {"topic": "Pregnancy and Kidney Disease", "q": "A pregnant patient with lupus nephritis should be counseled that pregnancy is safest when:", "opts": ["Disease has been quiescent for at least 6 months", "She is on high-dose prednisone", "Proteinuria is greater than 3 g/day", "Serum creatinine is above 2.0 mg/dL"], "ans": 0, "expl": "Pregnancy outcomes are best when lupus nephritis has been in remission for at least 6 months before conception. Active disease, significant proteinuria, or elevated creatinine increase risks substantially.", "obj": 4}, {"topic": "Pregnancy and Kidney Disease", "q": "What is the effect of pregnancy on long-term kidney function in women with mild CKD (stage 1-2)?", "opts": ["Pregnancy accelerates progression to ESKD in all cases", "Most women have no significant acceleration of kidney disease", "All women will require dialysis within 5 years", "Pregnancy has no effect on kidney disease progression"], "ans": 1, "expl": "Women with mild CKD (stage 1-2) generally do not experience accelerated progression of kidney disease from pregnancy. However, those with moderate-severe CKD or significant proteinuria have higher risk of progression.", "obj": 1}, {"topic": "Pregnancy and Kidney Disease", "q": "Which condition is an absolute contraindication to pregnancy in women with kidney disease?", "opts": ["Stage 2 CKD with controlled blood pressure", "Pulmonary hypertension associated with CKD", "History of urinary tract infection", "Nephrolithiasis without obstruction"], "ans": 1, "expl": "Pulmonary hypertension carries extremely high maternal mortality (30-50%) during pregnancy and is considered an absolute contraindication. Other conditions may increase risk but are not absolute contraindications.", "obj": 2}, {"topic": "Pregnancy and Kidney Disease", "q": "What is the role of low-dose aspirin in pregnant patients with CKD?", "opts": ["Contraindicated due to bleeding risk", "Recommended starting at 12 weeks to reduce preeclampsia risk", "Only used if platelet count is below 50,000", "Started only after delivery"], "ans": 1, "expl": "Low-dose aspirin (81 mg daily) starting at 12 weeks gestation is recommended for women with CKD to reduce the risk of preeclampsia, which they are at high risk for developing.", "obj": 5}, {"topic": "Pregnancy and Kidney Disease", "q": "Postpartum, what should be monitored in women who had preeclampsia with kidney involvement?", "opts": ["No follow-up needed if delivery was uncomplicated", "Blood pressure and kidney function for at least 3 months", "Only urine culture at 6 weeks", "Kidney biopsy immediately after delivery"], "ans": 1, "expl": "Women with preeclampsia need postpartum monitoring of BP and kidney function for at least 3 months, as some may have persistent hypertension or kidney dysfunction. They also have increased long-term CV and CKD risk.", "obj": 2}, {"topic": "Drug Dosing in Renal Failure", "q": "Which antibiotic requires significant dose reduction when GFR falls below 30 mL/min due to renal elimination?", "opts": ["Azithromycin", "Vancomycin", "Doxycycline", "Clindamycin"], "ans": 1, "expl": "Vancomycin is primarily eliminated by the kidneys and accumulates in renal failure, requiring dose adjustment based on trough levels and GFR.", "obj": 5}, {"topic": "Drug Dosing in Renal Failure", "q": "Why should metformin be discontinued in patients with eGFR below 30 mL/min?", "opts": ["Causes hyperglycemia", "Risk of lactic acidosis", "Increases proteinuria", "Causes hypertension"], "ans": 1, "expl": "Metformin accumulation in severe renal impairment increases the risk of lactic acidosis, a rare but potentially fatal complication.", "obj": 5}, {"topic": "Drug Dosing in Renal Failure", "q": "Which medication class should be avoided entirely in CKD patients due to risk of acute kidney injury?", "opts": ["ACE inhibitors", "NSAIDs", "Calcium channel blockers", "Beta blockers"], "ans": 1, "expl": "NSAIDs reduce renal blood flow by inhibiting prostaglandin-mediated vasodilation, potentially causing acute kidney injury especially in CKD.", "obj": 5}, {"topic": "Drug Dosing in Renal Failure", "q": "Nitrofurantoin is contraindicated in CKD primarily because:", "opts": ["It causes nephrotoxicity", "It lacks efficacy due to poor urinary concentration", "It increases blood pressure", "It causes hyperkalemia"], "ans": 1, "expl": "Nitrofurantoin requires adequate urinary concentrations for efficacy, which cannot be achieved when GFR is reduced; it also increases toxicity risk.", "obj": 5}, {"topic": "Drug Dosing in Renal Failure", "q": "Which drug is most likely to be removed during hemodialysis?", "opts": ["Warfarin", "Gentamicin", "Amiodarone", "Diazepam"], "ans": 1, "expl": "Gentamicin is water-soluble, has low protein binding, and small molecular weight, making it highly dialyzable.", "obj": 5}, {"topic": "Drug Dosing in Renal Failure", "q": "When dosing vancomycin in a hemodialysis patient, the typical approach is:", "opts": ["Daily dosing", "Dose after each dialysis session", "Dose before each dialysis session", "No dose adjustment needed"], "ans": 1, "expl": "Vancomycin is partially removed by dialysis, so it is typically dosed after hemodialysis sessions based on trough levels.", "obj": 5}, {"topic": "Drug Dosing in Renal Failure", "q": "Which contrast-related precaution is recommended for CKD patients undergoing CT imaging?", "opts": ["Administer high-dose diuretics", "Hydrate with IV normal saline before and after", "Give prophylactic antibiotics", "Avoid all imaging permanently"], "ans": 1, "expl": "IV hydration with normal saline before and after contrast administration helps reduce the risk of contrast-induced nephropathy.", "obj": 5}, {"topic": "Drug Dosing in Renal Failure", "q": "Which medication requires monitoring of drug levels in renal failure patients?", "opts": ["Lisinopril", "Digoxin", "Metoprolol", "Amlodipine"], "ans": 1, "expl": "Digoxin is renally eliminated and has a narrow therapeutic index, requiring level monitoring and dose adjustment in CKD.", "obj": 5}, {"topic": "Drug Dosing in Renal Failure", "q": "Aminoglycosides in renal failure patients should be dosed:", "opts": ["At higher frequencies", "With extended dosing intervals", "At standard intervals", "Only intramuscularly"], "ans": 1, "expl": "Aminoglycosides have prolonged half-lives in renal failure, requiring extended dosing intervals to prevent accumulation and ototoxicity/nephrotoxicity.", "obj": 5}, {"topic": "Drug Dosing in Renal Failure", "q": "Which drug is primarily metabolized by the liver and typically does NOT require renal dose adjustment?", "opts": ["Gabapentin", "Levetiracetam", "Diazepam", "Pregabalin"], "ans": 2, "expl": "Diazepam is hepatically metabolized and does not require significant dose adjustment in renal failure, unlike gabapentin, levetiracetam, and pregabalin which are renally eliminated.", "obj": 5}, {"topic": "Drug Dosing in Renal Failure", "q": "The primary mechanism by which ACE inhibitors protect kidneys in CKD is:", "opts": ["Increasing GFR directly", "Reducing intraglomerular pressure", "Increasing sodium reabsorption", "Blocking aldosterone only"], "ans": 1, "expl": "ACE inhibitors dilate efferent arterioles, reducing intraglomerular pressure and proteinuria, which slows CKD progression.", "obj": 2}, {"topic": "Drug Dosing in Renal Failure", "q": "Which electrolyte abnormality is a concern when using ACE inhibitors or ARBs in CKD?", "opts": ["Hypokalemia", "Hyperkalemia", "Hyponatremia", "Hypercalcemia"], "ans": 1, "expl": "ACE inhibitors and ARBs reduce aldosterone secretion, potentially causing hyperkalemia, especially in advanced CKD.", "obj": 5}, {"topic": "Drug Dosing in Renal Failure", "q": "Low molecular weight heparin (LMWH) in severe renal failure should be:", "opts": ["Used at standard doses", "Avoided or dose-reduced with monitoring", "Increased in dose", "Given only subcutaneously"], "ans": 1, "expl": "LMWH accumulates in renal failure, increasing bleeding risk; unfractionated heparin is often preferred, or LMWH with dose reduction and anti-Xa monitoring.", "obj": 5}, {"topic": "Drug Dosing in Renal Failure", "q": "Which opioid is safest to use in patients with severe renal impairment?", "opts": ["Morphine", "Meperidine", "Fentanyl", "Codeine"], "ans": 2, "expl": "Fentanyl is hepatically metabolized and does not produce active renally-cleared metabolites, making it safer than morphine, meperidine, or codeine in renal failure.", "obj": 5}, {"topic": "Drug Dosing in Renal Failure", "q": "Allopurinol dosing in CKD should be:", "opts": ["Increased to achieve uric acid goals", "Started low and titrated slowly", "Discontinued entirely", "Given only during dialysis"], "ans": 1, "expl": "Allopurinol and its active metabolite accumulate in CKD; start with low doses (50-100 mg) and titrate slowly to avoid toxicity.", "obj": 5}, {"topic": "Drug Dosing in Renal Failure", "q": "Which H2 blocker requires the most significant dose reduction in renal failure?", "opts": ["Famotidine", "Ranitidine", "Cimetidine", "All require similar adjustment"], "ans": 0, "expl": "Famotidine is primarily renally eliminated and requires significant dose reduction; all H2 blockers need adjustment but famotidine is most commonly used with renal dosing.", "obj": 5}, {"topic": "Drug Dosing in Renal Failure", "q": "Baclofen toxicity in CKD patients typically presents as:", "opts": ["Seizures and confusion", "Hypertension", "Hyperglycemia", "Rash"], "ans": 0, "expl": "Baclofen is renally eliminated and can cause severe CNS toxicity including seizures, confusion, and coma in CKD patients; avoid or use extreme caution.", "obj": 5}, {"topic": "Drug Dosing in Renal Failure", "q": "Which statin requires the least renal dose adjustment?", "opts": ["Atorvastatin", "Rosuvastatin", "Pravastatin", "Simvastatin"], "ans": 0, "expl": "Atorvastatin is primarily hepatically metabolized and does not require significant dose adjustment in renal failure, unlike rosuvastatin and pravastatin.", "obj": 5}, {"topic": "Drug Dosing in Renal Failure", "q": "The timing of antibiotic dosing relative to hemodialysis depends mainly on:", "opts": ["Patient preference", "Drug dialyzability and half-life", "Cost of medication", "Time of day"], "ans": 1, "expl": "Antibiotics that are highly dialyzable should be dosed after hemodialysis; those with long half-lives may not require timing adjustment.", "obj": 5}, {"topic": "Drug Dosing in Renal Failure", "q": "Which medication should be held on the day of contrast imaging in CKD patients?", "opts": ["Lisinopril", "Metformin", "Levothyroxine", "Omeprazole"], "ans": 1, "expl": "Metformin should be held before and after contrast procedures in CKD patients to reduce the risk of lactic acidosis if contrast-induced nephropathy occurs.", "obj": 5}, {"topic": "Acid-Base Disorders", "q": "A patient with diabetic ketoacidosis presents with pH 7.25, HCO3- 14 mEq/L, and PaCO2 30 mmHg. What is the primary acid-base disorder?", "opts": ["Metabolic acidosis", "Metabolic alkalosis", "Respiratory acidosis", "Respiratory alkalosis"], "ans": 0, "expl": "Low pH and low bicarbonate indicate metabolic acidosis. The low PaCO2 represents appropriate respiratory compensation.", "obj": 1}, {"topic": "Acid-Base Disorders", "q": "Which formula is used to calculate the anion gap?", "opts": ["Na+ - (Cl- + HCO3-)", "Na+ + (Cl- + HCO3-)", "(Na+ + K+) - Cl-", "Cl- - (Na+ + HCO3-)"], "ans": 0, "expl": "Anion gap = Na+ - (Cl- + HCO3-). Normal range is typically 8-12 mEq/L, though this varies by lab.", "obj": 1}, {"topic": "Acid-Base Disorders", "q": "A patient has pH 7.50, HCO3- 32 mEq/L, and PaCO2 45 mmHg. What is the primary disorder?", "opts": ["Metabolic alkalosis", "Respiratory alkalosis", "Metabolic acidosis", "Respiratory acidosis"], "ans": 0, "expl": "Elevated pH and elevated bicarbonate indicate metabolic alkalosis. The PaCO2 is not low enough to suggest primary respiratory alkalosis.", "obj": 1}, {"topic": "Acid-Base Disorders", "q": "In respiratory acidosis, what is the expected compensatory response?", "opts": ["Increased renal bicarbonate reabsorption", "Decreased renal bicarbonate reabsorption", "Increased respiratory rate", "Decreased carbonic anhydrase activity"], "ans": 0, "expl": "In chronic respiratory acidosis, the kidneys compensate by increasing bicarbonate reabsorption to buffer the acidemia.", "obj": 1}, {"topic": "Acid-Base Disorders", "q": "Which condition is associated with a high anion gap metabolic acidosis?", "opts": ["Diabetic ketoacidosis", "Diarrhea", "Renal tubular acidosis type 1", "Excessive antacid use"], "ans": 0, "expl": "DKA produces ketoacids (beta-hydroxybutyrate, acetoacetate) that increase the anion gap. Diarrhea and RTA cause normal anion gap acidosis.", "obj": 1}, {"topic": "Acid-Base Disorders", "q": "Winter's formula is used to assess compensation in which disorder?", "opts": ["Metabolic acidosis", "Metabolic alkalosis", "Respiratory acidosis", "Respiratory alkalosis"], "ans": 0, "expl": "Winter's formula (expected PaCO2 = 1.5 \u00d7 HCO3- + 8 \u00b1 2) predicts appropriate respiratory compensation in metabolic acidosis.", "obj": 1}, {"topic": "Acid-Base Disorders", "q": "A patient with chronic kidney disease stage 4 is most likely to develop which acid-base disorder?", "opts": ["Normal anion gap metabolic acidosis", "High anion gap metabolic acidosis", "Metabolic alkalosis", "Respiratory alkalosis"], "ans": 1, "expl": "Advanced CKD (stage 4-5) causes high anion gap metabolic acidosis from retention of unmeasured organic anions (sulfates, phosphates, urate). Normal anion gap acidosis is more typical of early CKD (stages 2-3) or RTA.", "obj": 1}, {"topic": "Acid-Base Disorders", "q": "Type 1 (distal) renal tubular acidosis is characterized by which defect?", "opts": ["Inability to acidify urine in the distal tubule", "Impaired bicarbonate reabsorption in proximal tubule", "Aldosterone deficiency", "Aldosterone resistance"], "ans": 0, "expl": "Distal RTA involves defective hydrogen ion secretion in the distal nephron, preventing urine acidification despite systemic acidosis.", "obj": 1}, {"topic": "Acid-Base Disorders", "q": "Which electrolyte abnormality is commonly associated with metabolic alkalosis?", "opts": ["Hypokalemia", "Hyperkalemia", "Hypercalcemia", "Hypermagnesemia"], "ans": 0, "expl": "Metabolic alkalosis often causes hypokalemia due to intracellular potassium shifts and increased renal potassium wasting.", "obj": 1}, {"topic": "Acid-Base Disorders", "q": "Lactic acidosis in sepsis is primarily caused by:", "opts": ["Tissue hypoperfusion and anaerobic metabolism", "Excessive lactate administration", "Impaired hepatic lactate clearance only", "Renal lactate overproduction"], "ans": 0, "expl": "In sepsis, tissue hypoperfusion leads to anaerobic metabolism, producing lactate. Impaired clearance also contributes.", "obj": 1}, {"topic": "Acid-Base Disorders", "q": "A patient presents with pH 7.30, PaCO2 50 mmHg, HCO3- 24 mEq/L. What is the primary disorder?", "opts": ["Respiratory acidosis", "Metabolic acidosis", "Respiratory alkalosis", "Metabolic alkalosis"], "ans": 0, "expl": "Low pH with elevated PaCO2 indicates respiratory acidosis. Bicarbonate is normal, suggesting acute presentation without compensation.", "obj": 1}, {"topic": "Acid-Base Disorders", "q": "Which medication can cause metabolic acidosis by inhibiting carbonic anhydrase?", "opts": ["Acetazolamide", "Furosemide", "Spironolactone", "Lisinopril"], "ans": 0, "expl": "Acetazolamide inhibits carbonic anhydrase in the proximal tubule, reducing bicarbonate reabsorption and causing metabolic acidosis.", "obj": 5}, {"topic": "Acid-Base Disorders", "q": "In a patient with metabolic alkalosis, a urine chloride level less than 10 mEq/L suggests:", "opts": ["Saline-responsive alkalosis", "Saline-resistant alkalosis", "Primary hyperaldosteronism", "Renal artery stenosis"], "ans": 0, "expl": "Low urine chloride indicates volume depletion and chloride-responsive alkalosis (e.g., from vomiting or diuretic use).", "obj": 1}, {"topic": "Acid-Base Disorders", "q": "Type 4 renal tubular acidosis is associated with:", "opts": ["Hyperkalemia and aldosterone deficiency or resistance", "Hypokalemia and distal acidification defect", "Bicarbonate wasting in proximal tubule", "Normal potassium with severe acidosis"], "ans": 0, "expl": "Type 4 RTA involves hypoaldosteronism or aldosterone resistance, causing hyperkalemia and impaired ammonium excretion.", "obj": 1}, {"topic": "Acid-Base Disorders", "q": "Which is the most appropriate initial treatment for severe metabolic acidosis (pH < 7.1) in DKA?", "opts": ["IV fluids and insulin therapy", "IV sodium bicarbonate bolus", "Oral bicarbonate tablets", "Mechanical ventilation"], "ans": 0, "expl": "DKA is treated with fluids and insulin to stop ketone production. Bicarbonate is rarely needed and may worsen outcomes.", "obj": 2}, {"topic": "Acid-Base Disorders", "q": "A patient with anxiety presents with pH 7.55, PaCO2 25 mmHg, HCO3- 22 mEq/L. What is the diagnosis?", "opts": ["Acute respiratory alkalosis", "Chronic respiratory alkalosis", "Metabolic alkalosis", "Metabolic acidosis"], "ans": 0, "expl": "High pH with low PaCO2 indicates respiratory alkalosis. Normal bicarbonate suggests acute presentation without renal compensation.", "obj": 1}, {"topic": "Acid-Base Disorders", "q": "The normal anion gap range is approximately:", "opts": ["8-12 mEq/L", "2-6 mEq/L", "15-20 mEq/L", "20-25 mEq/L"], "ans": 0, "expl": "Normal anion gap is typically 8-12 mEq/L, though reference ranges vary. Albumin correction may be needed in hypoalbuminemia.", "obj": 1}, {"topic": "Acid-Base Disorders", "q": "Which condition causes metabolic alkalosis through mineralocorticoid excess?", "opts": ["Primary hyperaldosteronism", "Addison's disease", "Type 4 RTA", "Diarrhea"], "ans": 0, "expl": "Hyperaldosteronism increases sodium reabsorption and hydrogen/potassium excretion, causing metabolic alkalosis and hypokalemia.", "obj": 1}, {"topic": "Acid-Base Disorders", "q": "In chronic respiratory alkalosis, the expected renal compensation is:", "opts": ["Decreased bicarbonate reabsorption", "Increased bicarbonate reabsorption", "Increased acid excretion", "No renal compensation"], "ans": 0, "expl": "Chronic respiratory alkalosis causes renal compensation through decreased bicarbonate reabsorption, lowering serum bicarbonate.", "obj": 1}, {"topic": "Acid-Base Disorders", "q": "Bicarbonate therapy in CKD patients is indicated when serum bicarbonate is:", "opts": ["Less than 22 mEq/L", "Less than 18 mEq/L only", "Greater than 26 mEq/L", "Any value below normal"], "ans": 0, "expl": "KDIGO guidelines suggest oral bicarbonate supplementation when serum bicarbonate is persistently below 22 mEq/L in CKD.", "obj": 2}, {"topic": "Fluid and Electrolyte Emergencies", "q": "A patient with chronic kidney disease presents with peaked T waves and widened QRS on ECG. Which electrolyte abnormality is most likely?", "opts": ["Hyperkalemia", "Hypokalemia", "Hypercalcemia", "Hyponatremia"], "ans": 0, "expl": "Peaked T waves and widened QRS are classic ECG findings in hyperkalemia, a life-threatening emergency in CKD patients requiring immediate intervention.", "obj": 1}, {"topic": "Fluid and Electrolyte Emergencies", "q": "Which medication is administered first to stabilize cardiac membranes in severe hyperkalemia?", "opts": ["Insulin with dextrose", "Calcium gluconate", "Sodium polystyrene sulfonate", "Albuterol"], "ans": 1, "expl": "Calcium gluconate is given first to stabilize cardiac membranes and prevent arrhythmias, though it does not lower potassium levels.", "obj": 5}, {"topic": "Fluid and Electrolyte Emergencies", "q": "A patient with SIADH typically presents with which sodium level pattern?", "opts": ["Hypernatremia with concentrated urine", "Hyponatremia with inappropriately concentrated urine", "Hyponatremia with dilute urine", "Normal sodium with polyuria"], "ans": 1, "expl": "SIADH causes hyponatremia with inappropriately concentrated urine due to excess ADH secretion leading to water retention.", "obj": 1}, {"topic": "Fluid and Electrolyte Emergencies", "q": "Rapid correction of chronic hyponatremia can lead to which serious complication?", "opts": ["Cerebral edema", "Osmotic demyelination syndrome", "Hyperkalemia", "Pulmonary edema"], "ans": 1, "expl": "Osmotic demyelination syndrome (central pontine myelinolysis) occurs when chronic hyponatremia is corrected too rapidly, causing irreversible neurologic damage.", "obj": 1}, {"topic": "Fluid and Electrolyte Emergencies", "q": "Which finding is most characteristic of hypercalcemia?", "opts": ["Trousseau sign", "Chvostek sign", "Shortened QT interval", "Prolonged QT interval"], "ans": 2, "expl": "Hypercalcemia shortens the QT interval on ECG. Trousseau and Chvostek signs are associated with hypocalcemia.", "obj": 1}, {"topic": "Fluid and Electrolyte Emergencies", "q": "A patient with hypermagnesemia is most likely to exhibit which symptom?", "opts": ["Hyperreflexia", "Hypotension and bradycardia", "Tetany", "Seizures"], "ans": 1, "expl": "Hypermagnesemia causes hypotension, bradycardia, decreased deep tendon reflexes, and can progress to respiratory depression and cardiac arrest.", "obj": 1}, {"topic": "Fluid and Electrolyte Emergencies", "q": "Which intervention is appropriate for a patient with fluid overload and pulmonary edema?", "opts": ["Administer IV fluids", "Place patient in Trendelenburg position", "Administer IV loop diuretics", "Restrict oxygen"], "ans": 2, "expl": "IV loop diuretics like furosemide reduce fluid volume. Position patient upright, provide oxygen, and restrict fluids.", "obj": 2}, {"topic": "Fluid and Electrolyte Emergencies", "q": "Hyperphosphatemia in renal failure commonly leads to which secondary electrolyte disturbance?", "opts": ["Hypercalcemia", "Hypocalcemia", "Hypernatremia", "Hypokalemia"], "ans": 1, "expl": "Elevated phosphate binds with calcium, causing hypocalcemia. This triggers secondary hyperparathyroidism in chronic kidney disease.", "obj": 1}, {"topic": "Fluid and Electrolyte Emergencies", "q": "Which ECG change is associated with hypocalcemia?", "opts": ["Shortened QT", "Prolonged QT", "Peaked T waves", "U waves"], "ans": 1, "expl": "Hypocalcemia prolongs the QT interval, increasing risk for ventricular arrhythmias including torsades de pointes.", "obj": 1}, {"topic": "Fluid and Electrolyte Emergencies", "q": "A patient with diabetes insipidus would most likely present with:", "opts": ["Hyponatremia and concentrated urine", "Hypernatremia and dilute urine", "Hyperkalemia and oliguria", "Hypocalcemia and polyuria"], "ans": 1, "expl": "Diabetes insipidus causes inability to concentrate urine, leading to polyuria, dehydration, and hypernatremia.", "obj": 1}, {"topic": "Fluid and Electrolyte Emergencies", "q": "Which treatment shifts potassium into cells for temporary management of hyperkalemia?", "opts": ["Calcium chloride", "Sodium bicarbonate", "Furosemide", "Sodium polystyrene sulfonate"], "ans": 1, "expl": "Sodium bicarbonate, insulin with dextrose, and beta-agonists shift potassium intracellularly. Definitive removal requires dialysis or binders.", "obj": 2}, {"topic": "Fluid and Electrolyte Emergencies", "q": "Severe hypomagnesemia is often associated with which other electrolyte abnormality?", "opts": ["Hypercalcemia", "Hypokalemia", "Hypernatremia", "Hyperphosphatemia"], "ans": 1, "expl": "Hypomagnesemia causes renal potassium wasting and impairs PTH secretion, often resulting in concurrent hypokalemia and hypocalcemia.", "obj": 1}, {"topic": "Fluid and Electrolyte Emergencies", "q": "Which assessment finding indicates worsening hyperkalemia?", "opts": ["Muscle cramps", "Narrow QRS complex", "Sinus bradycardia", "Increased urine output"], "ans": 2, "expl": "Progressive hyperkalemia causes bradycardia, heart block, and can deteriorate to ventricular fibrillation or asystole.", "obj": 1}, {"topic": "Fluid and Electrolyte Emergencies", "q": "A patient with hypernatremia and hypovolemia should initially receive:", "opts": ["Hypotonic saline", "Isotonic saline", "Hypertonic saline", "Oral water only"], "ans": 1, "expl": "Isotonic saline restores intravascular volume first. Once hemodynamically stable, free water deficit is corrected gradually.", "obj": 2}, {"topic": "Fluid and Electrolyte Emergencies", "q": "Which condition is a common cause of hyperkalemia in dialysis patients?", "opts": ["Excessive diarrhea", "Missed dialysis treatment", "Hyperaldosteronism", "Loop diuretic use"], "ans": 1, "expl": "Missed dialysis treatments allow potassium to accumulate. Dialysis patients have limited renal potassium excretion.", "obj": 1}, {"topic": "Fluid and Electrolyte Emergencies", "q": "Trousseau sign is elicited by:", "opts": ["Tapping the facial nerve", "Inflating a blood pressure cuff", "Checking deep tendon reflexes", "Observing gait"], "ans": 1, "expl": "Trousseau sign is carpal spasm induced by inflating a BP cuff above systolic pressure for 3 minutes, indicating hypocalcemia.", "obj": 1}, {"topic": "Fluid and Electrolyte Emergencies", "q": "Which medication can cause hyperkalemia as a side effect?", "opts": ["Furosemide", "Spironolactone", "Albuterol", "Insulin"], "ans": 1, "expl": "Spironolactone is a potassium-sparing diuretic that can cause hyperkalemia, especially in patients with renal impairment.", "obj": 5}, {"topic": "Fluid and Electrolyte Emergencies", "q": "The most appropriate initial nursing action for a patient with severe symptomatic hyponatremia is:", "opts": ["Administer hypertonic saline", "Restrict all fluids", "Encourage oral water intake", "Administer hypotonic fluids"], "ans": 0, "expl": "Severe symptomatic hyponatremia with seizures or altered mental status requires cautious hypertonic saline administration.", "obj": 2}, {"topic": "Fluid and Electrolyte Emergencies", "q": "Which lab value indicates the severity of hypercalcemia crisis?", "opts": ["Serum albumin", "Ionized calcium", "Serum phosphate", "BUN level"], "ans": 1, "expl": "Ionized calcium represents the biologically active form and best reflects severity of hypercalcemia, independent of albumin levels.", "obj": 1}, {"topic": "Fluid and Electrolyte Emergencies", "q": "A patient receiving rapid blood transfusions is at risk for which electrolyte imbalance?", "opts": ["Hypokalemia", "Hyperkalemia", "Hypercalcemia", "Hyponatremia"], "ans": 1, "expl": "Stored blood contains high potassium levels from cell lysis. Rapid transfusion can cause hyperkalemia, especially in renal patients.", "obj": 1}, {"topic": "Transplant Pharmacology", "q": "Which immunosuppressant requires therapeutic drug monitoring due to its narrow therapeutic index and risk of nephrotoxicity?", "opts": ["Tacrolimus", "Mycophenolate mofetil", "Prednisone", "Basiliximab"], "ans": 0, "expl": "Tacrolimus is a calcineurin inhibitor with a narrow therapeutic window requiring regular blood level monitoring to balance efficacy against nephrotoxicity and other adverse effects.", "obj": 5}, {"topic": "Transplant Pharmacology", "q": "What is the primary mechanism of action of tacrolimus?", "opts": ["Inhibits calcineurin, reducing IL-2 production", "Blocks purine synthesis in lymphocytes", "Inhibits mTOR pathway", "Binds to IL-2 receptor on T-cells"], "ans": 0, "expl": "Tacrolimus binds to FKBP-12, inhibiting calcineurin and preventing dephosphorylation of NFAT, which reduces IL-2 transcription and T-cell activation.", "obj": 5}, {"topic": "Transplant Pharmacology", "q": "Which food should transplant patients avoid while taking calcineurin inhibitors?", "opts": ["Grapefruit", "Bananas", "Spinach", "Orange juice"], "ans": 0, "expl": "Grapefruit inhibits CYP3A4 metabolism, significantly increasing blood levels of tacrolimus and cyclosporine, raising toxicity risk.", "obj": 4}, {"topic": "Transplant Pharmacology", "q": "What is a common side effect specific to cyclosporine but less common with tacrolimus?", "opts": ["Gingival hyperplasia", "New-onset diabetes", "Tremor", "Diarrhea"], "ans": 0, "expl": "Gingival hyperplasia occurs in up to 30% of patients on cyclosporine but is rare with tacrolimus, making it a distinguishing side effect.", "obj": 5}, {"topic": "Transplant Pharmacology", "q": "Which immunosuppressant is most associated with bone marrow suppression and leukopenia?", "opts": ["Mycophenolate mofetil", "Tacrolimus", "Prednisone", "Sirolimus"], "ans": 0, "expl": "Mycophenolate inhibits inosine monophosphate dehydrogenase, affecting rapidly dividing cells including bone marrow, leading to leukopenia and anemia.", "obj": 5}, {"topic": "Transplant Pharmacology", "q": "What is the mechanism of action of basiliximab?", "opts": ["IL-2 receptor antagonist on activated T-cells", "Calcineurin inhibitor", "mTOR inhibitor", "Antithymocyte globulin"], "ans": 0, "expl": "Basiliximab is a chimeric monoclonal antibody that binds to the alpha chain of the IL-2 receptor, preventing T-cell activation during induction therapy.", "obj": 5}, {"topic": "Transplant Pharmacology", "q": "Which medication requires monitoring for new-onset diabetes after transplant (NODAT)?", "opts": ["Tacrolimus", "Mycophenolate", "Azathioprine", "Basiliximab"], "ans": 0, "expl": "Tacrolimus impairs pancreatic beta-cell function and insulin secretion, with NODAT occurring in 10-20% of transplant recipients.", "obj": 5}, {"topic": "Transplant Pharmacology", "q": "What is the primary advantage of using antithymocyte globulin (ATG) for induction?", "opts": ["Potent T-cell depletion", "Oral administration", "No infection risk", "No monitoring required"], "ans": 0, "expl": "ATG causes profound T-cell depletion through complement-mediated lysis, providing powerful induction immunosuppression for high-risk patients.", "obj": 5}, {"topic": "Transplant Pharmacology", "q": "Which drug interaction would significantly increase tacrolimus levels?", "opts": ["Fluconazole", "Omeprazole", "Metformin", "Amlodipine"], "ans": 0, "expl": "Azole antifungals like fluconazole are strong CYP3A4 inhibitors that can double or triple tacrolimus levels, requiring dose reduction and close monitoring.", "obj": 5}, {"topic": "Transplant Pharmacology", "q": "What is a key nursing consideration when administering mycophenolate?", "opts": ["Monitor for signs of infection and bleeding", "Administer with grapefruit juice", "Check blood glucose before dosing", "Give only in the morning"], "ans": 0, "expl": "Mycophenolate causes immunosuppression and bone marrow suppression, requiring monitoring for infection signs and bleeding tendencies.", "obj": 5}, {"topic": "Transplant Pharmacology", "q": "Which immunosuppressant is associated with hyperlipidemia as a common side effect?", "opts": ["Sirolimus", "Tacrolimus", "Basiliximab", "Azathioprine"], "ans": 0, "expl": "Sirolimus (an mTOR inhibitor) commonly causes elevated cholesterol and triglycerides, requiring lipid monitoring and possible statin therapy.", "obj": 5}, {"topic": "Transplant Pharmacology", "q": "What is the typical therapeutic trough range for tacrolimus in the early post-transplant period?", "opts": ["8-12 ng/mL", "2-4 ng/mL", "15-20 ng/mL", "20-25 ng/mL"], "ans": 0, "expl": "Early post-transplant tacrolimus trough targets are typically 8-12 ng/mL, though ranges vary by institution and transplant type.", "obj": 5}, {"topic": "Transplant Pharmacology", "q": "Which medication is a prodrug converted to 6-mercaptopurine in the body?", "opts": ["Azathioprine", "Mycophenolate mofetil", "Tacrolimus", "Cyclosporine"], "ans": 0, "expl": "Azathioprine is metabolized to 6-mercaptopurine, which interferes with DNA synthesis in proliferating lymphocytes.", "obj": 5}, {"topic": "Transplant Pharmacology", "q": "What is the most appropriate action when a patient on cyclosporine develops elevated creatinine?", "opts": ["Notify provider for possible dose adjustment", "Immediately discontinue the medication", "Increase the dose", "Switch to oral administration"], "ans": 0, "expl": "Calcineurin inhibitor nephrotoxicity is dose-dependent; elevated creatinine requires provider notification for potential dose reduction.", "obj": 5}, {"topic": "Transplant Pharmacology", "q": "Which statement about steroid therapy in transplant is correct?", "opts": ["Long-term use causes osteoporosis and weight gain", "Steroids are never used in maintenance therapy", "Steroids have no metabolic side effects", "Steroids should be stopped abruptly"], "ans": 0, "expl": "Chronic prednisone use causes bone density loss, weight gain, hyperglycemia, and adrenal suppression requiring gradual tapering.", "obj": 5}, {"topic": "Transplant Pharmacology", "q": "What monitoring is essential for patients on sirolimus?", "opts": ["Lipid panel and complete blood count", "Blood glucose only", "Liver enzymes only", "Urinalysis weekly"], "ans": 0, "expl": "Sirolimus causes hyperlipidemia, thrombocytopenia, and anemia, requiring regular lipid panels and CBC monitoring.", "obj": 5}, {"topic": "Transplant Pharmacology", "q": "Which immunosuppressant is most nephrotoxic?", "opts": ["Cyclosporine", "Mycophenolate", "Prednisone", "Azathioprine"], "ans": 0, "expl": "Both cyclosporine and tacrolimus cause dose-dependent nephrotoxicity through afferent arteriole vasoconstriction, but cyclosporine has higher rates.", "obj": 5}, {"topic": "Transplant Pharmacology", "q": "What is the purpose of therapeutic drug monitoring in transplant patients?", "opts": ["Maintain therapeutic levels while minimizing toxicity", "Determine if the patient is compliant", "Calculate the exact dose needed", "Diagnose rejection episodes"], "ans": 0, "expl": "TDM ensures drug levels stay within the therapeutic window, balancing rejection prevention against toxicity risks.", "obj": 5}, {"topic": "Transplant Pharmacology", "q": "Which vaccine should be avoided in transplant patients on immunosuppression?", "opts": ["Live attenuated vaccines", "Inactivated influenza vaccine", "Hepatitis B vaccine", "Tetanus toxoid"], "ans": 0, "expl": "Live vaccines (MMR, varicella, live attenuated influenza) are contraindicated due to risk of vaccine-derived infection in immunosuppressed patients.", "obj": 4}, {"topic": "Transplant Pharmacology", "q": "What is a key difference between tacrolimus and cyclosporine?", "opts": ["Tacrolimus has higher diabetes risk; cyclosporine causes more gingival hyperplasia", "They have identical side effect profiles", "Cyclosporine is more potent than tacrolimus", "Tacrolimus requires no monitoring"], "ans": 0, "expl": "While both are calcineurin inhibitors, tacrolimus carries higher NODAT risk, while cyclosporine more commonly causes gingival hyperplasia and hirsutism.", "obj": 5}];
const ORIG_FLASHCARDS = [{"topic": "Kidney Disease", "front": "Acute Kidney Injury (AKI)", "back": "Sudden decline in kidney function over hours to days, characterized by increased creatinine and/or decreased urine output."}, {"topic": "Kidney Disease", "front": "Chronic Kidney Disease (CKD)", "back": "Progressive, irreversible loss of kidney function over 3+ months, classified into 5 stages based on GFR."}, {"topic": "Kidney Disease", "front": "Prerenal AKI", "back": "Kidney dysfunction caused by decreased blood flow to the kidneys before the renal tissue itself is damaged."}, {"topic": "Kidney Disease", "front": "Intrarenal AKI", "back": "Kidney damage occurring within the kidney tissue itself, often from toxins, ischemia, or inflammation."}, {"topic": "Kidney Disease", "front": "Postrenal AKI", "back": "Kidney dysfunction caused by obstruction of urine flow after it leaves the kidneys."}, {"topic": "Kidney Disease", "front": "Acute Tubular Necrosis (ATN)", "back": "Death of tubular epithelial cells, usually from ischemia or nephrotoxins, causing intrinsic AKI."}, {"topic": "Kidney Disease", "front": "Glomerular Filtration Rate (GFR)", "back": "Volume of fluid filtered by glomeruli per minute; best measure of overall kidney function."}, {"topic": "Kidney Disease", "front": "Nephrotic Syndrome", "back": "Clinical syndrome with heavy proteinuria (>3.5g/day), hypoalbuminemia, edema, and hyperlipidemia."}, {"topic": "Kidney Disease", "front": "Nephritic Syndrome", "back": "Clinical syndrome with hematuria, RBC casts, hypertension, and mild-to-moderate proteinuria."}, {"topic": "Kidney Disease", "front": "IgA Nephropathy", "back": "Most common glomerulonephritis; immune complex deposition in glomeruli causing hematuria and proteinuria."}, {"topic": "Kidney Disease", "front": "Hyperkalemia", "back": "Elevated serum potassium (>5.0 mEq/L); dangerous in CKD due to risk of cardiac arrhythmias."}, {"topic": "Kidney Disease", "front": "Uremia", "back": "Clinical syndrome of kidney failure with accumulation of nitrogenous wastes causing nausea, confusion, and pericarditis."}, {"topic": "Kidney Disease", "front": "Erythropoietin", "back": "Hormone produced by kidneys that stimulates red blood cell production; deficient in CKD."}, {"topic": "Kidney Disease", "front": "Metabolic Acidosis in CKD", "back": "Low blood pH from impaired hydrogen ion excretion and bicarbonate regeneration by damaged kidneys."}, {"topic": "Kidney Disease", "front": "Renal Replacement Therapy", "back": "Treatments that replace kidney function: hemodialysis, peritoneal dialysis, or kidney transplantation."}, {"topic": "Kidney Disease", "front": "Muddy Brown Casts", "back": "Granular casts in urine sediment pathognomonic for acute tubular necrosis."}, {"topic": "Kidney Disease", "front": "Oliguria", "back": "Reduced urine output (<400 mL/day in adults); common sign of AKI."}, {"topic": "Kidney Disease", "front": "Hyperphosphatemia", "back": "Elevated serum phosphate; common in CKD due to decreased excretion, leading to bone disease."}, {"topic": "Kidney Disease", "front": "Diabetic Nephropathy", "back": "Kidney damage from diabetes; leading cause of CKD and end-stage renal disease worldwide."}, {"topic": "Kidney Disease", "front": "K/DOQI Guidelines", "back": "Clinical practice guidelines for CKD evaluation, classification, and management by National Kidney Foundation."}, {"topic": "Hemodialysis", "front": "Diffusion", "back": "Movement of solutes from high to low concentration across a semipermeable membrane; primary clearance mechanism in HD"}, {"topic": "Hemodialysis", "front": "Convection", "back": "Solute movement with water flow across membrane (solvent drag); important for middle molecule clearance"}, {"topic": "Hemodialysis", "front": "Ultrafiltration", "back": "Removal of excess fluid by applying hydrostatic pressure across the dialyzer membrane"}, {"topic": "Hemodialysis", "front": "Kt/V", "back": "Measure of dialysis adequacy: K=clearance, t=time, V=volume of urea distribution; minimum 1.2 recommended"}, {"topic": "Hemodialysis", "front": "Arteriovenous Fistula (AVF)", "back": "Surgical connection of artery to vein; gold standard access with lowest infection risk and best patency"}, {"topic": "Hemodialysis", "front": "Arteriovenous Graft (AVG)", "back": "Synthetic tube connecting artery to vein; matures faster than AVF but higher infection and thrombosis risk"}, {"topic": "Hemodialysis", "front": "Dialyzer", "back": "Artificial kidney containing semipermeable membrane where blood and dialysate flow in opposite directions"}, {"topic": "Hemodialysis", "front": "Dialysate", "back": "Specially formulated solution containing electrolytes and bicarbonate that flows counter-current to blood in dialyzer"}, {"topic": "Hemodialysis", "front": "Heparin", "back": "Anticoagulant used during HD to prevent clotting in extracorporeal circuit"}, {"topic": "Hemodialysis", "front": "Intradialytic Hypotension", "back": "Most common HD complication; drop in BP during treatment due to rapid fluid removal or autonomic dysfunction"}, {"topic": "Hemodialysis", "front": "Dialysis Disequilibrium Syndrome", "back": "Neurological complication from rapid solute removal causing cerebral edema; presents with headache, confusion, seizures"}, {"topic": "Hemodialysis", "front": "Air Embolism", "back": "Life-threatening complication when air enters circulation; symptoms include chest pain, dyspnea; treat with left lateral decubitus position"}, {"topic": "Hemodialysis", "front": "High-Flux Dialyzer", "back": "Dialyzer with larger pores allowing better middle molecule clearance (e.g., beta-2 microglobulin)"}, {"topic": "Hemodialysis", "front": "Thrill", "back": "Vibration felt over functioning AV access; absence suggests thrombosis or stenosis"}, {"topic": "Hemodialysis", "front": "Bruit", "back": "Whooshing sound heard over AV access with stethoscope; indicates blood flow through access"}, {"topic": "Hemodialysis", "front": "Steal Syndrome", "back": "Complication where access diverts blood flow away from hand, causing ischemia, pain, and coolness"}, {"topic": "Hemodialysis", "front": "Dialysate Sodium", "back": "Typically 135-145 mEq/L; matches serum levels to prevent osmotic shifts and cramping"}, {"topic": "Hemodialysis", "front": "Cool Dialysate", "back": "Temperature 35-36\u00b0C; promotes vasoconstriction and reduces intradialytic hypotension"}, {"topic": "Hemodialysis", "front": "Beta-2 Microglobulin", "back": "Middle molecule toxin cleared better by high-flux dialyzers; accumulates in ESRD causing amyloidosis"}, {"topic": "Hemodialysis", "front": "Extracorporeal Circuit", "back": "Blood pathway outside body during HD: access \u2192 blood tubing \u2192 dialyzer \u2192 return to patient"}, {"topic": "Peritoneal Dialysis", "front": "Tenckhoff catheter", "back": "Most common PD catheter type; silicone tube with one or two cuffs for tissue ingrowth and infection barrier."}, {"topic": "Peritoneal Dialysis", "front": "Exit-site infection", "back": "Infection at catheter skin exit characterized by erythema, tenderness, and/or purulent drainage."}, {"topic": "Peritoneal Dialysis", "front": "Peritonitis (PD)", "back": "Inflammation of peritoneal membrane; diagnosed by cloudy effluent, abdominal pain, and/or WBC >100/\u03bcL in effluent."}, {"topic": "Peritoneal Dialysis", "front": "Peritoneal Equilibration Test (PET)", "back": "4-hour test measuring solute transport rate; classifies patients as high/low transporters to guide prescription."}, {"topic": "Peritoneal Dialysis", "front": "High transporter", "back": "Patient with rapid solute equilibration; loses osmotic gradient quickly, needs shorter dwells or icodextrin."}, {"topic": "Peritoneal Dialysis", "front": "Low transporter", "back": "Patient with slow solute equilibration; benefits from longer dwells for adequate clearance."}, {"topic": "Peritoneal Dialysis", "front": "CAPD", "back": "Continuous Ambulatory Peritoneal Dialysis; manual exchanges 4-5 times daily without machine."}, {"topic": "Peritoneal Dialysis", "front": "CCPD", "back": "Continuous Cyclic Peritoneal Dialysis; machine-assisted overnight exchanges with daytime dwell."}, {"topic": "Peritoneal Dialysis", "front": "Ultrafiltration", "back": "Fluid removal across peritoneal membrane driven by osmotic gradient from glucose or icodextrin."}, {"topic": "Peritoneal Dialysis", "front": "Ultrafiltration failure", "back": "Inability to achieve adequate fluid removal despite hypertonic exchanges; may indicate membrane changes."}, {"topic": "Peritoneal Dialysis", "front": "Icodextrin", "back": "Glucose polymer osmotic agent for long dwells; maintains UF in high transporters and overnight."}, {"topic": "Peritoneal Dialysis", "front": "Dwell time", "back": "Duration dialysate remains in peritoneal cavity; affects solute clearance and ultrafiltration volume."}, {"topic": "Peritoneal Dialysis", "front": "Dialysate", "back": "Sterile solution containing electrolytes, buffer (lactate/bicarbonate), and osmotic agent (glucose/icodextrin)."}, {"topic": "Peritoneal Dialysis", "front": "Peritoneal membrane", "back": "Semipermeable membrane lining abdominal cavity; acts as dialysis barrier between blood and dialysate."}, {"topic": "Peritoneal Dialysis", "front": "Catheter cuff", "back": "Dacron or polyester material promoting tissue ingrowth to secure catheter and prevent infection migration."}, {"topic": "Peritoneal Dialysis", "front": "Break-in period", "back": "2-4 weeks post-catheter placement before full-volume PD; allows healing and reduces leak risk."}, {"topic": "Peritoneal Dialysis", "front": "Residual renal function", "back": "Remaining native kidney function; contributes significantly to total clearance in early PD patients."}, {"topic": "Peritoneal Dialysis", "front": "Peritoneal dialysis adequacy", "back": "Measured by Kt/V (target \u22651.7/week) and creatinine clearance (target \u226550 L/week/1.73m\u00b2)."}, {"topic": "Peritoneal Dialysis", "front": "Encapsulating Peritoneal Sclerosis", "back": "Rare severe complication with fibrous bowel encapsulation causing obstruction; requires surgery."}, {"topic": "Peritoneal Dialysis", "front": "Empiric peritonitis therapy", "back": "Initial antibiotics covering Gram-positive (vancomycin/cephalosporin) AND Gram-negative (ceftazidime/aminoglycoside)."}, {"topic": "Transplant", "front": "Hyperacute Rejection", "back": "Rejection occurring within minutes to hours due to pre-formed antibodies against donor antigens; causes immediate graft thrombosis and is prevented by proper crossmatch testing."}, {"topic": "Transplant", "front": "Delayed Graft Function (DGF)", "back": "Need for dialysis within the first week post-transplant; more common with deceased donors, prolonged cold ischemia time, and associated with increased acute rejection risk."}, {"topic": "Transplant", "front": "Calcineurin Inhibitor Nephrotoxicity", "back": "Dose-dependent kidney injury from tacrolimus or cyclosporine causing afferent arteriolar vasoconstriction; managed by therapeutic drug monitoring and dose adjustment."}, {"topic": "Transplant", "front": "CMV D+/R- Risk", "back": "Highest risk CMV scenario: seronegative recipient receives organ from seropositive donor; requires antiviral prophylaxis (valganciclovir) for 3-6 months minimum."}, {"topic": "Transplant", "front": "BK Virus Nephropathy", "back": "Polyomavirus infection of renal tubular cells causing interstitial nephritis and potential graft loss; screened via urine decoy cells or plasma viral load; treated by reducing immunosuppression."}, {"topic": "Transplant", "front": "Induction Therapy", "back": "Intense immunosuppression given at transplant (basiliximab or ATG) to prevent early acute rejection while allowing delayed introduction of nephrotoxic maintenance agents."}, {"topic": "Transplant", "front": "Triple Immunosuppression", "back": "Standard maintenance regimen: calcineurin inhibitor (tacrolimus) + antimetabolite (mycophenolate) + corticosteroid; provides synergistic effect with reduced individual drug toxicity."}, {"topic": "Transplant", "front": "Transplant Glomerulopathy", "back": "Hallmark of chronic antibody-mediated rejection; characterized by glomerular basement membrane double contours on biopsy, often with C4d deposition."}, {"topic": "Transplant", "front": "Panel Reactive Antibody (PRA)", "back": "Percentage of HLA antigens against which a patient has pre-formed antibodies; high PRA (>80%) indicates sensitization and makes finding compatible donors more difficult."}, {"topic": "Transplant", "front": "Cold Ischemia Time", "back": "Duration kidney is preserved on ice between procurement and implantation; longer times (>24 hours) increase risk of DGF and may impact long-term graft survival."}, {"topic": "Transplant", "front": "Donor-Specific Antibody (DSA)", "back": "HLA antibodies in recipient directed against donor antigens; detected by Luminex assay; associated with antibody-mediated rejection and poorer graft outcomes."}, {"topic": "Transplant", "front": "PJP Prophylaxis", "back": "Trimethoprim-sulfamethoxazole given for 6-12 months post-transplant to prevent Pneumocystis jirovecii pneumonia; also protects against Toxoplasma and some bacterial infections."}, {"topic": "Transplant", "front": "Post-Transplant Diabetes Mellitus (PTDM)", "back": "New-onset diabetes after transplantation; risk factors include tacrolimus, corticosteroids, obesity, and family history; requires glucose monitoring and may need insulin or oral agents."}, {"topic": "Transplant", "front": "Acute Cellular Rejection", "back": "T-cell mediated rejection typically occurring in first 3-6 months; diagnosed by biopsy showing tubulitis and interstitial inflammation; treated with pulse steroids."}, {"topic": "Transplant", "front": "Living Donor Advantage", "back": "Better outcomes than deceased donor due to HLA matching potential, shorter cold ischemia time, elective scheduling, and ability to transplant before dialysis dependence."}, {"topic": "Transplant", "front": "mTOR Inhibitors", "back": "Sirolimus and everolimus block IL-2 signaling pathway; used as alternative to calcineurin inhibitors; side effects include impaired wound healing, proteinuria, and hyperlipidemia."}, {"topic": "Transplant", "front": "Crossmatch Test", "back": "Pre-transplant test mixing recipient serum with donor lymphocytes; positive result indicates pre-formed antibodies and contraindicates transplantation due to hyperacute rejection risk."}, {"topic": "Transplant", "front": "Death with Functioning Graft", "back": "Leading cause of graft loss in first year; primarily from cardiovascular disease and infection; reflects success of rejection prevention but challenges with immunosuppression complications."}, {"topic": "Transplant", "front": "University of Wisconsin Solution", "back": "Standard preservation fluid for deceased donor kidneys; contains impermeants and substrates that minimize cellular injury during cold storage; allows 24-48 hour preservation."}, {"topic": "Transplant", "front": "Chronic Rejection", "back": "Slow graft deterioration over months to years; characterized by interstitial fibrosis, tubular atrophy, and/or transplant glomerulopathy; generally irreversible and leads to graft failure."}, {"topic": "Acute Therapies", "front": "Convection (CRRT)", "back": "Solute removal mechanism using hydrostatic pressure to create solvent drag across membrane; primary in CVVH"}, {"topic": "Acute Therapies", "front": "Diffusion (CRRT)", "back": "Solute removal via concentration gradient between blood and dialysate; primary mechanism in CVVHD"}, {"topic": "Acute Therapies", "front": "CVVH", "back": "Continuous Veno-Venous Hemofiltration: uses convection with replacement fluid for solute clearance"}, {"topic": "Acute Therapies", "front": "CVVHD", "back": "Continuous Veno-Venous Hemodialysis: uses diffusion with dialysate flow for solute clearance"}, {"topic": "Acute Therapies", "front": "CVVHDF", "back": "Continuous Veno-Venous Hemodiafiltration: combines convection and diffusion for maximal clearance"}, {"topic": "Acute Therapies", "front": "SLED", "back": "Sustained Low-Efficiency Dialysis: extended intermittent RRT (6-12 hrs) with lower flows than conventional HD"}, {"topic": "Acute Therapies", "front": "KDIGO CRRT Dose", "back": "Recommended delivered dose: 20-25 mL/kg/hr for critically ill AKI patients"}, {"topic": "Acute Therapies", "front": "Citrate Anticoagulation", "back": "Regional anticoagulation via calcium chelation in circuit; reduces bleeding risk vs systemic heparin"}, {"topic": "Acute Therapies", "front": "Citrate Toxicity Signs", "back": "Hypocalcemia, metabolic alkalosis, elevated total-to-ionized calcium ratio (>2.5); seen in liver failure"}, {"topic": "Acute Therapies", "front": "Preferred CRRT Access", "back": "Right internal jugular vein: straight path, lower infection risk, preserves subclavian for future fistula"}, {"topic": "Acute Therapies", "front": "Transmembrane Pressure (TMP)", "back": "Pressure gradient across filter membrane; rising TMP indicates filter clotting or fouling"}, {"topic": "Acute Therapies", "front": "Effluent Flow Rate", "back": "Total waste fluid rate (ultrafiltrate + dialysate + net removal); determines prescribed CRRT dose"}, {"topic": "Acute Therapies", "front": "CRRT Blood Flow Rate", "back": "Typical range: 100-200 mL/min, lower than conventional HD for hemodynamic stability"}, {"topic": "Acute Therapies", "front": "Hyperkalemia Management (CRRT)", "back": "CRRT indication in AKI; monitor for rapid shifts during initiation to prevent arrhythmias"}, {"topic": "Acute Therapies", "front": "CRRT-Associated Hypophosphatemia", "back": "Common during prolonged CRRT due to inadequate phosphate clearance; requires supplementation"}, {"topic": "Acute Therapies", "front": "Bicarbonate Buffer (CRRT)", "back": "Standard modern CRRT buffer; more physiologic than lactate, better hemodynamic stability"}, {"topic": "Acute Therapies", "front": "CRRT Downtime Impact", "back": "Circuit clotting, transport, procedures reduce delivered dose 15-30% below prescribed"}, {"topic": "Acute Therapies", "front": "Hyponatremia Correction Limit", "back": "Do not increase serum Na+ >10-12 mEq/L per 24 hours to avoid osmotic demyelination"}, {"topic": "Acute Therapies", "front": "Hypernatremia Correction Limit", "back": "Do not decrease serum Na+ >10-12 mEq/L per 24 hours to avoid cerebral edema"}, {"topic": "Acute Therapies", "front": "Sepsis-Induced AKI RRT Indication", "back": "Life-threatening complications: severe acidosis, hyperkalemia, refractory volume overload, uremia"}, {"topic": "CKD Complications", "front": "Erythropoietin (EPO) deficiency in CKD", "back": "Damaged kidneys produce less EPO, causing normocytic normochromic anemia. Treated with ESAs and iron supplementation."}, {"topic": "CKD Complications", "front": "CKD-MBD (Chronic Kidney Disease-Mineral and Bone Disorder)", "back": "Systemic disorder of mineral metabolism (calcium, phosphate, PTH, vitamin D) causing bone abnormalities and vascular calcification."}, {"topic": "CKD Complications", "front": "Secondary Hyperparathyroidism", "back": "Elevated PTH due to kidney's inability to activate vitamin D and excrete phosphate, causing low calcium that stimulates parathyroid glands."}, {"topic": "CKD Complications", "front": "Adynamic Bone Disease", "back": "Low bone turnover state with suppressed PTH (<150 pg/mL). Risk factors: overuse of vitamin D analogs, calcium-based binders, diabetes."}, {"topic": "CKD Complications", "front": "Metabolic Acidosis in CKD", "back": "Normal anion gap acidosis from decreased acid excretion and bicarbonate regeneration. Accelerates CKD progression and causes bone buffering."}, {"topic": "CKD Complications", "front": "Hyperkalemia threshold requiring intervention", "back": "Potassium >5.5 mEq/L requires dietary modification; >6.0 mEq/L is dangerous and may need emergency treatment (calcium, insulin/glucose, dialysis)."}, {"topic": "CKD Complications", "front": "Phosphate binder timing", "back": "Must be taken WITH meals to bind dietary phosphate in the gut. Taking between meals is ineffective."}, {"topic": "CKD Complications", "front": "Calcimimetics (e.g., cinacalcet)", "back": "Medications that increase calcium-sensing receptor sensitivity, lowering PTH, calcium, and phosphate. Used in secondary hyperparathyroidism."}, {"topic": "CKD Complications", "front": "Vitamin D activation pathway", "back": "Skin/supplements (D3/D2) \u2192 Liver (25-OH-D) \u2192 Kidney 1-alpha-hydroxylase (1,25-OH-D/calcitriol). Kidney step impaired in CKD."}, {"topic": "CKD Complications", "front": "Protein-energy wasting (PEW)", "back": "Loss of protein and energy reserves in CKD. Causes: uremic toxins, inflammation, acidosis, anorexia. Increases mortality risk."}, {"topic": "CKD Complications", "front": "Dyslipidemia pattern in CKD", "back": "High triglycerides, low HDL, normal or mildly elevated LDL. Caused by decreased lipoprotein lipase activity and impaired clearance."}, {"topic": "CKD Complications", "front": "Cardiovascular risk in CKD", "back": "CKD is an independent CVD risk factor. Mechanisms: hypertension, anemia, vascular calcification, inflammation, endothelial dysfunction."}, {"topic": "CKD Complications", "front": "Uremic pruritus", "back": "Generalized itching in advanced CKD/dialysis. Related to uremic toxins, xerosis, immune activation. Treat with emollients, gabapentin, optimized dialysis."}, {"topic": "CKD Complications", "front": "Target hemoglobin with ESA therapy", "back": "10-11 g/dL. Avoid >11.5 g/dL due to increased stroke, thrombosis, and mortality risk without QOL benefit."}, {"topic": "CKD Complications", "front": "Functional iron deficiency", "back": "Adequate iron stores (normal/high ferritin) but unavailable for erythropoiesis (low TSAT). Common in CKD due to inflammation/hepcidin."}, {"topic": "CKD Complications", "front": "Vascular calcification in CKD", "back": "Calcium-phosphate deposition in arterial media. Accelerated by hyperphosphatemia, high calcium load, vitamin D analogs. Increases CV mortality."}, {"topic": "CKD Complications", "front": "Diabetic nephropathy progression", "back": "Hyperglycemia \u2192 glomerular hyperfiltration \u2192 microalbuminuria \u2192 macroalbuminuria \u2192 declining GFR \u2192 ESRD. ACEi/ARB slow progression."}, {"topic": "CKD Complications", "front": "Sodium bicarbonate therapy indication", "back": "Serum bicarbonate <22 mEq/L. Goal: 22-26 mEq/L. Slows CKD progression, improves bone health, reduces protein catabolism."}, {"topic": "CKD Complications", "front": "FGF23 in CKD", "back": "Fibroblast growth factor 23 rises early to increase phosphate excretion. High levels predict LVH, cardiovascular events, and mortality."}, {"topic": "CKD Complications", "front": "Osteitis fibrosa cystica", "back": "High bone turnover disease from severe secondary hyperparathyroidism. Features: elevated PTH, bone pain, fractures, brown tumors."}, {"topic": "Pediatric Nephrology", "front": "Nephrotic Syndrome Diagnostic Criteria (Children)", "back": "Heavy proteinuria (UPCR >2.0 mg/mg or >40 mg/m2/hr), hypoalbuminemia (<2.5 g/dL), edema, and often hyperlipidemia"}, {"topic": "Pediatric Nephrology", "front": "Most Common Cause of Nephrotic Syndrome in Children", "back": "Minimal change disease (80-90% of cases in children ages 1-10 years)"}, {"topic": "Pediatric Nephrology", "front": "Classic HUS Triad", "back": "Microangiopathic hemolytic anemia, thrombocytopenia, and acute kidney injury"}, {"topic": "Pediatric Nephrology", "front": "Typical HUS Pathogen", "back": "Shiga toxin-producing Escherichia coli (STEC), most commonly O157:H7"}, {"topic": "Pediatric Nephrology", "front": "Posterior Urethral Valves (PUV)", "back": "Congenital obstructing membranes in the posterior urethra of males; most common cause of bladder outlet obstruction in male infants"}, {"topic": "Pediatric Nephrology", "front": "Preferred Dialysis Modality in Infants", "back": "Peritoneal dialysis - provides gentle continuous ultrafiltration, better growth outcomes, and easier home management"}, {"topic": "Pediatric Nephrology", "front": "CAKUT", "back": "Congenital Anomalies of the Kidney and Urinary Tract - most common birth defects affecting kidneys, including hydronephrosis, renal agenesis, and obstructive uropathies"}, {"topic": "Pediatric Nephrology", "front": "Vesicoureteral Reflux (VUR) Grading", "back": "Grade I-V: I (ureter only), II (ureter and pelvis without dilation), III (mild dilation), IV (moderate dilation with tortuosity), V (severe dilation with loss of papillary impressions)"}, {"topic": "Pediatric Nephrology", "front": "Steroid-Sensitive Nephrotic Syndrome", "back": "Achieves remission (proteinuria <4 mg/m2/hr or trace/negative dipstick) within 8 weeks of daily prednisone therapy"}, {"topic": "Pediatric Nephrology", "front": "Steroid-Resistant Nephrotic Syndrome", "back": "No remission after 8 weeks of daily prednisone; requires biopsy and consideration of alternative immunosuppression"}, {"topic": "Pediatric Nephrology", "front": "Growth Failure in Pediatric CKD", "back": "Multifactorial: inadequate nutrition, metabolic acidosis, CKD-mineral bone disorder, growth hormone resistance, and delayed puberty"}, {"topic": "Pediatric Nephrology", "front": "Maintenance Fluid Calculation (Holliday-Segar)", "back": "100 mL/kg (first 10 kg) + 50 mL/kg (next 10 kg) + 20 mL/kg (each kg over 20 kg)"}, {"topic": "Pediatric Nephrology", "front": "Acute Kidney Injury in Children (KDIGO Criteria)", "back": "Increase in serum creatinine \u22650.3 mg/dL within 48 hours, OR increase to \u22651.5 times baseline within 7 days, OR urine output <0.5 mL/kg/hr for 6 hours"}, {"topic": "Pediatric Nephrology", "front": "Hyperkalemia Emergency Treatment (Children)", "back": "Calcium gluconate (membrane stabilization), insulin with glucose (shifts K+ into cells), albuterol, sodium bicarbonate, and dialysis if severe"}, {"topic": "Pediatric Nephrology", "front": "Renal Tubular Acidosis Type 1 (Distal)", "back": "Defect in distal acid secretion; causes normal anion gap metabolic acidosis, hypokalemia, nephrocalcinosis, and kidney stones"}, {"topic": "Pediatric Nephrology", "front": "Renal Tubular Acidosis Type 2 (Proximal)", "back": "Defect in proximal bicarbonate reabsorption; causes normal anion gap metabolic acidosis, hypokalemia, often part of Fanconi syndrome"}, {"topic": "Pediatric Nephrology", "front": "Renal Tubular Acidosis Type 4", "back": "Aldosterone deficiency or resistance; causes hyperkalemic normal anion gap metabolic acidosis"}, {"topic": "Pediatric Nephrology", "front": "Anemia Management in Pediatric CKD", "back": "Target hemoglobin 11-12 g/dL; treat with erythropoiesis-stimulating agents and iron supplementation (ferritin >100 ng/mL, TSAT >20%)"}, {"topic": "Pediatric Nephrology", "front": "CKD-Mineral Bone Disorder in Children", "back": "Abnormalities in calcium, phosphorus, PTH, and vitamin D metabolism; requires phosphate binders, vitamin D analogs, and dietary management"}, {"topic": "Pediatric Nephrology", "front": "Indications for Dialysis in Children", "back": "Volume overload refractory to diuretics, severe electrolyte abnormalities, uremic symptoms, severe acidosis, or toxin removal"}, {"topic": "Pregnancy and Kidney Disease", "front": "Normal serum creatinine in pregnancy", "back": "0.4-0.8 mg/dL (lower than non-pregnant due to 40-50% increase in GFR)"}, {"topic": "Pregnancy and Kidney Disease", "front": "Definition of chronic hypertension in pregnancy", "back": "BP \u2265140/90 mmHg present before pregnancy or diagnosed before 20 weeks gestation"}, {"topic": "Pregnancy and Kidney Disease", "front": "Definition of gestational hypertension", "back": "New-onset BP \u2265140/90 mmHg after 20 weeks gestation without proteinuria or other preeclampsia features"}, {"topic": "Pregnancy and Kidney Disease", "front": "Diagnostic criteria for preeclampsia", "back": "BP \u2265140/90 after 20 weeks PLUS proteinuria (\u2265300 mg/24hr) OR severe features (thrombocytopenia, elevated creatinine, elevated LFTs, pulmonary edema, cerebral/visual symptoms)"}, {"topic": "Pregnancy and Kidney Disease", "front": "HELLP syndrome components", "back": "Hemolysis (schistocytes, elevated LDH), Elevated Liver enzymes (AST/ALT), Low Platelets (<100,000/mcL)"}, {"topic": "Pregnancy and Kidney Disease", "front": "First-line antihypertensives in pregnancy", "back": "Labetalol, nifedipine, methyldopa"}, {"topic": "Pregnancy and Kidney Disease", "front": "Antihypertensives contraindicated in pregnancy", "back": "ACE inhibitors, ARBs, direct renin inhibitors (cause fetal renal toxicity, oligohydramnios, skull hypoplasia)"}, {"topic": "Pregnancy and Kidney Disease", "front": "Target BP in pregnant patients with CKD", "back": "Below 140/90 mmHg (avoid aggressive lowering that may compromise placental perfusion)"}, {"topic": "Pregnancy and Kidney Disease", "front": "Risk of superimposed preeclampsia in CKD patients", "back": "25-50% depending on baseline kidney function and proteinuria level"}, {"topic": "Pregnancy and Kidney Disease", "front": "Most common cause of AKI in pregnancy", "back": "Preeclampsia/HELLP syndrome (50-60% of cases)"}, {"topic": "Pregnancy and Kidney Disease", "front": "Creatinine level concerning for AKI in pregnancy", "back": "\u22651.0 mg/dL or rise of \u22650.3 mg/dL from baseline (remember baseline is lower in pregnancy)"}, {"topic": "Pregnancy and Kidney Disease", "front": "Treatment of pyelonephritis in pregnancy", "back": "Hospital admission + IV antibiotics (ceftriaxone or cefepime) due to high risk of sepsis and preterm labor"}, {"topic": "Pregnancy and Kidney Disease", "front": "Safe antibiotics for UTI in pregnancy", "back": "Cephalexin, amoxicillin-clavulanate, nitrofurantoin (avoid in first trimester and near term), fosfomycin"}, {"topic": "Pregnancy and Kidney Disease", "front": "Antibiotics to avoid in pregnancy for UTI", "back": "Fluoroquinolones (cartilage damage), tetracyclines (tooth discoloration), TMP-SMX (first trimester and near term)"}, {"topic": "Pregnancy and Kidney Disease", "front": "Dialysis prescription in pregnancy", "back": "Intensive: daily or near-daily HD totaling 20+ hours/week to maintain BUN <50 mg/dL"}, {"topic": "Pregnancy and Kidney Disease", "front": "Target BUN in pregnant dialysis patients", "back": "Below 50 mg/dL (ideally <40 mg/dL) to reduce risk of polyhydramnios and improve fetal outcomes"}, {"topic": "Pregnancy and Kidney Disease", "front": "Preterm delivery rate in pregnant dialysis patients", "back": "50-80% (most deliver before 34 weeks)"}, {"topic": "Pregnancy and Kidney Disease", "front": "When is pregnancy safest in lupus nephritis?", "back": "When disease has been quiescent for at least 6 months with stable kidney function"}, {"topic": "Pregnancy and Kidney Disease", "front": "Low-dose aspirin in pregnant CKD patients", "back": "81 mg daily starting at 12 weeks to reduce preeclampsia risk (recommended by ACOG and KDIGO)"}, {"topic": "Pregnancy and Kidney Disease", "front": "Long-term risk after preeclampsia", "back": "Increased risk of chronic hypertension, CKD, and cardiovascular disease - requires lifelong monitoring"}, {"topic": "Drug Dosing in Renal Failure", "front": "Renal clearance", "back": "The volume of plasma from which a drug is completely removed by the kidneys per unit time; determines if dose adjustment is needed in CKD."}, {"topic": "Drug Dosing in Renal Failure", "front": "Dialyzable drug", "back": "A medication that can be removed by hemodialysis, typically water-soluble, low protein binding, and small molecular weight."}, {"topic": "Drug Dosing in Renal Failure", "front": "Nephrotoxic drug", "back": "A medication that can cause kidney damage, such as NSAIDs, aminoglycosides, amphotericin B, or contrast dye."}, {"topic": "Drug Dosing in Renal Failure", "front": "Loading dose", "back": "An initial higher dose to rapidly achieve therapeutic drug levels; usually unchanged in renal failure since it depends on volume of distribution."}, {"topic": "Drug Dosing in Renal Failure", "front": "Maintenance dose", "back": "The ongoing dose that maintains therapeutic drug levels; typically reduced in renal failure to prevent drug accumulation."}, {"topic": "Drug Dosing in Renal Failure", "front": "Therapeutic drug monitoring (TDM)", "back": "Measuring drug blood levels to guide dosing, essential for narrow therapeutic index drugs like vancomycin, gentamicin, and digoxin in CKD."}, {"topic": "Drug Dosing in Renal Failure", "front": "Contrast-induced nephropathy (CIN)", "back": "Acute kidney injury occurring 48-72 hours after iodinated contrast administration; prevented with IV hydration in at-risk CKD patients."}, {"topic": "Drug Dosing in Renal Failure", "front": "Lactic acidosis", "back": "A rare but serious complication of metformin accumulation in renal failure, with mortality up to 50% if severe."}, {"topic": "Drug Dosing in Renal Failure", "front": "Hyperkalemia", "back": "Elevated serum potassium; a risk with ACE inhibitors, ARBs, potassium-sparing diuretics, and trimethoprim in CKD patients."}, {"topic": "Drug Dosing in Renal Failure", "front": "Extended-interval dosing", "back": "Giving drugs less frequently but at similar doses in renal failure; commonly used for aminoglycosides and vancomycin."}, {"topic": "Drug Dosing in Renal Failure", "front": "Protein binding", "back": "The degree to which a drug binds to plasma proteins; highly protein-bound drugs (>90%) are generally not dialyzable."}, {"topic": "Drug Dosing in Renal Failure", "front": "Volume of distribution (Vd)", "back": "The theoretical volume in which a drug is distributed; drugs with large Vd are less dialyzable as they reside in tissues."}, {"topic": "Drug Dosing in Renal Failure", "front": "GFR threshold for metformin", "back": "Metformin should be discontinued when eGFR falls below 30 mL/min/1.73m\u00b2 due to lactic acidosis risk."}, {"topic": "Drug Dosing in Renal Failure", "front": "Vancomycin trough target", "back": "Typical target trough levels are 10-20 mcg/mL depending on infection severity; monitored closely in renal failure."}, {"topic": "Drug Dosing in Renal Failure", "front": "Aminoglycoside toxicity", "back": "Ototoxicity (hearing loss, vertigo) and nephrotoxicity (acute tubular necrosis); risk increased with accumulation in renal failure."}, {"topic": "Drug Dosing in Renal Failure", "front": "NSAID mechanism of nephrotoxicity", "back": "Inhibition of renal prostaglandins causes afferent arteriole vasoconstriction, reducing renal blood flow and GFR."}, {"topic": "Drug Dosing in Renal Failure", "front": "Post-dialysis dosing", "back": "Administering medications after hemodialysis to replace drug removed during the dialysis session."}, {"topic": "Drug Dosing in Renal Failure", "front": "Opioid metabolites in renal failure", "back": "Morphine and codeine produce active metabolites that accumulate in CKD, causing prolonged sedation and respiratory depression."}, {"topic": "Drug Dosing in Renal Failure", "front": "Allopurinol hypersensitivity", "back": "Severe rash and organ involvement risk increased in CKD; start low (50-100mg) and screen for HLA-B*5801 in high-risk populations."}, {"topic": "Drug Dosing in Renal Failure", "front": "Baclofen in CKD", "back": "Renally eliminated muscle relaxant that can cause severe CNS toxicity in CKD; avoid or use with extreme dose reduction."}, {"topic": "Acid-Base Disorders", "front": "Metabolic acidosis", "back": "Low pH (<7.35) and low bicarbonate (<22 mEq/L) due to acid accumulation or bicarbonate loss"}, {"topic": "Acid-Base Disorders", "front": "Respiratory acidosis", "back": "Low pH (<7.35) and high PaCO2 (>45 mmHg) due to inadequate alveolar ventilation"}, {"topic": "Acid-Base Disorders", "front": "Metabolic alkalosis", "back": "High pH (>7.45) and high bicarbonate (>26 mEq/L) due to acid loss or bicarbonate gain"}, {"topic": "Acid-Base Disorders", "front": "Respiratory alkalosis", "back": "High pH (>7.45) and low PaCO2 (<35 mmHg) due to excessive alveolar ventilation"}, {"topic": "Acid-Base Disorders", "front": "Anion gap", "back": "Calculated as Na+ - (Cl- + HCO3-); normal range 8-12 mEq/L; helps classify metabolic acidosis"}, {"topic": "Acid-Base Disorders", "front": "Winter's formula", "back": "Expected PaCO2 = 1.5 \u00d7 HCO3- + 8 (\u00b12); assesses respiratory compensation in metabolic acidosis"}, {"topic": "Acid-Base Disorders", "front": "Type 1 RTA (distal)", "back": "Defective H+ secretion in distal tubule; urine pH >5.5; associated with hypokalemia and nephrolithiasis"}, {"topic": "Acid-Base Disorders", "front": "Type 2 RTA (proximal)", "back": "Impaired bicarbonate reabsorption in proximal tubule; urine pH variable; associated with Fanconi syndrome"}, {"topic": "Acid-Base Disorders", "front": "Type 4 RTA", "back": "Aldosterone deficiency or resistance; hyperkalemia; impaired ammonium excretion; urine pH <5.5"}, {"topic": "Acid-Base Disorders", "front": "High anion gap metabolic acidosis causes", "back": "MUDPILES: Methanol, Uremia, DKA, Propylene glycol, Isoniazid/Iron, Lactic acidosis, Ethylene glycol, Salicylates"}, {"topic": "Acid-Base Disorders", "front": "Normal anion gap metabolic acidosis causes", "back": "HARDASS: Hyperalimentation, Acetazolamide, RTA, Diarrhea, Addison's disease, Saline infusion, Spironolactone"}, {"topic": "Acid-Base Disorders", "front": "Lactic acidosis", "back": "Accumulation of lactate due to tissue hypoxia (Type A) or metabolic causes (Type B); anion gap >12"}, {"topic": "Acid-Base Disorders", "front": "Diabetic ketoacidosis (DKA)", "back": "Hyperglycemia, ketonemia, metabolic acidosis; anion gap elevated; treated with fluids and insulin"}, {"topic": "Acid-Base Disorders", "front": "Compensation", "back": "Physiologic response to primary acid-base disorder; respiratory compensation is rapid, renal compensation takes days"}, {"topic": "Acid-Base Disorders", "front": "Acute respiratory acidosis compensation", "back": "Bicarbonate increases 1 mEq/L for every 10 mmHg PaCO2 increase above 40 mmHg"}, {"topic": "Acid-Base Disorders", "front": "Chronic respiratory acidosis compensation", "back": "Bicarbonate increases 3-4 mEq/L for every 10 mmHg PaCO2 increase above 40 mmHg"}, {"topic": "Acid-Base Disorders", "front": "Acute respiratory alkalosis compensation", "back": "Bicarbonate decreases 2 mEq/L for every 10 mmHg PaCO2 decrease below 40 mmHg"}, {"topic": "Acid-Base Disorders", "front": "Chronic respiratory alkalosis compensation", "back": "Bicarbonate decreases 4-5 mEq/L for every 10 mmHg PaCO2 decrease below 40 mmHg"}, {"topic": "Acid-Base Disorders", "front": "Bicarbonate therapy in CKD", "back": "Indicated when serum bicarbonate <22 mEq/L; target 22-26 mEq/L per KDIGO guidelines"}, {"topic": "Acid-Base Disorders", "front": "Saline-responsive metabolic alkalosis", "back": "Urine chloride <10 mEq/L; caused by vomiting, NG suction, or diuretics; treated with normal saline"}, {"topic": "Fluid and Electrolyte Emergencies", "front": "Hyperkalemia ECG progression", "back": "Peaked T waves \u2192 PR prolongation \u2192 QRS widening \u2192 Sine wave \u2192 Ventricular fibrillation/asystole"}, {"topic": "Fluid and Electrolyte Emergencies", "front": "Normal potassium range", "back": "3.5-5.0 mEq/L; levels above 6.5 mEq/L or with ECG changes constitute emergency"}, {"topic": "Fluid and Electrolyte Emergencies", "front": "Calcium gluconate in hyperkalemia", "back": "Stabilizes cardiac membranes within minutes; does not lower potassium; effect lasts 30-60 minutes"}, {"topic": "Fluid and Electrolyte Emergencies", "front": "Insulin-dextrose protocol", "back": "10 units regular insulin IV with 25g dextrose; lowers K+ by 0.5-1.5 mEq/L in 15-30 min; lasts 4-6 hours"}, {"topic": "Fluid and Electrolyte Emergencies", "front": "Osmotic demyelination syndrome", "back": "Neurologic injury from rapid hyponatremia correction; limit sodium increase to 8-10 mEq/L in 24 hours"}, {"topic": "Fluid and Electrolyte Emergencies", "front": "SIADH diagnostic criteria", "back": "Hyponatremia, low serum osmolality, inappropriately high urine osmolality (>100 mOsm/kg), euvolemia, normal thyroid/adrenal function"}, {"topic": "Fluid and Electrolyte Emergencies", "front": "Hypernatremia causes", "back": "Water loss (diabetes insipidus, osmotic diuresis), sodium gain (hypertonic saline), or inadequate water intake"}, {"topic": "Fluid and Electrolyte Emergencies", "front": "Hypocalcemia symptoms", "back": "Perioral paresthesias, muscle cramps, tetany, Chvostek sign, Trousseau sign, prolonged QT, seizures"}, {"topic": "Fluid and Electrolyte Emergencies", "front": "Hypercalcemia emergency treatment", "back": "IV isotonic saline for volume expansion, calcitonin for rapid effect, bisphosphonates for sustained reduction, dialysis if severe"}, {"topic": "Fluid and Electrolyte Emergencies", "front": "Normal calcium range", "back": "Total calcium 8.5-10.5 mg/dL; ionized calcium 4.5-5.6 mg/dL; correct total for albumin"}, {"topic": "Fluid and Electrolyte Emergencies", "front": "Hypermagnesemia causes", "back": "Renal failure with magnesium-containing antacids/laxatives, preeclampsia treatment with magnesium sulfate"}, {"topic": "Fluid and Electrolyte Emergencies", "front": "Hypermagnesemia symptoms", "back": "Loss of deep tendon reflexes (first sign), hypotension, bradycardia, respiratory depression, cardiac arrest"}, {"topic": "Fluid and Electrolyte Emergencies", "front": "Hypermagnesemia treatment", "back": "IV calcium gluconate to antagonize effects, IV fluids with loop diuretics, dialysis for severe cases or renal failure"}, {"topic": "Fluid and Electrolyte Emergencies", "front": "Hyperphosphatemia complications", "back": "Hypocalcemia, metastatic calcification, secondary hyperparathyroidism, increased cardiovascular mortality in CKD"}, {"topic": "Fluid and Electrolyte Emergencies", "front": "Phosphate binders", "back": "Calcium acetate, sevelamer, lanthanum; taken with meals to bind dietary phosphate in CKD patients"}, {"topic": "Fluid and Electrolyte Emergencies", "front": "Fluid overload assessment", "back": "Weight gain, edema, jugular venous distension, crackles, dyspnea, orthopnea, S3 heart sound, elevated BNP"}, {"topic": "Fluid and Electrolyte Emergencies", "front": "Pulmonary edema emergency management", "back": "Sit upright, high-flow oxygen, IV loop diuretics, nitrates for preload reduction, noninvasive ventilation if needed"}, {"topic": "Fluid and Electrolyte Emergencies", "front": "Hypomagnesemia ECG changes", "back": "Prolonged QT, prolonged PR, ST depression, T wave flattening, predisposition to torsades de pointes"}, {"topic": "Fluid and Electrolyte Emergencies", "front": "Diabetes insipidus types", "back": "Central (ADH deficiency), nephrogenic (renal resistance to ADH), gestational, dipsogenic; all cause polyuria and hypernatremia risk"}, {"topic": "Fluid and Electrolyte Emergencies", "front": "Hyperkalemia risk medications", "back": "ACE inhibitors, ARBs, potassium-sparing diuretics, NSAIDs, beta-blockers, digoxin toxicity, succinylcholine"}, {"topic": "Transplant Pharmacology", "front": "Calcineurin Inhibitors (CNIs)", "back": "Immunosuppressants (tacrolimus, cyclosporine) that block calcineurin, preventing IL-2 production and T-cell activation; require therapeutic drug monitoring due to nephrotoxicity risk."}, {"topic": "Transplant Pharmacology", "front": "Tacrolimus (FK506)", "back": "Potent calcineurin inhibitor binding FKBP-12; narrow therapeutic index; side effects include nephrotoxicity, neurotoxicity, hyperglycemia, and new-onset diabetes after transplant."}, {"topic": "Transplant Pharmacology", "front": "Cyclosporine", "back": "Calcineurin inhibitor that binds cyclophilin; distinctive side effects include gingival hyperplasia, hirsutism, and hypertension; more nephrotoxic than tacrolimus."}, {"topic": "Transplant Pharmacology", "front": "Mycophenolate Mofetil (MMF)", "back": "Antimetabolite inhibiting inosine monophosphate dehydrogenase; blocks purine synthesis in lymphocytes; common side effects include GI upset, leukopenia, and increased infection risk."}, {"topic": "Transplant Pharmacology", "front": "Azathioprine", "back": "Prodrug converted to 6-mercaptopurine; inhibits DNA synthesis in proliferating cells; causes bone marrow suppression; largely replaced by MMF but still used in some protocols."}, {"topic": "Transplant Pharmacology", "front": "Sirolimus (Rapamycin)", "back": "mTOR inhibitor blocking cell cycle progression; side effects include hyperlipidemia, thrombocytopenia, impaired wound healing, and proteinuria; not nephrotoxic."}, {"topic": "Transplant Pharmacology", "front": "Basiliximab", "back": "Chimeric monoclonal antibody against IL-2 receptor alpha chain (CD25); used for induction therapy; prevents T-cell activation without causing cytokine release syndrome."}, {"topic": "Transplant Pharmacology", "front": "Antithymocyte Globulin (ATG)", "back": "Polyclonal antibody causing T-cell depletion via complement-mediated lysis; used for induction in high-risk patients or treatment of acute rejection; requires premedication."}, {"topic": "Transplant Pharmacology", "front": "Prednisone", "back": "Corticosteroid with broad anti-inflammatory and immunosuppressive effects; long-term use causes osteoporosis, weight gain, hyperglycemia, hypertension, and adrenal suppression."}, {"topic": "Transplant Pharmacology", "front": "Therapeutic Drug Monitoring (TDM)", "back": "Regular measurement of blood drug levels (tacrolimus, cyclosporine, sirolimus) to maintain therapeutic range while minimizing toxicity; trough levels typically drawn 12 hours post-dose."}, {"topic": "Transplant Pharmacology", "front": "CYP3A4 Inhibitors", "back": "Drugs that increase calcineurin inhibitor levels (e.g., fluconazole, clarithromycin, diltiazem, grapefruit); require dose reduction and close monitoring."}, {"topic": "Transplant Pharmacology", "front": "CYP3A4 Inducers", "back": "Drugs that decrease calcineurin inhibitor levels (e.g., rifampin, phenytoin, carbamazepine, St. John's wort); may cause subtherapeutic levels and rejection risk."}, {"topic": "Transplant Pharmacology", "front": "Nephrotoxicity (CNI-induced)", "back": "Dose-dependent kidney injury from calcineurin inhibitors via afferent arteriole vasoconstriction; manifests as elevated creatinine; managed by dose reduction or conversion to alternative agents."}, {"topic": "Transplant Pharmacology", "front": "New-Onset Diabetes After Transplant (NODAT)", "back": "Post-transplant hyperglycemia often caused by tacrolimus or steroids; occurs in 10-20% of recipients; requires glucose monitoring and possible medication adjustment."}, {"topic": "Transplant Pharmacology", "front": "Induction Therapy", "back": "Intense immunosuppression given at transplant to prevent early acute rejection; agents include basiliximab (IL-2 antagonist) or ATG (T-cell depleting antibody)."}, {"topic": "Transplant Pharmacology", "front": "Maintenance Immunosuppression", "back": "Long-term medication regimen to prevent rejection; typically includes a calcineurin inhibitor, antimetabolite (MMF or azathioprine), and often low-dose steroids."}, {"topic": "Transplant Pharmacology", "front": "Gingival Hyperplasia", "back": "Overgrowth of gum tissue occurring in up to 30% of cyclosporine patients; rare with tacrolimus; managed with dental care or medication switch."}, {"topic": "Transplant Pharmacology", "front": "Hyperlipidemia (Transplant-related)", "back": "Elevated cholesterol and triglycerides common with sirolimus and steroids; requires lipid monitoring and may need statin therapy."}, {"topic": "Transplant Pharmacology", "front": "Bone Marrow Suppression", "back": "Reduced blood cell production caused by MMF and azathioprine; manifests as leukopenia, anemia, or thrombocytopenia; requires CBC monitoring and possible dose adjustment."}, {"topic": "Transplant Pharmacology", "front": "Live Vaccines Contraindication", "back": "Live attenuated vaccines (MMR, varicella, nasal influenza) are contraindicated in transplant patients on immunosuppression due to risk of vaccine-derived infection."}];
const ORIG_LESSONS = [{"topic": "Kidney Disease", "title": "Understanding Acute Kidney Injury: Types and Causes", "body": "Acute Kidney Injury (AKI) is classified into three categories based on the location of the problem. Prerenal AKI occurs when blood flow to the kidneys is reduced before reaching the renal tissue. Common causes include hypotension, heart failure, sepsis, dehydration, and hemorrhage. The kidney tissue itself is initially healthy but cannot filter properly without adequate perfusion. Intrarenal (intrinsic) AKI involves direct damage to the kidney tissue itself. The most common form is acute tubular necrosis (ATN), caused by prolonged ischemia or nephrotoxic substances like contrast dye, aminoglycoside antibiotics, or NSAIDs. Other intrarenal causes include glomerulonephritis, interstitial nephritis, and vascular diseases. Postrenal AKI results from obstruction of urine flow after it leaves the kidneys. Causes include kidney stones, bladder tumors, prostate enlargement, ureteral strictures, or blood clots. Early recognition of the type is critical because treatment differs: prerenal requires volume resuscitation and improving perfusion, intrarenal needs removal of offending agents and supportive care, and postrenal requires relieving the obstruction. Nurses should monitor urine output, serum creatinine trends, and urine sediment findings to help identify the type and guide interventions."}, {"topic": "Kidney Disease", "title": "Chronic Kidney Disease: Staging and Management", "body": "Chronic Kidney Disease (CKD) is classified into five stages based on glomerular filtration rate (GFR). Stage 1 (GFR \u226590) has normal or high GFR with kidney damage markers like proteinuria. Stage 2 (GFR 60-89) shows mild reduction. Stage 3 (GFR 30-59) is moderate reduction, often when symptoms begin appearing. Stage 4 (GFR 15-29) is severe reduction requiring preparation for renal replacement therapy. Stage 5 (GFR <15) is kidney failure requiring dialysis or transplantation. Key management principles include blood pressure control (target <130/80 mmHg), preferably with ACE inhibitors or ARBs which also reduce proteinuria. Glycemic control is essential for diabetic patients. Dietary modifications include sodium restriction (<2g/day), protein moderation (0.6-0.8g/kg/day in stages 3-5), potassium restriction if hyperkalemic, and phosphate restriction with binders if hyperphosphatemic. Anemia management involves erythropoiesis-stimulating agents and iron supplementation. Bone-mineral disorder is managed with vitamin D analogs, phosphate binders, and calcimimetics. Regular monitoring includes GFR, electrolytes, hemoglobin, calcium, phosphorus, PTH, and urine albumin-to-creatinine ratio. Patient education focuses on medication adherence, dietary compliance, recognizing complications, and understanding treatment options including dialysis modalities and transplantation."}, {"topic": "Kidney Disease", "title": "Glomerular Diseases: Nephrotic vs Nephritic Syndromes", "body": "Glomerular diseases present as either nephrotic or nephritic syndromes, distinguished by their clinical features and underlying pathology. Nephrotic syndrome results from increased glomerular permeability to proteins. Classic findings include heavy proteinuria (>3.5g/day), hypoalbuminemia (<3.0g/dL), generalized edema (often periorbital and dependent), hyperlipidemia, and lipiduria. Common causes include minimal change disease (common in children), focal segmental glomerulosclerosis, membranous nephropathy, and diabetic nephropathy. Complications include increased infection risk (loss of immunoglobulins), thromboembolism (loss of antithrombin III), and accelerated atherosclerosis. Treatment involves corticosteroids or immunosuppressants for primary causes, ACE inhibitors/ARBs to reduce proteinuria, diuretics for edema, statins for hyperlipidemia, and anticoagulation if albumin is very low. Nephritic syndrome involves glomerular inflammation with capillary wall damage. Hallmark findings include hematuria with dysmorphic RBCs and RBC casts, hypertension, oliguria, mild-to-moderate proteinuria (<3.5g/day), and azotemia. Causes include IgA nephropathy (most common worldwide), post-streptococcal glomerulonephritis, lupus nephritis, and rapidly progressive glomerulonephritis. Management focuses on treating the underlying cause, blood pressure control, sodium and fluid restriction for edema, and immunosuppression for autoimmune causes. Urinalysis showing RBC casts is pathognomonic for glomerulonephritis and distinguishes nephritic from nephrotic presentation. Both syndromes require nephrology consultation and often kidney biopsy for definitive diagnosis."}, {"topic": "Hemodialysis", "title": "Principles of Hemodialysis: Diffusion, Convection, and Ultrafiltration", "body": "Hemodialysis relies on three key principles to remove waste and excess fluid from the blood. DIFFUSION is the primary mechanism, where solutes move from areas of high concentration (blood) to low concentration (dialysate) across a semipermeable membrane. Small molecules like urea, creatinine, and potassium are efficiently cleared this way. CONVECTION occurs when solutes are dragged along with water as it moves across the membrane due to pressure gradients, particularly important for clearing middle-sized molecules. ULTRAFILTRATION is the controlled removal of excess fluid by applying hydrostatic pressure, forcing plasma water through the membrane pores. The dialyzer membrane's characteristics determine what can pass through: pore size controls the molecular weight cutoff, typically allowing molecules under 50,000 Daltons while retaining albumin and blood cells. High-flux membranes have larger pores for better middle molecule clearance. Blood and dialysate flow in opposite directions (counter-current) to maximize the concentration gradient throughout the dialyzer length."}, {"topic": "Hemodialysis", "title": "Vascular Access for Hemodialysis: Types, Care, and Complications", "body": "Vascular access is the lifeline for hemodialysis patients. There are three main types: ARTERIOVENOUS FISTULA (AVF), ARTERIOVENOUS GRAFT (AVG), and CENTRAL VENOUS CATHETER. AVF is created by surgically connecting an artery to a vein, usually in the arm. It requires 3-6 months to mature but offers the best long-term patency and lowest infection risk, making it the gold standard. A functioning AVF has a palpable thrill and audible bruit. AVG uses a synthetic tube to connect artery and vein, maturing in 2-4 weeks but with higher thrombosis and infection rates. Catheters (tunneled or non-tunneled) provide immediate access but carry the highest infection and thrombosis risk, reserved for temporary use. COMPLICATIONS include: thrombosis (loss of thrill/bruit), stenosis (reduced flow, prolonged bleeding after needle removal), infection (redness, warmth, fever), aneurysm formation (repeated cannulation sites), and steal syndrome (hand ischemia from diverted blood flow). Proper care includes daily inspection, avoiding blood pressure measurements or IVs in the access arm, and immediate reporting of any changes in thrill or bruit."}, {"topic": "Hemodialysis", "title": "Intradialytic Complications: Recognition and Management", "body": "Several complications can occur during hemodialysis treatments. INTRADIALYTIC HYPOTENSION is the most common, affecting 20-30% of treatments. Causes include rapid ultrafiltration, autonomic dysfunction, and cardiac issues. Management includes stopping ultrafiltration, placing patient in Trendelenburg position, administering saline bolus, and using cool dialysate for prevention. MUSCLE CRAMPS occur in 5-20% of treatments, typically from rapid volume depletion. Treatment includes stretching, hypertonic saline, or reducing ultrafiltration rate. DIALYSIS DISEQUILIBRIUM SYNDROME results from rapid solute removal causing cerebral edema, presenting with headache, nausea, confusion, and potentially seizures. Prevention involves slower, more frequent treatments for new patients. AIR EMBOLISM is rare but life-threatening, occurring when air enters the venous line. Symptoms include sudden chest pain, dyspnea, cough, and cardiovascular collapse. Immediate management: clamp venous line, place patient in left lateral decubitus with head down (Durant's maneuver), administer 100% oxygen, and call for emergency support. Other complications include hemolysis (from overheated dialysate or chloramine exposure), allergic reactions to dialyzer membrane, and bleeding from excessive anticoagulation."}, {"topic": "Peritoneal Dialysis", "title": "PD Catheter Types and Placement", "body": "Peritoneal dialysis requires secure vascular access via a PD catheter. The Tenckhoff catheter is the most widely used design, featuring a silicone tube with one or two cuffs made of Dacron or polyester. The cuffs promote tissue ingrowth, anchoring the catheter and creating a barrier against bacterial migration. Catheters can be placed surgically (open or laparoscopic), percutaneously, or with fluoroscopic guidance. Laparoscopic placement allows direct visualization, omentopexy if needed, and concurrent hernia repair. Catheter types include standard Tenckhoff (coiled or straight tip), presternal catheters (exit site on chest wall for patients with abdominal ostomies or severe obesity), and moncrief-popovich catheters (external segment buried until use). Proper catheter positioning places the tip in the pelvis (pouch of Douglas) to ensure complete drainage. Break-in period of 2-4 weeks with low-volume exchanges allows healing and reduces pericatheter leak risk. Exit-site should be oriented downward or laterally to minimize trauma and contamination risk."}, {"topic": "Peritoneal Dialysis", "title": "Peritoneal Membrane Transport and the PET", "body": "The Peritoneal Equilibration Test (PET) characterizes individual membrane transport properties to optimize PD prescriptions. During PET, a standard 2.5% dextrose exchange is performed with dialysate and blood samples collected at specified intervals. The dialysate-to-plasma (D/P) creatinine ratio at 4 hours determines transporter status: high (>0.81), high-average (0.65-0.81), low-average (0.49-0.64), or low (<0.49). High transporters rapidly equilibrate solutes but quickly lose the osmotic gradient, resulting in poor ultrafiltration on long dwells. They benefit from shorter dwell times, automated PD (APD), or icodextrin for long dwells. Low transporters have slower solute clearance but maintain UF longer; they need extended dwell times and may require higher glucose concentrations. Understanding transporter status guides modality selection (CAPD vs. APD), dwell times, and dialysate composition. Repeat PET annually or when clinical changes occur (UF failure, inadequate clearance)."}, {"topic": "Peritoneal Dialysis", "title": "Peritonitis Recognition and Management", "body": "Peritonitis is the most serious common complication of PD, requiring prompt recognition and treatment. Diagnostic criteria include at least two of: cloudy effluent, abdominal pain, and/or effluent WBC >100/\u03bcL with >50% neutrophils. Gram stain and culture should be obtained before antibiotics. Empiric therapy must cover both Gram-positive organisms (vancomycin 15-30 mg/kg IP or cephalosporin) and Gram-negative organisms (ceftazidime 1g IP or aminoglycoside). Intraperitoneal administration achieves superior peritoneal tissue levels compared to IV. Treatment continues for 2-3 weeks depending on organism. Catheter removal is indicated for refractory peritonitis (no improvement after 5 days), fungal peritonitis, relapsing peritonitis, or severe exit-site/tunnel infection. Prevention focuses on proper exchange technique, exit-site care with topical mupirocin or gentamicin, and patient education. Recurrent peritonitis may indicate biofilm formation, requiring catheter removal. Early recognition and appropriate antibiotic selection preserve membrane function and prevent complications like encapsulating peritoneal sclerosis."}, {"topic": "Transplant", "title": "Types of Kidney Transplant Rejection", "body": "Kidney transplant rejection is classified by timing and mechanism. Hyperacute rejection occurs within minutes to hours due to pre-existing antibodies against donor HLA antigens, causing immediate thrombosis and graft loss. This is now rare due to mandatory crossmatch testing. Acute rejection typically occurs within the first 3-6 months and has two forms: acute cellular rejection (T-cell mediated, showing tubulitis on biopsy) and acute antibody-mediated rejection (donor-specific antibodies causing complement activation). Both are treatable with intensified immunosuppression if caught early. Chronic rejection develops over months to years and is characterized by progressive interstitial fibrosis, tubular atrophy, and transplant glomerulopathy. Chronic antibody-mediated rejection shows glomerular basement membrane double contours and C4d deposition. Unlike acute rejection, chronic changes are largely irreversible and represent the leading cause of late graft loss. Prevention through consistent immunosuppression adherence and regular monitoring is critical."}, {"topic": "Transplant", "title": "Immunosuppressive Medication Management", "body": "Kidney transplant recipients require lifelong immunosuppression to prevent rejection. Standard maintenance therapy uses triple drug regimens: a calcineurin inhibitor (tacrolimus preferred over cyclosporine), an antimetabolite (mycophenolate mofetil or mycophenolic acid), and corticosteroids. Tacrolimus requires therapeutic drug monitoring with trough levels typically targeted at 8-12 ng/mL in early post-transplant period and 5-8 ng/mL long-term, though targets vary by center and patient risk. Mycophenolate inhibits lymphocyte proliferation through IMPDH inhibition and does not require routine level monitoring. Corticosteroids are often tapered to low doses or discontinued in select patients but provide important anti-inflammatory effects. Induction therapy with basiliximab (IL-2 receptor antagonist) or antithymocyte globulin (T-cell depleting antibody) is given at transplant to provide intense early immunosuppression while allowing delayed introduction of nephrotoxic calcineurin inhibitors. Key nursing considerations include medication timing consistency, recognition of toxicity signs (tremor, hyperglycemia, nephrotoxicity), drug interaction awareness (CYP3A4 inhibitors/inducers affect tacrolimus levels), and patient education on adherence importance."}, {"topic": "Transplant", "title": "Infectious Complications Post-Transplant", "body": "Infection is a leading cause of morbidity and mortality post-kidney transplant, with risk varying by time since transplant. In the first month, bacterial infections predominate (wound infections, UTI, pneumonia, line infections). Between 1-6 months, opportunistic infections emerge due to peak immunosuppression: CMV (especially D+/R- recipients), BK virus nephropathy, Pneumocystis jirovecii pneumonia, and fungal infections. After 6 months, community-acquired infections become more common, though late opportunistic infections occur with intensified immunosuppression for rejection. CMV prophylaxis with valganciclovir is standard for 3-6 months in high-risk patients. PJP prophylaxis with trimethoprim-sulfamethoxazole is given for 6-12 months. BK virus screening via plasma viral load or urine decoy cells is performed monthly for 3-6 months, then quarterly through year one. Elevated BK viral load prompts immunosuppression reduction as the primary treatment. All transplant recipients should receive appropriate vaccinations pre-transplant when possible (avoiding live vaccines post-transplant) and practice infection prevention measures including hand hygiene, avoiding sick contacts, and food safety precautions."}, {"topic": "Acute Therapies", "title": "CRRT Modalities and Solute Removal Mechanisms", "body": "Continuous Renal Replacement Therapy (CRRT) encompasses several modalities that differ primarily in their solute removal mechanisms. Understanding these mechanisms is essential for selecting the appropriate therapy and optimizing prescriptions.\n\nCONVECTION: This mechanism uses hydrostatic pressure to push fluid across a semipermeable membrane, dragging dissolved solutes along through 'solvent drag.' Convection is particularly effective for middle-molecule clearance. In CVVH (Continuous Veno-Venous Hemofiltration), convection is the primary clearance mechanism, requiring replacement fluid to maintain volume balance.\n\nDIFFUSION: Solutes move down their concentration gradient from blood to dialysate (or vice versa) across the membrane. Diffusion is most efficient for small molecules like urea and creatinine. CVVHD (Continuous Veno-Venous Hemodialysis) relies primarily on diffusion, using dialysate flow to create concentration gradients.\n\nCVVHDF (Continuous Veno-Venous Hemodiafiltration) combines both mechanisms, using both replacement fluid and dialysate to maximize clearance across all molecular weight ranges. This modality offers flexibility but requires managing both fluid streams.\n\nSLED (Sustained Low-Efficiency Dialysis) represents an intermediate approach\u2014extended intermittent therapy typically run 6-12 hours with lower blood and dialysate flows than conventional hemodialysis. SLED provides better hemodynamic stability than standard HD while requiring less continuous monitoring than CRRT.\n\nSelection depends on patient hemodynamics, available resources, and specific clearance needs. All modalities require careful attention to anticoagulation, vascular access, and dose delivery."}, {"topic": "Acute Therapies", "title": "Anticoagulation Strategies in CRRT", "body": "Preventing circuit clotting while minimizing bleeding risk is a central challenge in CRRT management. Two primary anticoagulation strategies are used: systemic heparin and regional citrate anticoagulation.\n\nSYSTEMIC HEPARIN: Unfractionated heparin is administered continuously or intermittently to maintain circuit patency. Monitoring typically uses aPTT or anti-Xa levels. Advantages include familiarity, low cost, and easy reversal with protamine. Disadvantages include bleeding risk, heparin-induced thrombocytopenia (HIT), and variable response in critically ill patients.\n\nREGIONAL CITRATE ANTICOAGULATION: Citrate is infused pre-filter, chelating ionized calcium within the circuit to prevent clotting. Calcium is then replaced post-filter or systemically to maintain normal patient calcium levels. Citrate is metabolized by the liver to bicarbonate.\n\nAdvantages of citrate include: significantly reduced bleeding risk (anticoagulation is circuit-confined), longer circuit life, and no HIT risk. Disadvantages include: complexity of monitoring, risk of citrate accumulation (especially in liver failure or shock), metabolic alkalosis from citrate metabolism, and need for calcium monitoring.\n\nMonitoring citrate anticoagulation requires checking: circuit ionized calcium (target 0.25-0.4 mmol/L), systemic ionized calcium (target 1.0-1.2 mmol/L), total calcium, acid-base status, and the total-to-ionized calcium ratio (elevation >2.5 suggests accumulation).\n\nContraindications to citrate include severe liver failure, severe shock with impaired perfusion, and certain metabolic conditions. In these cases, heparin or saline flushes may be preferred.\n\nKDIGO guidelines suggest citrate as the preferred anticoagulation method when not contraindicated, based on evidence for longer circuit life and reduced bleeding."}, {"topic": "Acute Therapies", "title": "CRRT Dosing, Access, and Clinical Considerations", "body": "Proper CRRT prescription and management requires attention to dose delivery, vascular access, and ongoing monitoring for complications.\n\nDOSE PRESCRIPTION: KDIGO guidelines recommend a delivered dose of 20-25 mL/kg/hr for critically ill patients with AKI. The dose is calculated based on effluent flow rate (total waste fluid). Importantly, prescribed dose often exceeds delivered dose by 15-30% due to treatment downtime from circuit changes, transport, procedures, and alarms. To achieve target delivered dose, consider prescribing 25-30 mL/kg/hr.\n\nVASCULAR ACCESS: The right internal jugular vein is the preferred site for CRRT catheters. It provides direct access to the superior vena cava/right atrium junction, has lower infection rates than femoral access, and avoids subclavian vein stenosis that could compromise future arteriovenous fistula creation. Femoral access is acceptable when other sites are unavailable but carries higher infection risk. Catheters should be dual-lumen, non-cuffed, designed for high flow rates (typically 11-13 French for adults).\n\nELECTROLYTE MANAGEMENT: CRRT significantly affects electrolyte balance. Potassium is effectively cleared, but rapid shifts during initiation can precipitate arrhythmias. Phosphate clearance is often inadequate, leading to hypophosphatemia during prolonged therapy\u2014monitor and supplement as needed. Sodium correction must be gradual (no more than 10-12 mEq/L per 24 hours) to avoid neurologic complications. Bicarbonate-buffered solutions are standard, but acid-base status requires monitoring and dialysate/replacement fluid adjustments.\n\nSEPSIS-INDUCED AKI: In septic patients, CRRT initiation is based on life-threatening complications rather than arbitrary BUN/creatinine thresholds. Indications include: severe metabolic acidosis refractory to medical management, hyperkalemia with ECG changes, volume overload causing respiratory compromise, and uremic complications (pericarditis, encephalopathy, bleeding). Early initiation before severe complications develop may be considered in rapidly deteriorating patients.\n\nCIRCUIT MONITORING: Watch for rising transmembrane pressure (indicates clotting), decreasing venous pressure (access problems), and visual evidence of clotting in the circuit. Prompt intervention preserves circuit life and maintains dose delivery."}, {"topic": "CKD Complications", "title": "Anemia Management in Chronic Kidney Disease", "body": "Anemia is one of the most common complications of CKD, affecting over 90% of patients with stage 5 disease. The primary mechanism is erythropoietin (EPO) deficiency, as damaged kidneys cannot produce adequate amounts of this hormone that stimulates red blood cell production in bone marrow.\n\nKey Assessment Points:\n- Monitor hemoglobin regularly (target: 10-11 g/dL with ESA therapy)\n- Check iron studies: ferritin, transferrin saturation (TSAT)\n- Assess for symptoms: fatigue, weakness, shortness of breath, pallor\n- Rule out other causes: blood loss, B12/folate deficiency, hemolysis\n\nTreatment Approach:\n1. Iron supplementation: Maintain ferritin >100 ng/mL (non-dialysis) or >200 ng/mL (dialysis), TSAT >20%\n2. Erythropoiesis-stimulating agents (ESAs): epoetin alfa, darbepoetin alfa\n3. Avoid hemoglobin >11.5 g/dL due to increased cardiovascular risk\n4. Consider IV iron for dialysis patients or those with poor oral absorption\n\nNursing Considerations:\n- Educate patients about iron-rich foods and ESA administration\n- Monitor blood pressure (ESAs can worsen hypertension)\n- Watch for signs of iron overload or allergic reactions to IV iron\n- Assess vascular access sites in dialysis patients receiving IV medications"}, {"topic": "CKD Complications", "title": "CKD-Mineral and Bone Disorder (CKD-MBD): Comprehensive Management", "body": "CKD-MBD is a systemic disorder affecting mineral metabolism, bone health, and cardiovascular function. It encompasses abnormalities in calcium, phosphorus, PTH, and vitamin D metabolism that develop as kidney function declines.\n\nPathophysiology:\nAs GFR decreases, phosphate retention occurs, stimulating FGF23 release. The kidney's ability to activate vitamin D diminishes, reducing calcium absorption. Low calcium and high phosphate trigger secondary hyperparathyroidism. Over time, this leads to bone disease and vascular calcification.\n\nLaboratory Monitoring:\n- Calcium (corrected for albumin): target 8.4-9.5 mg/dL\n- Phosphate: target 2.5-4.5 mg/dL (stage 3-5), 3.5-5.5 mg/dL (dialysis)\n- Intact PTH: target 35-70 pg/mL (stage 3), 70-120 pg/mL (stage 4), 150-300 pg/mL (stage 5/dialysis)\n- Alkaline phosphatase: marker of bone turnover\n- 25-hydroxyvitamin D: maintain >30 ng/mL\n\nTreatment Strategies:\n1. Phosphate control: dietary restriction (800-1000 mg/day), phosphate binders (calcium-based, sevelamer, lanthanum)\n2. Vitamin D supplementation: cholecalciferol for deficiency, calcitriol/analogs for secondary HPT\n3. Calcimimetics: cinacalcet for refractory secondary HPT\n4. Parathyroidectomy: for severe, medication-resistant disease\n\nNursing Priorities:\n- Teach proper timing of phosphate binders (with meals)\n- Monitor for hypercalcemia symptoms (nausea, confusion, polyuria)\n- Assess for bone pain, fractures, height loss\n- Emphasize medication adherence to prevent long-term complications"}, {"topic": "CKD Complications", "title": "Cardiovascular Complications and Risk Reduction in CKD", "body": "Cardiovascular disease is the leading cause of death in CKD patients, accounting for approximately 50% of mortality. CKD patients are more likely to die from cardiovascular events than progress to ESRD.\n\nUnique Cardiovascular Risks in CKD:\n- Accelerated atherosclerosis from chronic inflammation and endothelial dysfunction\n- Left ventricular hypertrophy from hypertension and anemia\n- Vascular calcification from CKD-MBD\n- Arrhythmias from electrolyte imbalances (especially hyperkalemia)\n- Uremic cardiomyopathy in advanced disease\n- Increased arterial stiffness\n\nRisk Factor Management:\n1. Blood pressure: Target <130/80 mmHg; ACE inhibitors or ARBs preferred for proteinuria\n2. Lipid management: Statins recommended for most CKD patients (except dialysis)\n3. Glycemic control: HbA1c target ~7% for diabetic patients\n4. Anemia management: Maintain hemoglobin 10-11 g/dL\n5. Mineral metabolism: Control phosphate, calcium, PTH to reduce calcification\n6. Lifestyle: Smoking cessation, weight management, physical activity as tolerated\n\nScreening Recommendations:\n- Regular blood pressure monitoring\n- Lipid panel annually (or more frequently if abnormal)\n- ECG for patients with symptoms or high risk\n- Echocardiogram if heart failure symptoms present\n- Assess for peripheral arterial disease\n\nPatient Education:\n- Recognize cardiac symptoms: chest pain, shortness of breath, palpitations, edema\n- Medication adherence for BP, lipids, diabetes\n- Dietary modifications: low sodium, heart-healthy fats, appropriate potassium/phosphate\n- Importance of regular follow-up and laboratory monitoring\n- When to seek emergency care for cardiac symptoms"}, {"topic": "Pediatric Nephrology", "title": "Nephrotic Syndrome in Children: Assessment and Management", "body": "Nephrotic syndrome is one of the most common glomerular disorders in pediatric nephrology. The hallmark is heavy proteinuria leading to hypoalbuminemia, edema, and hyperlipidemia. In children ages 1-10 years, minimal change disease accounts for 80-90% of cases and typically responds well to corticosteroid therapy. Nursing assessment should focus on daily weights, edema monitoring (periorbital, sacral, extremities), blood pressure checks, and urine protein monitoring via dipstick. Key nursing interventions include sodium restriction (1-2 mEq/kg/day), fluid management based on urine output and edema severity, skin care to prevent breakdown from edema, and infection prevention due to immunosuppression from both the disease and steroid treatment. Families should be taught to monitor urine protein at home using dipsticks and recognize signs of relapse (foamy urine, returning edema, weight gain). Complications to monitor include infection (especially peritonitis and cellulitis), thromboembolism (due to urinary loss of antithrombin III), and acute kidney injury from severe hypovolemia. Steroid therapy typically starts at 60 mg/m2/day or 2 mg/kg/day for 6 weeks, followed by alternate-day dosing. Children who relapse frequently or become steroid-dependent may require steroid-sparing agents such as cyclosporine, tacrolimus, mycophenolate mofetil, or rituximab. Regular monitoring of growth, blood pressure, kidney function, and medication side effects is essential for long-term management."}, {"topic": "Pediatric Nephrology", "title": "Hemolytic Uremic Syndrome: Recognition and Supportive Care", "body": "Hemolytic uremic syndrome (HUS) is the most common cause of acute kidney injury in children. Typical HUS follows a prodrome of bloody diarrhea caused by Shiga toxin-producing E. coli (STEC), most commonly serotype O157:H7. The toxin damages endothelial cells, particularly in the kidney, leading to the classic triad: microangiopathic hemolytic anemia (schistocytes on blood smear, low hemoglobin), thrombocytopenia (platelet consumption), and acute kidney injury. Nursing care is primarily supportive as there is no specific antidote for Shiga toxin. Critical interventions include careful fluid and electrolyte management, monitoring for and treating hyperkalemia, managing hypertension, and providing dialysis when indicated. Avoid antibiotics in suspected STEC infection as they may increase toxin release and worsen outcomes. Antimotility agents should also be avoided. Monitor complete blood counts daily for anemia and thrombocytopenia progression. Transfuse packed red blood cells for symptomatic anemia but use platelet transfusions cautiously as they may worsen thrombotic microangiopathy. Watch for extrarenal complications including CNS involvement (seizures, stroke), pancreatitis, and cardiac dysfunction. Most children recover kidney function within 2-3 weeks, but approximately 5-10% develop chronic kidney disease or end-stage kidney disease. Long-term follow-up should include blood pressure monitoring, urine protein assessment, and kidney function evaluation. Prevention focuses on food safety: cooking ground beef thoroughly, washing produce, avoiding unpasteurized dairy and juices, and proper hand hygiene."}, {"topic": "Pediatric Nephrology", "title": "Peritoneal Dialysis in Pediatric Patients: Nursing Considerations", "body": "Peritoneal dialysis (PD) is the preferred renal replacement therapy for infants and young children awaiting kidney transplantation. The peritoneal membrane serves as the dialysis surface, with dialysate instilled into the peritoneal cavity via a surgically placed catheter. PD offers several advantages in children: continuous gentle ultrafiltration that is better tolerated hemodynamically, preservation of residual kidney function, more liberal fluid and dietary intake, and the ability to perform exchanges at home allowing normal school attendance and activities. Two main modalities exist: continuous ambulatory peritoneal dialysis (CAPD) with manual exchanges 4-5 times daily, and automated peritoneal dialysis (APD) using a cycler machine overnight. Nursing responsibilities include comprehensive family education on aseptic technique, exchange procedures, catheter care, and recognition of complications. Peritonitis is the most serious complication, presenting with cloudy effluent, abdominal pain, and fever. Exit site infections require prompt treatment to prevent peritonitis. Other complications include catheter malfunction, hernias, gastroesophageal reflux from increased intra-abdominal pressure, and protein losses requiring nutritional supplementation. Adequate nutrition is critical as children on PD need 100-140% of recommended daily calories and adequate protein (1.2-1.5 g/kg/day) to support growth. Monitor growth parameters closely and coordinate with dietitians. Prescription adjustments may be needed based on ultrafiltration goals, solute clearance (Kt/V target >1.8 weekly), and residual kidney function. Regular assessment of catheter exit site, documentation of exchange volumes and times, and monitoring of monthly labs (electrolytes, hemoglobin, albumin, PTH) are essential nursing functions. Successful PD requires strong family engagement and 24/7 access to the dialysis team for troubleshooting."}, {"topic": "Pregnancy and Kidney Disease", "title": "Physiologic Changes in Pregnancy Affecting Kidney Function", "body": "During normal pregnancy, the kidneys undergo significant anatomic and physiologic changes. Renal plasma flow increases by 50-80% and GFR rises by 40-50%, beginning in the first trimester and peaking around 16-26 weeks. This hyperfiltration state results in lower serum creatinine (0.4-0.8 mg/dL) and BUN (8-10 mg/dL) compared to non-pregnant values. The kidneys increase in length by approximately 1 cm due to vascular engorgement and interstitial edema. The ureters dilate, particularly on the right side, due to progesterone-mediated smooth muscle relaxation and mechanical compression from the gravid uterus. This predisposes pregnant women to urinary stasis and increased risk of pyelonephritis. Sodium retention increases by 500-900 mEq during pregnancy, supporting the 40-50% expansion of plasma volume. Understanding these normal adaptations is critical for recognizing pathologic states - a creatinine of 1.0 mg/dL in pregnancy represents significant impairment, whereas it might be normal in a non-pregnant woman. Protein excretion may increase up to 300 mg/24 hours without indicating pathology. Blood pressure normally decreases in the first and second trimesters due to systemic vasodilation, then returns to baseline near term. Failure of BP to decrease or early elevation may indicate underlying kidney disease or risk for preeclampsia."}, {"topic": "Pregnancy and Kidney Disease", "title": "Preeclampsia vs Chronic Hypertension in Kidney Disease Patients", "body": "Distinguishing between chronic hypertension and preeclampsia in pregnant patients with CKD is essential for management and prognosis. Chronic hypertension is defined as BP \u2265140/90 mmHg present before pregnancy or diagnosed before 20 weeks gestation. Preeclampsia is new-onset hypertension after 20 weeks with proteinuria (\u2265300 mg/24 hours) or severe features including thrombocytopenia, renal insufficiency (creatinine >1.1 mg/dL or doubling), elevated liver enzymes, pulmonary edema, or cerebral/visual symptoms. Women with CKD have 25-50% risk of superimposed preeclampsia - preeclampsia developing on top of chronic hypertension or CKD. Warning signs include sudden worsening of hypertension, new or increasing proteinuria, rising creatinine, or development of severe features. Laboratory findings that favor preeclampsia over chronic hypertension alone include elevated uric acid (often disproportionately elevated), thrombocytopenia, elevated LDH, and schistocytes on peripheral smear. Management differs significantly: chronic hypertension is managed with oral antihypertensives to maintain BP <140/90, while preeclampsia with severe features requires magnesium sulfate for seizure prophylaxis, aggressive BP control, and often delivery regardless of gestational age. Low-dose aspirin 81 mg daily starting at 12 weeks reduces preeclampsia risk in high-risk women including those with CKD. Postpartum, women with preeclampsia need monitoring for at least 3 months and counseling about increased long-term cardiovascular and kidney disease risk."}, {"topic": "Pregnancy and Kidney Disease", "title": "Dialysis Management During Pregnancy in ESKD Patients", "body": "Pregnancy in patients with end-stage kidney disease on dialysis is high-risk but achievable with intensive management. The dialysis prescription must be significantly intensified compared to non-pregnant patients. Standard thrice-weekly hemodialysis is inadequate; instead, daily or near-daily dialysis totaling 20+ hours per week is recommended. The goal is to maintain predialysis BUN below 50 mg/dL (ideally <40 mg/dL), which mimics the low BUN of normal pregnancy and is associated with improved fetal outcomes. High BUN levels cause osmotic diuresis in the fetus, leading to polyhydramnios, which increases preterm labor risk. Fluid removal must be gentle to avoid intradialytic hypotension that could compromise uteroplacental perfusion. Ultrafiltration rates should be minimized, and dry weight should be adjusted frequently to accommodate pregnancy weight gain. Hemodialysis access should be well-functioning; fistulas are preferred over catheters to reduce infection risk. Erythropoiesis-stimulating agents are often needed at higher doses due to increased plasma volume and fetal iron demands. Iron supplementation (often IV) is required. Nutritional support is critical - protein intake should be 1.5-1.8 g/kg/day to support fetal growth and replace dialysis losses. Despite intensive dialysis, complications remain common: preterm delivery occurs in 50-80% of cases, intrauterine growth restriction in 30-50%, and polyhydramnios in up to 70%. Multidisciplinary care involving nephrology, maternal-fetal medicine, and neonatology is essential. Peritoneal dialysis can be continued but requires more frequent exchanges and careful monitoring for peritonitis, which carries high risk in pregnancy."}, {"topic": "Drug Dosing in Renal Failure", "title": "Understanding Renal Drug Clearance", "body": "Drugs are eliminated from the body through two primary pathways: renal (kidney) and hepatic (liver) clearance. In patients with chronic kidney disease (CKD), understanding which pathway dominates for each medication is critical for safe prescribing.\n\nRenally cleared drugs include: vancomycin, aminoglycosides (gentamicin, tobramycin), digoxin, gabapentin, pregabalin, levetiracetam, metformin, most beta-lactam antibiotics, and low molecular weight heparin. These medications require dose reduction or interval extension as GFR declines.\n\nHepatically cleared drugs include: diazepam, lorazepam, fentanyl, most statins (especially atorvastatin), warfarin, and many antidepressants. These typically do not require renal dose adjustment, though caution is still warranted in severe CKD due to altered protein binding and metabolism.\n\nThe Cockcroft-Gault equation or CKD-EPI formula estimates GFR to guide dosing decisions. General thresholds: GFR >60 mL/min (no adjustment), GFR 30-59 mL/min (moderate reduction), GFR 15-29 mL/min (significant reduction), GFR <15 mL/min or dialysis (major adjustment or avoidance).\n\nKey principle: When GFR decreases, the half-life of renally cleared drugs increases proportionally. A drug with a 2-hour half-life in normal renal function may have an 8-12 hour half-life in end-stage renal disease, leading to dangerous accumulation if dosing is not adjusted."}, {"topic": "Drug Dosing in Renal Failure", "title": "High-Risk Medications in CKD", "body": "Certain medications pose particular dangers in CKD patients and require special attention:\n\nNSAIDs (ibuprofen, naproxen, celecoxib): Contraindicated in CKD. They inhibit prostaglandin synthesis, causing afferent arteriole vasoconstriction and reduced renal blood flow. This can precipitate acute kidney injury on chronic kidney disease. Even short courses can be harmful. Use acetaminophen for pain instead.\n\nMetformin: First-line diabetes medication but contraindicated when eGFR <30 mL/min. Accumulation causes lactic acidosis with 50% mortality. Reduce dose when eGFR 30-45 mL/min and discontinue below this threshold. Hold during acute illness or before contrast procedures.\n\nNitrofurantoin: Used for UTIs but ineffective and dangerous in CKD. Requires adequate urinary concentrations for bactericidal activity, which cannot be achieved with reduced GFR. Also increases risk of peripheral neuropathy and pulmonary toxicity in CKD. Avoid when CrCl <30 mL/min. It may be used cautiously for uncomplicated cystitis when CrCl is 30-60 mL/min.\n\nBaclofen: Muscle relaxant that is renally eliminated. Can cause severe CNS toxicity including seizures, coma, and respiratory depression in CKD. Avoid entirely in dialysis patients; use extreme dose reduction (5mg daily) if absolutely necessary in moderate CKD.\n\nOpioids: Morphine, codeine, and meperidine produce active metabolites that accumulate in renal failure, causing prolonged sedation and respiratory depression. Fentanyl and methadone are preferred as they are hepatically metabolized without active renally-cleared metabolites.\n\nContrast dye: Iodinated contrast can cause contrast-induced nephropathy. Prevent with IV normal saline hydration (1 mL/kg/hr for 6-12 hours before and after), hold metformin, and use lowest possible contrast volume. Consider alternative imaging in severe CKD."}, {"topic": "Drug Dosing in Renal Failure", "title": "Dialysis and Drug Dosing Considerations", "body": "Hemodialysis significantly affects drug dosing for many medications. Understanding dialyzability determines whether to dose before, after, or independent of dialysis sessions.\n\nFactors affecting dialyzability:\n1. Molecular weight: Small molecules (<500 Daltons) are more easily removed\n2. Protein binding: Drugs >90% protein-bound are not dialyzable (warfarin, phenytoin)\n3. Water solubility: Water-soluble drugs are more dialyzable than lipid-soluble\n4. Volume of distribution: Drugs with large Vd reside in tissues and are less dialyzable\n\nHighly dialyzable drugs (dose AFTER hemodialysis): Vancomycin, aminoglycosides, gabapentin, pregabalin, most beta-lactam antibiotics, lithium, digoxin (partially).\n\nMinimally dialyzable drugs (dose independent of dialysis): Warfarin, heparin, most beta-blockers, calcium channel blockers, benzodiazepines, fentanyl.\n\nVancomycin dosing in hemodialysis: Use weight-based loading (20-25 mg/kg IV) followed by maintenance (10-15 mg/kg after each session) guided by AUC/MIC targets (400-600) or trough levels. Fixed 500-1000 mg dosing is outdated and risks under- or overdosing. Check levels before each session.\n\nAminoglycoside dosing: Use extended-interval dosing (e.g., gentamicin 2-3 mg/kg after each dialysis session). Monitor peak and trough levels to prevent ototoxicity and nephrotoxicity. Use extended-interval dosing (5-7 mg/kg once daily) with random level monitoring at 6-14 hours (Hartford nomogram). When a trough is checked, target <1 mcg/mL to minimize nephrotoxicity.\n\nPeritoneal dialysis considerations: Generally removes drugs less efficiently than hemodialysis due to slower clearance. Many medications can be dosed normally, but some (like vancomycin) may be given intraperitoneally for peritonitis treatment.\n\nGeneral rule: When uncertain about dialyzability, consult drug references or time doses after dialysis sessions for renally-cleared medications with narrow therapeutic indices."}, {"topic": "Acid-Base Disorders", "title": "Understanding Metabolic Acidosis: Types and Clinical Approach", "body": "Metabolic acidosis is characterized by low arterial pH (<7.35) and reduced serum bicarbonate (<22 mEq/L). The first step in evaluation is calculating the anion gap: AG = Na+ - (Cl- + HCO3-). A normal anion gap is 8-12 mEq/L, though this varies by laboratory. High anion gap metabolic acidosis occurs when unmeasured anions accumulate. Common causes include diabetic ketoacidosis (ketone bodies), lactic acidosis (lactate from tissue hypoxia), uremia (retained organic acids), and toxic ingestions (methanol, ethylene glycol, salicylates). Use the mnemonic MUDPILES to remember these causes. Normal anion gap (hyperchloremic) metabolic acidosis results from bicarbonate loss or impaired renal acid excretion. Causes include diarrhea (GI bicarbonate loss), renal tubular acidosis (defective renal acidification), and early CKD. The mnemonic HARDASS helps recall these etiologies. In nephrology nursing, recognizing the type of metabolic acidosis guides treatment. DKA requires insulin and fluid resuscitation to stop ketogenesis. Lactic acidosis needs treatment of the underlying cause (sepsis, hypoperfusion). RTA types require different approaches: Type 1 needs alkali therapy, Type 2 needs high-dose bicarbonate, and Type 4 may need potassium binders and fludrocortisone. Always assess compensation using Winter's formula for metabolic acidosis: expected PaCO2 = 1.5 \u00d7 HCO3- + 8 (\u00b12). If measured PaCO2 exceeds expected, a concurrent respiratory acidosis exists. If lower, concurrent respiratory alkalosis is present."}, {"topic": "Acid-Base Disorders", "title": "Respiratory Acid-Base Disorders and Renal Compensation", "body": "Respiratory acid-base disorders result from changes in alveolar ventilation affecting PaCO2. Respiratory acidosis (PaCO2 >45 mmHg, pH <7.35) occurs from hypoventilation due to COPD exacerbation, opioid overdose, neuromuscular disease, or chest wall abnormalities. The kidneys compensate by increasing bicarbonate reabsorption, but this takes 3-5 days for full effect. In acute respiratory acidosis, bicarbonate rises 1 mEq/L per 10 mmHg PaCO2 increase. In chronic respiratory acidosis, bicarbonate rises 3-4 mEq/L per 10 mmHg increase. Respiratory alkalosis (PaCO2 <35 mmHg, pH >7.45) results from hyperventilation due to anxiety, pain, hypoxemia, pulmonary embolism, or mechanical ventilation. Renal compensation decreases bicarbonate reabsorption. In acute respiratory alkalosis, bicarbonate falls 2 mEq/L per 10 mmHg PaCO2 decrease. In chronic respiratory alkalosis, bicarbonate falls 4-5 mEq/L per 10 mmHg decrease. For nephrology nurses, understanding compensation is critical when evaluating CKD or dialysis patients with concurrent pulmonary disease. A patient with COPD may have chronic respiratory acidosis with appropriate renal compensation (elevated bicarbonate). If bicarbonate is lower than expected, a concurrent metabolic acidosis (e.g., from uremia or lactic acidosis) should be suspected. Conversely, if bicarbonate is higher than expected, metabolic alkalosis (e.g., from diuretics or vomiting) may coexist. Never interpret blood gases in isolation\u2014always correlate with clinical context, electrolytes, and renal function. Treatment focuses on the underlying cause: bronchodilators and steroids for COPD, reversing sedation for opioid overdose, or adjusting ventilator settings for iatrogenic causes."}, {"topic": "Acid-Base Disorders", "title": "Renal Tubular Acidosis and Bicarbonate Management in CKD", "body": "Renal tubular acidosis (RTA) comprises disorders of renal acidification with normal anion gap metabolic acidosis. Type 1 (distal) RTA involves defective hydrogen ion secretion in the distal nephron. Key features: urine pH >5.5 despite systemic acidosis, hypokalemia, nephrolithiasis (from hypercalciuria and low citrate), and nephrocalcinosis. Causes include autoimmune diseases (Sj\u00f6gren's, lupus), amphotericin B toxicity, and hereditary forms. Treatment requires alkali therapy (sodium bicarbonate or potassium citrate) at 1-3 mEq/kg/day. Type 2 (proximal) RTA involves impaired bicarbonate reabsorption in the proximal tubule. Key features: urine pH variable (can acidify when bicarbonate is depleted), hypokalemia, and association with Fanconi syndrome (glycosuria, phosphaturia, aminoaciduria). Treatment requires bicarbonate 3-10 mEq/kg/day in divided doses (start 3-5, titrate up to 10 as needed) because administered bicarbonate is wasted in urine until the reabsorption threshold is exceeded. Type 4 RTA involves aldosterone deficiency or resistance. Key features: hyperkalemia, urine pH <5.5 (can acidify), and impaired ammonium excretion. Causes include diabetic nephropathy, ACE inhibitors, ARBs, NSAIDs, and adrenal insufficiency. Treatment includes addressing hyperkalemia (diet, potassium binders), fludrocortisone if deficient, and modest alkali if needed. In CKD, metabolic acidosis develops as GFR declines below 60 mL/min/1.73m\u00b2. The kidneys lose capacity to excrete acid and regenerate bicarbonate. KDIGO guidelines recommend oral bicarbonate supplementation when serum bicarbonate is persistently <22 mEq/L, targeting 22-26 mEq/L. Benefits include slowing CKD progression, reducing muscle wasting, and improving bone health. Sodium bicarbonate tablets (650 mg = 7.7 mEq) are commonly used. Monitor for sodium overload, hypertension, and edema. In dialysis patients, bicarbonate concentration in dialysate can be adjusted to correct acidosis between sessions."}, {"topic": "Fluid and Electrolyte Emergencies", "title": "Hyperkalemia: Recognition and Emergency Management", "body": "Hyperkalemia is a life-threatening electrolyte emergency requiring immediate recognition and intervention. Normal potassium ranges from 3.5-5.0 mEq/L, with levels above 6.5 mEq/L or any level with ECG changes constituting an emergency. ECG changes progress predictably: peaked T waves appear first, followed by PR interval prolongation, QRS widening, sine wave pattern, and ultimately ventricular fibrillation or asystole. Emergency treatment follows a three-pronged approach. First, stabilize cardiac membranes with IV calcium gluconate (1 gram over 2-3 minutes), which works within minutes but does not lower potassium levels. Second, shift potassium intracellularly using insulin with dextrose (10 units regular insulin IV with 25g dextrose), sodium bicarbonate in acidotic patients, or nebulized albuterol. These measures lower potassium by 0.5-1.5 mEq/L within 15-30 minutes. Third, remove potassium from the body using loop diuretics if renal function permits, potassium binders like sodium polystyrene sulfonate or newer agents, or emergent hemodialysis for severe cases. Nurses must continuously monitor cardiac rhythm, verify IV access, and prepare for rapid sequence intervention. Prevention includes medication review (ACE inhibitors, ARBs, potassium-sparing diuretics), dietary counseling, and ensuring adherence to dialysis schedules."}, {"topic": "Fluid and Electrolyte Emergencies", "title": "Hyponatremia and Hypernatremia: Safe Correction Principles", "body": "Sodium disorders require careful assessment and measured correction to prevent neurologic complications. Hyponatremia (sodium <135 mEq/L) is classified by volume status: hypovolemic (fluid loss), euvolemic (SIADH), or hypervolemic (heart failure, cirrhosis). SIADH presents with hyponatremia, low serum osmolality, and inappropriately concentrated urine despite euvolemia. The critical principle in hyponatremia management is avoiding overly rapid correction. Chronic hyponatremia corrected too quickly can cause osmotic demyelination syndrome (central pontine myelinolysis), resulting in irreversible neurologic damage including paralysis, dysarthria, and locked-in syndrome. Sodium should not increase more than 8-10 mEq/L in 24 hours or 18 mEq/L in 48 hours. Severe symptomatic hyponatremia with seizures requires cautious hypertonic saline (3%) administration. Hypernatremia (sodium >145 mEq/L) typically results from water loss exceeding sodium loss, as seen in diabetes insipidus or inadequate water intake. Treatment involves gradual free water replacement, calculating the water deficit and correcting over 48-72 hours. Rapid correction of hypernatremia can cause cerebral edema. Nurses must monitor neurologic status, strict intake/output, daily weights, and serial sodium levels. Both conditions require identifying and treating the underlying cause while maintaining careful fluid balance."}, {"topic": "Fluid and Electrolyte Emergencies", "title": "Calcium, Magnesium, and Phosphate Emergencies", "body": "Calcium, magnesium, and phosphate disorders frequently occur together and require integrated management. Hypocalcemia (total calcium <8.5 mg/dL or ionized <4.5 mg/dL) presents with neuromuscular irritability including perioral paresthesias, muscle cramps, tetany, Chvostek sign (facial muscle contraction when tapping facial nerve), and Trousseau sign (carpal spasm with BP cuff inflation). ECG shows prolonged QT interval increasing arrhythmia risk. Emergency treatment involves IV calcium gluconate or chloride for severe symptoms. Hypercalcemia (calcium >10.5 mg/dL, crisis >14 mg/dL) causes shortened QT, confusion, polyuria, constipation, and renal stones. Treatment includes aggressive IV isotonic saline for volume expansion, calcitonin for rapid effect, IV bisphosphonates for sustained reduction, and dialysis for severe cases. Hypermagnesemia (>2.6 mg/dL) typically occurs in renal failure patients receiving magnesium-containing products. Early signs include loss of deep tendon reflexes, progressing to hypotension, bradycardia, respiratory depression, and cardiac arrest. Treatment involves IV calcium gluconate to antagonize effects and dialysis. Hyperphosphatemia commonly occurs in CKD, causing hypocalcemia through calcium-phosphate binding and triggering secondary hyperparathyroidism. Management includes phosphate binders (calcium acetate, sevelamer) taken with meals and dietary phosphate restriction. Nurses must monitor ionized calcium levels, assess neuromuscular symptoms, and coordinate timing of medications with meals for optimal phosphate binding."}, {"topic": "Transplant Pharmacology", "title": "Calcineurin Inhibitors: Tacrolimus and Cyclosporine", "body": "Calcineurin inhibitors (CNIs) form the backbone of most transplant immunosuppression regimens. Both tacrolimus and cyclosporine work by inhibiting calcineurin, a phosphatase enzyme critical for T-cell activation. When T-cells encounter antigens, calcineurin dephosphorylates NFAT (nuclear factor of activated T-cells), allowing it to enter the nucleus and transcribe IL-2 and other cytokines. CNIs block this pathway, preventing T-cell proliferation and activation.\n\nTACROLIMUS: Binds to FKBP-12 (FK506-binding protein), forming a complex that inhibits calcineurin. It is 10-100 times more potent than cyclosporine. Key monitoring parameters include trough levels (typically 8-12 ng/mL early post-transplant, 5-10 ng/mL long-term), serum creatinine, blood glucose, and electrolytes (especially potassium and magnesium). Major adverse effects include nephrotoxicity (dose-dependent, reversible with dose reduction), neurotoxicity (tremor, headache, seizures in severe cases), hyperglycemia and new-onset diabetes after transplant (NODAT occurs in 10-20% of patients), hyperkalemia, and hypomagnesemia. Tacrolimus should be taken consistently with or without food, and grapefruit must be avoided.\n\nCYCLOSPORINE: Binds to cyclophilin, forming a complex that inhibits calcineurin. Available in immediate-release and modified formulations (Neoral, Gengraf). Monitoring includes trough levels (variable by institution), creatinine, blood pressure, and lipids. Distinctive side effects include gingival hyperplasia (up to 30% of patients), hirsutism (excessive hair growth), hypertension, and hyperlipidemia. Like tacrolimus, it causes nephrotoxicity and requires avoidance of grapefruit.\n\nDRUG INTERACTIONS: Both CNIs are metabolized by CYP3A4 and are P-glycoprotein substrates. Strong CYP3A4 inhibitors (azole antifungals, macrolide antibiotics, diltiazem, verapamil, grapefruit) significantly increase levels and toxicity risk. CYP3A4 inducers (rifampin, phenytoin, carbamazepine, St. John's wort) decrease levels and increase rejection risk. Always consult pharmacy before adding new medications.\n\nNURSING CONSIDERATIONS: Administer at consistent times (usually every 12 hours), draw trough levels 12 hours after the last dose and immediately before the next dose, monitor for signs of nephrotoxicity (rising creatinine, decreased urine output), assess for neurotoxicity symptoms, check blood glucose regularly, and educate patients about drug interactions and the importance of adherence."}, {"topic": "Transplant Pharmacology", "title": "Antimetabolites and mTOR Inhibitors", "body": "ANTIMETABOLITES work by interfering with purine synthesis, affecting rapidly dividing cells including activated lymphocytes.\n\nMYCOPHENOLATE MOFETIL (MMF): Converted to mycophenolic acid, which inhibits inosine monophosphate dehydrogenase (IMPDH), blocking de novo purine synthesis. Lymphocytes depend on this pathway, making them selectively targeted. Standard dosing is 500-1500 mg twice daily. Common side effects include GI symptoms (diarrhea, nausea, abdominal pain - often improved by taking with food or dividing doses), bone marrow suppression (leukopenia, anemia, thrombocytopenia), and increased infection risk. Monitoring includes complete blood count (CBC) weekly initially, then monthly; assess for signs of infection and bleeding. MMF is teratogenic and requires effective contraception. It may be available as enteric-coated mycophenolate sodium (Myfortic), which may reduce GI side effects.\n\nAZATHIOPRINE: An older antimetabolite, prodrug converted to 6-mercaptopurine, which interferes with DNA and RNA synthesis. Less commonly used now due to MMF's superior efficacy and tolerability, but still used in some protocols or when MMF is not tolerated. Dosing is typically 1-2 mg/kg/day. Major adverse effect is bone marrow suppression, which can be severe. Patients with low thiopurine methyltransferase (TPMT) activity are at higher risk for toxicity. Monitoring includes CBC and liver function tests. Drug interactions include allopurinol (increases azathioprine toxicity - avoid combination or reduce azathioprine dose by 75%).\n\nmTOR INHIBITORS: Sirolimus (rapamycin) and everolimus block the mammalian target of rapamycin (mTOR), a kinase involved in cell cycle progression.\n\nSIROLIMUS: Used as maintenance immunosuppression, particularly in patients with CNI nephrotoxicity or certain malignancies (Kaposi sarcoma, renal cell carcinoma). Does not cause nephrotoxicity, making it useful for CNI-sparing or CNI-free regimens. However, it has significant side effects including hyperlipidemia (elevated cholesterol and triglycerides in 30-50% of patients), thrombocytopenia and anemia, impaired wound healing (avoid in early post-operative period), proteinuria, and increased risk of lymphocele. Monitoring includes lipid panel, CBC, sirolimus trough levels (target 4-12 ng/mL depending on protocol), and urinalysis for protein. Like CNIs, it is metabolized by CYP3A4 and has similar drug interactions.\n\nNURSING CONSIDERATIONS: For MMF, administer on empty stomach if tolerated (or with food to reduce GI upset), monitor CBC regularly, educate about infection prevention and contraception requirements. For sirolimus, monitor lipids and CBC, assess wound healing, avoid in immediate post-operative period, and counsel about drug interactions. Both require adherence education and regular laboratory monitoring."}, {"topic": "Transplant Pharmacology", "title": "Induction Agents and Corticosteroids", "body": "INDUCTION THERAPY provides intense immunosuppression at the time of transplant to prevent early acute rejection and may allow delayed introduction or lower doses of maintenance immunosuppressants.\n\nBASILIXIMAB (Simulect): A chimeric (human-mouse) monoclonal antibody targeting the alpha chain of the IL-2 receptor (CD25) on activated T-cells. By blocking IL-2 binding, it prevents T-cell proliferation. Given as IV infusion: 20 mg on day 0 (before transplant) and day 4. Does not cause cytokine release syndrome, so premedication is not typically required. Well-tolerated with minimal side effects. Contraindicated in patients with known hypersensitivity. Provides coverage for the first 4-6 weeks post-transplant.\n\nANTITHYMOCYTE GLOBULIN (ATG): Polyclonal antibodies derived from rabbit or horse immunized with human T-cells. Causes profound T-cell depletion through complement-mediated lysis and apoptosis. Used for induction in high-risk patients (high PRA, retransplant, delayed graft function) and for treatment of acute rejection. Dosing varies (typically 1-1.5 mg/kg/day for 3-5 days). Requires premedication with acetaminophen, diphenhydramine, and often corticosteroids to prevent infusion reactions. Side effects include cytokine release syndrome (fever, chills, hypotension during infusion), leukopenia, thrombocytopenia, and increased infection risk (particularly CMV, fungal). Requires monitoring of CBC with differential, CD3 counts to assess T-cell depletion, and infection surveillance.\n\nCORTICOSTEROIDS: Prednisone and methylprednisolone have been cornerstone immunosuppressants since the early days of transplantation. They work through multiple mechanisms: inhibiting cytokine production, reducing lymphocyte proliferation, and decreasing inflammation.\n\nUSES: High-dose IV methylprednisolone for acute rejection treatment (pulse therapy: 500-1000 mg daily for 3 days), oral prednisone for maintenance (typically started at 20-30 mg/day and tapered to 5-10 mg/day long-term, or discontinued in steroid-free protocols).\n\nADVERSE EFFECTS (dose and duration dependent): Metabolic - hyperglycemia, weight gain, fluid retention, dyslipidemia; Musculoskeletal - osteoporosis, osteonecrosis (especially femoral head), myopathy; Dermatologic - thin skin, easy bruising, poor wound healing, acne; Ophthalmic - cataracts, glaucoma; Endocrine - adrenal suppression (requires stress-dose steroids for surgery/illness if on chronic therapy), Cushingoid appearance; GI - peptic ulcer disease, gastritis; Neuropsychiatric - mood changes, insomnia, psychosis (rare); Immunologic - increased infection risk.\n\nNURSING CONSIDERATIONS: Monitor blood glucose (especially in diabetics or those on tacrolimus), assess bone density (DEXA scans), ensure calcium and vitamin D supplementation, consider bisphosphonate prophylaxis for long-term therapy, educate about never stopping abruptly (adrenal crisis risk), provide stress-dose education for illness/surgery, monitor for signs of infection, and assess mood and sleep patterns. Tapering should be gradual to allow adrenal recovery."}];
if (typeof module !== 'undefined' && module.exports) module.exports = {ORIG_QUESTIONS, ORIG_FLASHCARDS, ORIG_LESSONS};
